// A socket io server for bot nodes to connect to and receive commands from the master node
// --------------------------------------------------------

const express = require("express");
const cors = require("cors");
const app = express();
const http = require("http").createServer(app);
const io = require("socket.io")(http, { path: '/master/socket.io/' });
const MasterConfig = require('./deployment.config').Master;

const nodes = {};

function removeNodeTasks(node) {
  // remove all tasks
  for (const task of node.tasks) {
    if (task.stream) {
      task.res.end();
    } else {
      task.res.status(500).json({ error: 'Node is offline, please retry later.' });
    }
  }
  node.tasks = [];
}

io.on("connection", (socket) => {
  const ip = (socket.handshake.headers['x-forwarded-for'] || '').split(',')[0];
  const node = nodes[socket.id] = { ip, socket, tasks: [], config: {}, status: 'unknown' };

  socket.on("config", (config) => {
    node['config'] = config;
    console.log(`[${node.ip}]`, 'connected', 'ip', ip, 'config', config);
  });

  socket.on('status', ({ status }) => {
    node.status = status;
    console.log(`[${node.ip}]`, 'status', status);

    if (status === 'offline') {
      removeNodeTasks(node);
    }
  });

  socket.on("message", (data) => {
    const message = typeof data === 'string' ? JSON.parse(data) : data;
    const task = node.tasks.find((item) => item.key === message.key);
    if (!task) {
      socket.emit('remove_task', { key: message.key });
      return;
    }

    // remove spaces from beginning of output
    if (task.outputBuffer.length === 0) {
      message.output = message.output.trimLeft();
    }
    task.outputBuffer.push(message.output);
    // make OpenAI style response
    if (task.stream) {
      const response = { id: message.key, object: 'chat.completion', model: task.model, created: task.created, choices: [
        { index: 0, delta: { role: 'assistant', content: message.output }, finish_reason: message.done ? 'stop': null }
      ]};
      task.res.write(`data: ${JSON.stringify(response)}\n\n`);
      if (message.done) {
        task.res.write('data: [DONE]\n\n');
        task.res.end();
      }
    } else {
      if (message.done) {
        const response = { id: message.key, object: 'chat.completion', model: task.model, created: task.created, choices: [
          { index: 0, message: { role: 'assistant', content: task.outputBuffer.join('') }, finish_reason: 'stop' }
        ]};
        task.res.json(response);
      }
    }
  });

  socket.on("disconnect", () => {
    removeNodeTasks(node);
    delete nodes[socket.id];
    console.log(`[${node.ip}]`, 'disconnected');
  });
});

function findAvailableNode(task) {
  // find node with least tasks
  let minTasks = Infinity;
  let minNode = null;
  for (const [id, node] of Object.entries(nodes)) {
    if (task.model && node.config.model.id !== task.model) {
      continue;
    }
    if (!task.model && node.config.model.id !== MasterConfig.defaultModel) {
      continue;
    }
    if (node.status !== 'online') {
      continue;
    }
    if (node.tasks.length < minTasks) {
      minTasks = node.tasks.length;
      minNode = node;
    }
  }

  if (minNode && !task.model) {
    // assign model to task
    task.model = minNode.config.model.id;
  }
  return minNode;
}

// handle POST /chat/completions
app.use(express.json());
app.use(cors());

app.get('/v1/models', (req, res) => {
  const models = [];
  for (const [id, node] of Object.entries(nodes)) {
    const model = node.config.model;
    if (models.find(m => m.id === model.id)) {
      continue;
    }
    model.object = 'model';
    model.owned_by = 'organization-owner';
    models.push(model);
  }
  models.sort((a, b) => a.id == MasterConfig.defaultModel ? -1 : 0)
  res.json({ data: models, object: 'list'});
});

app.get('/v1/nodes', (req, res) => {
  const data = [];
  for (const [id, node] of Object.entries(nodes)) {
    data.push({id, ip: node.ip, config: node.config, tasks: node.tasks.length});
  }
  res.json({ data, object: 'list'});
});

app.post('/v1/chat/completions', (req, res) => {
  // verify bearer apiKey from authorization header
  const apiKey = req.headers.authorization?.toLowerCase().replace('bearer ', '');
  if (MasterConfig.apiKeys.indexOf(apiKey) === -1) {
    res.status(401).json({ error: 'Invalid API key.\n' });
    return;
  }

  const ip = (req.headers['x-forwarded-for'] || '').split(',')[0];
  const task = req.body;
  if (!task.messages || task.messages.length === 0) {
    res.status(400).json({ error: '`messages` is required.\n' });
    return;
  }

  task.max_tokens = task.max_tokens || task.max_new_tokens;
  task.input = task.messages[task.messages.length - 1].content.trim();
  task.key = Math.random().toString(36).substring(2);

  // for Will's test
  if (task.model === 'gpt-3.5-turbo') {
    task.model = null;
  }
  // if task.stop is string, convert to array
  if (task.stop && !Array.isArray(task.stop)) {
    task.stop = [task.stop];
  }

  const node = findAvailableNode(task);
  if (!node) {
    res.status(500).json({ error: `No available node for model ${task.model}` });
    return;
  }
  // send task to node
  node.socket.emit('add_task', task);
  console.log(`[${node.ip}]`, '[INPUT]', task.key, task.model, task.input, 'from', ip, 'apiKey', apiKey);

  // add task to nodes
  task.res = res;
  task.outputBuffer = [];
  task.created = parseInt(Date.now()/1000);
  node['tasks'].push(task);

  // remove task from node when socket is closed
  req.socket.on('close', () => {
    node.socket.emit('remove_task', { key: task.key });
    console.log(`[${node.ip}]`, '[OUTPUT]', task.key, 'tokens', task.outputBuffer.length, task.outputBuffer.join(''));
    // remove task from node
    node.tasks = node.tasks.filter(t => t.key !== task.key);
  });

  if (task.stream) {
    res.writeHead(200, {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
    });
  }
});


// run app
const port = MasterConfig.port || process.env.PORT || 3010;
http.listen(port, () => {
  console.log(`listening on *:${port}`);
});

// Socket IO node
// --------------------------------------------------------

const NodeConfig = require(process.argv[2] || './deployment.config').Node;
const axios = require('axios');

let currentStatus = 'offline';
let pendingStatus = false;
let modelId = null;
const runningTasks = {};


function updateNodeStatus(newStatus) {
  if (newStatus === currentStatus) {
    return;
  }
  currentStatus = newStatus;
  socket.emit('status', {status: currentStatus});
  console.log('model', modelId, 'status', currentStatus);
}

function checkNodeStatus() {
  if (pendingStatus) {
    return;
  }

  const taskCount = Object.keys(runningTasks).length;
  if (taskCount > 0) {
    console.log('model', modelId, 'running tasks', taskCount);
  }

  const url = NodeConfig.inferenceServerUrl + '/v1/models';
  // If timeout, it means the inference server is not running
  pendingStatus = true;
  axios.get(url, {timeout: 15 * 1000}).then((response) => {
    modelId = response.data.data[0].id;
    updateNodeStatus('online');
  }).catch((error) => {
    updateNodeStatus('offline');
  }).finally(() => {
    pendingStatus = false;
  });
}

checkNodeStatus();
setInterval(checkNodeStatus, NodeConfig.pingInterval || 3000);


const io = require('socket.io-client');
const socket = io(NodeConfig.masterServerUrl, { path: '/master/socket.io/', query: {} });
const outputInterval = NodeConfig.outputInterval || 50;

function isBreakable(content) {
  if ('.!?;。！？；'.includes(content)) {
    return true;
  }
  return false;
}

function addOutputToTask(key, content) {
  if (!runningTasks[key]) {
    console.error('add output to invalid task', key);
    return;
  }

  const task = runningTasks[key];
  task.outputTokens += 1;
  task.outputBuffer.push(content);

  if (Date.now() - task.lastOutputTimestamp >= outputInterval || isBreakable(content)) {
    socket.emit('message', {key, output: task.outputBuffer.join(''), count: task.outputBuffer.length, done: false});
    task.outputBuffer = [];
    task.lastOutputTimestamp = Date.now();
  }
}

function finishTask(key) {
  if (!runningTasks[key]) {
    console.error('finish invalid task', key);
    return;
  }

  const task = runningTasks[key];
  socket.emit('message', {key, output: task.outputBuffer.join(''), done: true, tokens: task.outputTokens});
  delete runningTasks[key];
}

socket.on('connect', () => {
  console.log('connected to', NodeConfig.masterServerUrl);
  socket.emit('config', {model: NodeConfig.model, gpu: NodeConfig.gpu, memory: NodeConfig.memory});
  socket.emit('status', {status: currentStatus});
});

socket.on('add_task', (task) => {
  if (!task.key || runningTasks[task.key]) {
    console.error('add_task', 'invalid key');
    return;
  }

  const data = {
    "model": modelId,
    "messages": task.messages,
    "max_tokens": task.max_tokens,
    "temperature": task.temperature || 0.3,
    "top_p": task.top_p,
    "stop": task.stop,
    "presence_penalty": task.presence_penalty,
    "frequency_penalty": task.frequency_penalty,
    "stream": true
  };

  const timeout = 1000 * 60 * 2;
  const controller = new AbortController();
  const params = {
    responseType: 'stream',
    timeout,
    signal: controller.signal
  };

  runningTasks[task.key] = {
    controller,
    data,
    outputTokens: 0,
    outputBuffer: [],
    lastOutputTimestamp: Date.now()
  };

  axios.post(NodeConfig.inferenceServerUrl + '/v1/chat/completions', data, params).then((response) => {
    let buffer = [];
    response.data.on('data', (data) => {
      // append data to buffer, split by line, remove empty lines
      buffer.push(data.toString());
      buffer = buffer.join('').split('\n');

      // the last line must be ends with a new line
      while (buffer.length > 1) {
        const line = buffer.shift().trim();
        if (!line) {
          continue;
        }

        // remove data: prefix
        const message = line.replace(/^data: /, '');
        if (message === '[DONE]') {
          continue; // Stream finished
        }

        // try to parse message as JSON
        try {
          const parsed = JSON.parse(message);
          const choice = parsed.choices[0];
          const delta = choice.delta;
          if (delta.content?.length) {
            addOutputToTask(task.key, delta.content);
          }
        } catch (error) {
          console.error('Could not JSON parse stream message', message, error);
        }
      }
    });

    response.data.on('end', () => {
      finishTask(task.key);
    });
  }).catch((error) => {
    console.error('error', error);
    delete runningTasks[task.key];
  });
});

socket.on('remove_task', (task) => {
  if (!task.key || !runningTasks[task.key]) {
    return;
  }
  runningTasks[task.key].controller.abort();
  delete runningTasks[task.key];
});

socket.on('disconnect', () => {
  console.log('disconnected');
});

socket.on('error', (error) => {
  console.error('error', error);
});

