/**
 * SpiffsGenerator 类
 * 模仿 spiffs_assets_gen.py 的功能，用于在浏览器端生成 assets.bin 文件
 * 
 * 文件格式：
 * {
 *     total_files: int (4字节)          // 文件总数
 *     checksum: int (4字节)            // 校验和
 *     combined_data_length: int (4字节) // 数据总长度
 *     mmap_table: [                    // 文件映射表
 *         {
 *             name: char[32]           // 文件名 (32字节)
 *             size: int (4字节)        // 文件大小
 *             offset: int (4字节)      // 文件偏移量 
 *             width: short (2字节)     // 图片宽度
 *             height: short (2字节)    // 图片高度
 *         }
 *         ...
 *     ]
 *     file_data: [                     // 文件数据
 *         0x5A 0x5A + file1_data      // 每个文件前面加0x5A5A标识
 *         0x5A 0x5A + file2_data
 *         ...
 *     ]
 * }
 */

class SpiffsGenerator {
  constructor() {
    this.files = []
    this.textEncoder = new TextEncoder()
  }

  /**
   * 添加文件
   * @param {string} filename - 文件名
   * @param {ArrayBuffer} data - 文件数据
   * @param {Object} options - 可选参数 {width?, height?}
   */
  addFile(filename, data, options = {}) {
    if (filename.length > 32) {
      console.warn(`Filename "${filename}" exceeds 32 bytes and will be truncated`)
    }

    this.files.push({
      filename,
      data,
      size: data.byteLength,
      width: options.width || 0,
      height: options.height || 0
    })
  }

  /**
   * 从图片文件获取尺寸信息
   * @param {ArrayBuffer} imageData - 图片数据
   * @returns {Promise<Object>} {width, height}
   */
  async getImageDimensions(imageData) {
    return new Promise((resolve) => {
      try {
        const blob = new Blob([imageData])
        const url = URL.createObjectURL(blob)
        const img = new Image()

        img.onload = () => {
          URL.revokeObjectURL(url)
          resolve({ width: img.width, height: img.height })
        }

        img.onerror = () => {
          URL.revokeObjectURL(url)
          resolve({ width: 0, height: 0 })
        }

        img.src = url
      } catch (error) {
        resolve({ width: 0, height: 0 })
      }
    })
  }

  /**
   * 检查是否为特殊图片格式 (.sjpg, .spng, .sqoi)
   * @param {string} filename - 文件名
   * @param {ArrayBuffer} data - 文件数据
   * @returns {Object} {width, height}
   */
  parseSpecialImageFormat(filename, data) {
    const ext = filename.toLowerCase().split('.').pop()

    if (['.sjpg', '.spng', '.sqoi'].includes('.' + ext)) {
      try {
        // 特殊格式的头部结构：偏移14字节后是宽度和高度（各2字节，小端序）
        const view = new DataView(data)
        const width = view.getUint16(14, true)  // 小端序
        const height = view.getUint16(16, true) // 小端序
        return { width, height }
      } catch (error) {
        console.warn(`Failed to parse special image format: ${filename}`, error)
      }
    }

    return { width: 0, height: 0 }
  }

  /**
   * 将32位整数转换为小端序字节数组
   * @param {number} value - 整数值
   * @returns {Uint8Array} 4字节的小端序数组
   */
  packUint32(value) {
    const bytes = new Uint8Array(4)
    bytes[0] = value & 0xFF
    bytes[1] = (value >> 8) & 0xFF
    bytes[2] = (value >> 16) & 0xFF
    bytes[3] = (value >> 24) & 0xFF
    return bytes
  }

  /**
   * 将16位整数转换为小端序字节数组
   * @param {number} value - 整数值
   * @returns {Uint8Array} 2字节的小端序数组
   */
  packUint16(value) {
    const bytes = new Uint8Array(2)
    bytes[0] = value & 0xFF
    bytes[1] = (value >> 8) & 0xFF
    return bytes
  }

  /**
   * 将字符串打包为固定长度的二进制数据
   * @param {string} string - 输入字符串
   * @param {number} maxLen - 最大长度
   * @returns {Uint8Array} 打包后的二进制数据
   */
  packString(string, maxLen) {
    const bytes = new Uint8Array(maxLen)
    const encoded = this.textEncoder.encode(string)

    // 复制字符串数据，确保不超过最大长度
    const copyLen = Math.min(encoded.length, maxLen)
    bytes.set(encoded.slice(0, copyLen), 0)

    // 剩余字节为0填充
    return bytes
  }

  /**
   * 计算校验和
   * @param {Uint8Array} data - 数据
   * @returns {number} 16位校验和
   */
  computeChecksum(data) {
    let checksum = 0
    for (let i = 0; i < data.length; i++) {
      checksum += data[i]
    }
    return checksum & 0xFFFF
  }

  /**
   * 对文件进行排序
   * @param {Array} files - 文件列表
   * @returns {Array} 排序后的文件列表
   */
  sortFiles(files) {
    return files.slice().sort((a, b) => {
      const extA = a.filename.split('.').pop() || ''
      const extB = b.filename.split('.').pop() || ''

      if (extA !== extB) {
        return extA.localeCompare(extB)
      }

      const nameA = a.filename.replace(/\.[^/.]+$/, '')
      const nameB = b.filename.replace(/\.[^/.]+$/, '')
      return nameA.localeCompare(nameB)
    })
  }

  /**
   * 生成 assets.bin 文件
   * @param {Function} progressCallback - 进度回调函数
   * @returns {Promise<ArrayBuffer>} 生成的 assets.bin 数据
   */
  async generate(progressCallback = null) {
    if (this.files.length === 0) {
      throw new Error('No files to package')
    }

    if (progressCallback) progressCallback(0, 'Starting to package files...')

    // 排序文件
    const sortedFiles = this.sortFiles(this.files)
    const totalFiles = sortedFiles.length

    // 处理文件信息并获取图片尺寸
    const fileInfoList = []
    let mergedDataSize = 0

    for (let i = 0; i < sortedFiles.length; i++) {
      const file = sortedFiles[i]
      let width = file.width
      let height = file.height

      if (progressCallback) {
        progressCallback(10 + (i / totalFiles) * 30, `Processing file: ${file.filename}`)
      }

      // 如果没有提供尺寸信息，尝试自动获取
      if (width === 0 && height === 0) {
        // 先检查特殊图片格式
        const specialDimensions = this.parseSpecialImageFormat(file.filename, file.data)
        if (specialDimensions.width > 0 || specialDimensions.height > 0) {
          width = specialDimensions.width
          height = specialDimensions.height
        } else {
          // 尝试作为普通图片解析
          const ext = file.filename.toLowerCase().split('.').pop()
          if (['png', 'jpg', 'jpeg', 'gif', 'bmp', 'webp'].includes(ext)) {
            const dimensions = await this.getImageDimensions(file.data)
            width = dimensions.width
            height = dimensions.height
          }
        }
      }

      fileInfoList.push({
        filename: file.filename,
        data: file.data,
        size: file.size,
        offset: mergedDataSize,
        width,
        height
      })

      mergedDataSize += 2 + file.size // 2字节前缀 + 文件数据
    }

    if (progressCallback) progressCallback(40, 'Building file mapping table...')

    // 构建映射表
    const mmapTableSize = totalFiles * (32 + 4 + 4 + 2 + 2) // name + size + offset + width + height
    const mmapTable = new Uint8Array(mmapTableSize)
    let mmapOffset = 0

    for (const fileInfo of fileInfoList) {
      // 文件名 (32字节)
      mmapTable.set(this.packString(fileInfo.filename, 32), mmapOffset)
      mmapOffset += 32

      // 文件大小 (4字节)
      mmapTable.set(this.packUint32(fileInfo.size), mmapOffset)
      mmapOffset += 4

      // 文件偏移 (4字节)
      mmapTable.set(this.packUint32(fileInfo.offset), mmapOffset)
      mmapOffset += 4

      // 图片宽度 (2字节)
      mmapTable.set(this.packUint16(fileInfo.width), mmapOffset)
      mmapOffset += 2

      // 图片高度 (2字节)  
      mmapTable.set(this.packUint16(fileInfo.height), mmapOffset)
      mmapOffset += 2
    }

    if (progressCallback) progressCallback(60, 'Merging file data...')

    // 合并文件数据
    const mergedData = new Uint8Array(mergedDataSize)
    let mergedOffset = 0

    for (let i = 0; i < fileInfoList.length; i++) {
      const fileInfo = fileInfoList[i]

      if (progressCallback) {
        progressCallback(60 + (i / totalFiles) * 20, `Merging file: ${fileInfo.filename}`)
      }

      // 添加0x5A5A前缀
      mergedData[mergedOffset] = 0x5A
      mergedData[mergedOffset + 1] = 0x5A
      mergedOffset += 2

      // 添加文件数据
      mergedData.set(new Uint8Array(fileInfo.data), mergedOffset)
      mergedOffset += fileInfo.size
    }

    if (progressCallback) progressCallback(80, 'Computing checksum...')

    // 计算组合数据的校验和
    const combinedData = new Uint8Array(mmapTableSize + mergedDataSize)
    combinedData.set(mmapTable, 0)
    combinedData.set(mergedData, mmapTableSize)

    const checksum = this.computeChecksum(combinedData)
    const combinedDataLength = combinedData.length

    if (progressCallback) progressCallback(90, 'Building final file...')

    // 构建最终输出
    const headerSize = 4 + 4 + 4 // total_files + checksum + combined_data_length
    const totalSize = headerSize + combinedDataLength
    const finalData = new Uint8Array(totalSize)

    let offset = 0

    // 写入文件总数
    finalData.set(this.packUint32(totalFiles), offset)
    offset += 4

    // 写入校验和
    finalData.set(this.packUint32(checksum), offset)
    offset += 4

    // 写入组合数据长度
    finalData.set(this.packUint32(combinedDataLength), offset)
    offset += 4

    // 写入组合数据
    finalData.set(combinedData, offset)

    if (progressCallback) progressCallback(100, 'Packaging completed')

    return finalData.buffer
  }

  /**
   * 获取文件统计信息
   * @returns {Object} 统计信息
   */
  getStats() {
    let totalSize = 0
    const fileTypes = new Map()

    for (const file of this.files) {
      totalSize += file.size

      const ext = file.filename.split('.').pop()?.toLowerCase() || 'unknown'
      fileTypes.set(ext, (fileTypes.get(ext) || 0) + 1)
    }

    return {
      fileCount: this.files.length,
      totalSize,
      fileTypes: Object.fromEntries(fileTypes),
      averageFileSize: this.files.length > 0 ? Math.round(totalSize / this.files.length) : 0
    }
  }

  /**
   * 打印打包的文件列表
   */
  printFileList() {
    console.log('=== Packaged File List ===')
    console.log(`Total files: ${this.files.length}`)

    if (this.files.length === 0) {
      console.log('No files available')
      return
    }

    // 按扩展名和文件名排序后打印
    const sortedFiles = this.sortFiles(this.files)

    sortedFiles.forEach((file, index) => {
      const ext = file.filename.split('.').pop()?.toLowerCase() || 'unknown'
      const sizeKB = (file.size / 1024).toFixed(2)
      const dimensions = (file.width && file.height) ? `${file.width}x${file.height}` : 'N/A'

      console.log(`${String(index + 1).padStart(3, ' ')}. ${file.filename}`)
      console.log(`    Type: ${ext.toUpperCase()}`)
      console.log(`    Size: ${sizeKB} KB (${file.size} bytes)`)
      console.log(`    Dimensions: ${dimensions}`)
      console.log('')
    })

    // 打印统计信息
    const stats = this.getStats()
    console.log('=== File Statistics ===')
    console.log(`Total size: ${(stats.totalSize / 1024).toFixed(2)} KB`)
    console.log(`Average size: ${(stats.averageFileSize / 1024).toFixed(2)} KB`)
    console.log('File type distribution:')
    Object.entries(stats.fileTypes).forEach(([ext, count]) => {
      console.log(`  ${ext.toUpperCase()}: ${count} files`)
    })
  }

  /**
   * 清理文件列表
   */
  clear() {
    this.files = []
  }
}

export default SpiffsGenerator

/**
 * StorageHelper 工具类
 * 为各个组件提供便捷的文件存储功能
 */

import configStorage from './ConfigStorage.js'

class StorageHelper {
  /**
   * 为字体文件提供自动保存功能
   * @param {File} file - 字体文件
   * @param {Object} config - 字体配置
   * @returns {Promise<void>}
   */
  static async saveFontFile(file, config = {}) {
    if (file) {
      const key = 'custom_font'
      try {
        await configStorage.saveFile(key, file, 'font', {
          size: config.size || 20,
          bpp: config.bpp || 4,
          charset: config.charset || 'deepseek'
        })
        console.log(`字体文件已保存: ${file.name}`)
      } catch (error) {
        console.warn(`保存字体文件失败: ${file.name}`, error)
      }
    }
  }

  /**
   * 为表情文件提供自动保存功能
   * @param {string} emojiName - 表情名称或文件hash（如果以hash_开头）
   * @param {File} file - 表情文件
   * @param {Object} config - 表情配置
   * @returns {Promise<void>}
   */
  static async saveEmojiFile(emojiName, file, config = {}) {
    if (file && emojiName) {
      // 如果 emojiName 已经以 hash_ 开头（新的去重结构），直接使用
      // 否则添加 emoji_ 前缀（旧的结构，向后兼容）
      const key = emojiName.startsWith('hash_') ? emojiName : `emoji_${emojiName}`

      try {
        const width = config?.size?.width ?? 64
        const height = config?.size?.height ?? 64

        // 传入可克隆的普通对象，避免 Vue Proxy
        await configStorage.saveFile(key, file, 'emoji', {
          name: emojiName,
          size: { width, height },
          format: config?.format,
          emotions: config?.emotions  // 新增：记录使用该文件的表情列表
        })
        console.log(`表情文件已保存: ${key} - ${file.name}`)
      } catch (error) {
        console.warn(`保存表情文件失败: ${emojiName}`, error)
      }
    }
  }

  /**
   * 为背景文件提供自动保存功能
   * @param {string} mode - 模式 ('light' 或 'dark')
   * @param {File} file - 背景文件
   * @param {Object} config - 背景配置
   * @returns {Promise<void>}
   */
  static async saveBackgroundFile(mode, file, config = {}) {
    if (file && mode) {
      const key = `background_${mode}`
      try {
        let safeConfig = {}
        try {
          safeConfig = config ? JSON.parse(JSON.stringify(config)) : {}
        } catch (e) {
          safeConfig = { ...config }
        }

        await configStorage.saveFile(key, file, 'background', {
          mode,
          ...safeConfig
        })
        console.log(`背景文件已保存: ${mode} - ${file.name}`)
      } catch (error) {
        console.warn(`保存背景文件失败: ${mode}`, error)
      }
    }
  }

  /**
   * 恢复字体文件
   * @returns {Promise<File|null>}
   */
  static async restoreFontFile() {
    try {
      return await configStorage.loadFile('custom_font')
    } catch (error) {
      console.warn('恢复字体文件失败:', error)
      return null
    }
  }

  /**
   * 恢复表情文件
   * @param {string} emojiName - 表情名称或文件hash（如果以hash_开头）
   * @returns {Promise<File|null>}
   */
  static async restoreEmojiFile(emojiName) {
    if (!emojiName) return null

    try {
      // 如果 emojiName 已经以 hash_ 开头（新的去重结构），直接使用
      // 否则添加 emoji_ 前缀（旧的结构，向后兼容）
      const key = emojiName.startsWith('hash_') ? emojiName : `emoji_${emojiName}`
      return await configStorage.loadFile(key)
    } catch (error) {
      console.warn(`恢复表情文件失败: ${emojiName}`, error)
      return null
    }
  }

  /**
   * 恢复背景文件
   * @param {string} mode - 模式 ('light' 或 'dark')
   * @returns {Promise<File|null>}
   */
  static async restoreBackgroundFile(mode) {
    if (!mode) return null

    try {
      const key = `background_${mode}`
      return await configStorage.loadFile(key)
    } catch (error) {
      console.warn(`恢复背景文件失败: ${mode}`, error)
      return null
    }
  }

  /**
   * 删除字体文件
   * @returns {Promise<void>}
   */
  static async deleteFontFile() {
    try {
      await configStorage.deleteFile('custom_font')
      console.log('字体文件已删除')
    } catch (error) {
      console.warn('删除字体文件失败:', error)
    }
  }

  /**
   * 删除表情文件
   * @param {string} emojiName - 表情名称或文件hash（如果以hash_开头）
   * @returns {Promise<void>}
   */
  static async deleteEmojiFile(emojiName) {
    if (!emojiName) return

    try {
      // 如果 emojiName 已经以 hash_ 开头（新的去重结构），直接使用
      // 否则添加 emoji_ 前缀（旧的结构，向后兼容）
      const key = emojiName.startsWith('hash_') ? emojiName : `emoji_${emojiName}`
      await configStorage.deleteFile(key)
      console.log(`表情文件已删除: ${key}`)
    } catch (error) {
      console.warn(`删除表情文件失败: ${emojiName}`, error)
    }
  }

  /**
   * 删除背景文件
   * @param {string} mode - 模式 ('light' 或 'dark')
   * @returns {Promise<void>}
   */
  static async deleteBackgroundFile(mode) {
    if (!mode) return

    try {
      const key = `background_${mode}`
      await configStorage.deleteFile(key)
      console.log(`背景文件已删除: ${mode}`)
    } catch (error) {
      console.warn(`删除背景文件失败: ${mode}`, error)
    }
  }

  /**
   * 获取文件存储信息
   * @returns {Promise<Object>}
   */
  static async getStorageInfo() {
    try {
      return await configStorage.getStorageInfo()
    } catch (error) {
      console.warn('获取存储信息失败:', error)
      return {
        configs: { count: 0 },
        files: { count: 0 },
        temp_data: { count: 0 },
        lastSaved: null
      }
    }
  }

  /**
   * 清理所有文件存储
   * @returns {Promise<void>}
   */
  static async clearAllFiles() {
    try {
      await configStorage.clearAll()
      console.log('所有存储文件已清理')
    } catch (error) {
      console.warn('清理存储文件失败:', error)
      throw error
    }
  }
}

