/**
 * WakenetModelPacker 类
 * 模仿 pack_model.py 的功能，用于在浏览器端打包唤醒词模型
 * 
 * 注意：已修复与Python版本的兼容性问题：
 * - 使用ASCII编码而非UTF-8编码
 * - 确保小端序整数格式一致
 * - 移除冗余的字符串替换操作
 * 
 * 打包格式：
 * {
 *     model_num: int (4字节)
 *     model1_info: model_info_t
 *     model2_info: model_info_t
 *     ...
 *     model1数据
 *     model2数据
 *     ...
 * }
 * 
 * model_info_t格式：
 * {
 *     model_name: char[32] (32字节)
 *     file_number: int (4字节)
 *     file1_name: char[32] (32字节)
 *     file1_start: int (4字节)  
 *     file1_len: int (4字节)
 *     file2_name: char[32] (32字节)
 *     file2_start: int (4字节)   
 *     file2_len: int (4字节)
 *     ...
 * }
 */

class WakenetModelPacker {
  constructor() {
    this.models = new Map()
  }

  /**
   * 添加模型文件
   * @param {string} modelName - 模型名称
   * @param {string} fileName - 文件名
   * @param {ArrayBuffer} fileData - 文件数据
   */
  addModelFile(modelName, fileName, fileData) {
    if (!this.models.has(modelName)) {
      this.models.set(modelName, new Map())
    }
    this.models.get(modelName).set(fileName, fileData)
  }

  /**
   * 从share/wakenet_model或multinet_model目录加载模型
   * @param {string} modelName - 模型名称 (例如: wn9s_nihaoxiaozhi 或 mn6_cn)
   * @returns {Promise<boolean>} 加载是否成功
   */
  async loadModelFromShare(modelName) {
    try {
      let modelFiles = []
      let baseUrl = ''

      if (modelName.startsWith('wn9')) {
        // wakenet模型
        modelFiles = ['_MODEL_INFO_', 'wn9_data', 'wn9_index']
        baseUrl = `./static/wakenet_model/${modelName}/`
      } else if (modelName.startsWith('mn6') || modelName.startsWith('mn7')) {
        // multinet模型
        modelFiles = ['_MODEL_INFO_', `${modelName.substring(0, 3)}_data`, `${modelName.substring(0, 3)}_index`, 'vocab']
        baseUrl = `./static/multinet_model/${modelName}/`

        // 同时加载 fst 模型文件 (Multinet 6/7 必需)
        await this.loadFSTModel()
      } else {
        throw new Error(`Unknown model type: ${modelName}`)
      }

      let loadedFiles = 0
      for (const fileName of modelFiles) {
        try {
          const response = await fetch(`${baseUrl}${fileName}`)
          if (response.ok) {
            const fileData = await response.arrayBuffer()
            this.addModelFile(modelName, fileName, fileData)
            loadedFiles++
          } else {
            console.warn(`无法加载文件: ${fileName}, status: ${response.status}`)
          }
        } catch (error) {
          console.warn(`加载文件失败: ${fileName}`, error)
        }
      }

      return loadedFiles === modelFiles.length
    } catch (error) {
      console.error(`加载模型失败: ${modelName}`, error)
      return false
    }
  }

  /**
   * 加载 FST 模型文件 (Multinet 6/7 必需)
   * @returns {Promise<boolean>} 是否加载成功
   */
  async loadFSTModel() {
    try {
      const modelName = 'fst'

      // 如果已经加载过，直接返回
      if (this.models.has(modelName)) {
        return true
      }

      const modelFiles = ['commands_cn.txt', 'commands_en.txt']
      const baseUrl = `./static/multinet_model/fst/`

      let loadedFiles = 0
      for (const fileName of modelFiles) {
        try {
          const response = await fetch(`${baseUrl}${fileName}`)
          if (response.ok) {
            const fileData = await response.arrayBuffer()
            this.addModelFile(modelName, fileName, fileData)
            loadedFiles++
          } else {
            console.warn(`无法加载 FST 文件: ${fileName}, status: ${response.status}`)
          }
        } catch (error) {
          console.warn(`加载 FST 文件失败: ${fileName}`, error)
        }
      }

      return loadedFiles > 0
    } catch (error) {
      console.error('加载 FST 模型失败', error)
      return false
    }
  }

  /**
   * 将字符串打包为固定长度的二进制数据
   * 模仿Python版本的struct_pack_string行为，使用ASCII编码
   * @param {string} string - 输入字符串
   * @param {number} maxLen - 最大长度
   * @returns {Uint8Array} 打包后的二进制数据
   */
  packString(string, maxLen) {
    const bytes = new Uint8Array(maxLen)

    // 使用ASCII编码，与Python版本保持一致
    // 不预留null终止符空间，完整使用maxLen字节
    const copyLen = Math.min(string.length, maxLen)

    for (let i = 0; i < copyLen; i++) {
      // 使用charCodeAt获取ASCII码，只取低8位以确保兼容性
      bytes[i] = string.charCodeAt(i) & 0xFF
    }

    // 剩余字节保持为0（默认初始化值）
    return bytes
  }

  /**
   * 将32位整数转换为小端序字节数组
   * 与Python版本的struct.pack('<I', value)保持一致
   * @param {number} value - 整数值
   * @returns {Uint8Array} 4字节的小端序数组
   */
  packUint32(value) {
    const bytes = new Uint8Array(4)
    bytes[0] = value & 0xFF          // 最低字节 (LSB)
    bytes[1] = (value >> 8) & 0xFF   // 
    bytes[2] = (value >> 16) & 0xFF  // 
    bytes[3] = (value >> 24) & 0xFF  // 最高字节 (MSB)
    return bytes
  }

  /**
   * 打包所有模型为srmodels.bin格式
   * @returns {ArrayBuffer} 打包后的二进制数据
   */
  packModels() {
    if (this.models.size === 0) {
      throw new Error('没有模型数据可打包')
    }

    // 计算所有文件的总数和数据
    let totalFileNum = 0
    const modelDataList = []

    // 按模型名排序遍历
    for (const [modelName, files] of Array.from(this.models.entries()).sort((a, b) => a[0].localeCompare(b[0]))) {
      totalFileNum += files.size
      // 按文件名排序，确保与Python版本顺序一致
      const sortedFiles = Array.from(files.entries()).sort((a, b) => a[0].localeCompare(b[0]))
      modelDataList.push({
        name: modelName,
        files: sortedFiles
      })
    }

    // 计算头部长度: 模型数量(4) + 每个模型信息(32+4+文件数*(32+4+4))
    const modelNum = this.models.size
    let headerLen = 4 // model_num

    for (const model of modelDataList) {
      headerLen += 32 + 4 // model_name + file_number
      headerLen += model.files.length * (32 + 4 + 4) // 每个文件的 name + start + len
    }

    // 创建输出缓冲区
    const totalSize = headerLen + Array.from(this.models.values())
      .reduce((total, files) => total + Array.from(files.values())
        .reduce((fileTotal, fileData) => fileTotal + fileData.byteLength, 0), 0)

    const output = new Uint8Array(totalSize)
    let offset = 0

    // 写入模型数量
    output.set(this.packUint32(modelNum), offset)
    offset += 4

    // 写入模型信息头
    let dataOffset = headerLen

    for (const model of modelDataList) {
      // 写入模型名称
      output.set(this.packString(model.name, 32), offset)
      offset += 32

      // 写入文件数量
      output.set(this.packUint32(model.files.length), offset)
      offset += 4

      // 写入每个文件的信息
      for (const [fileName, fileData] of model.files) {
        // 文件名
        output.set(this.packString(fileName, 32), offset)
        offset += 32

        // 文件起始位置
        output.set(this.packUint32(dataOffset), offset)
        offset += 4

        // 文件长度
        output.set(this.packUint32(fileData.byteLength), offset)
        offset += 4

        dataOffset += fileData.byteLength
      }
    }

    // 写入文件数据
    for (const model of modelDataList) {
      for (const [fileName, fileData] of model.files) {
        output.set(new Uint8Array(fileData), offset)
        offset += fileData.byteLength
      }
    }

    return output.buffer
  }

  /**
   * 验证模型名称是否有效
   * @param {string} modelName - 模型名称
   * @param {string} chipModel - 芯片型号
   * @returns {boolean} 是否有效
   */
  static isValidModel(modelName, chipModel) {
    const isC3OrC6 = chipModel === 'esp32c3' || chipModel === 'esp32c6'

    if (isC3OrC6) {
      return modelName.startsWith('wn9s_')
    } else {
      return modelName.startsWith('wn9_')
    }
  }

  /**
   * 清理已加载的模型数据
   */
  clear() {
    this.models.clear()
  }

  /**
   * 获取已加载的模型统计
   * @returns {Object} 统计信息
   */
  getStats() {
    let totalFiles = 0
    let totalSize = 0

    for (const files of this.models.values()) {
      totalFiles += files.size
      for (const fileData of files.values()) {
        totalSize += fileData.byteLength
      }
    }

    return {
      modelCount: this.models.size,
      fileCount: totalFiles,
      totalSize,
      models: Array.from(this.models.keys())
    }
  }

  /**
   * 验证打包格式的兼容性
   * 用于测试与Python版本的一致性
   * @returns {Object} 验证结果
   */
  validatePackingCompatibility() {
    // 测试字符串打包
    const testString = "test_model"
    const packedString = this.packString(testString, 32)

    // 测试整数打包
    const testInt = 0x12345678
    const packedInt = this.packUint32(testInt)

    return {
      stringPacking: {
        input: testString,
        output: Array.from(packedString).map(b => `0x${b.toString(16).padStart(2, '0')}`),
        isASCII: packedString.every((b, i) => i >= testString.length || b === testString.charCodeAt(i))
      },
      intPacking: {
        input: `0x${testInt.toString(16)}`,
        output: Array.from(packedInt).map(b => `0x${b.toString(16).padStart(2, '0')}`),
        isLittleEndian: packedInt[0] === 0x78 && packedInt[3] === 0x12
      }
    }
  }
}

export default WakenetModelPacker

/**
 * WasmGifScaler 类
 * 使用 gifsicle-wasm-browser 进行 GIF 图片缩放处理
 * 
 * 主要功能：
 * - GIF 图片缩放
 * - 保持宽高比
 * - GIF 优化压缩
 * - 多种缩放模式
 */

import gifsicle from 'gifsicle-wasm-browser'

class WasmGifScaler {
  constructor(options = {}) {
    this.quality = options.quality || 10 // 1-200, lossy 压缩质量
    this.debug = options.debug || false
    this.scalingMode = options.scalingMode || 'auto' // 'auto', 'fit', 'fill'
    this.optimize = options.optimize !== false // 默认启用优化
    this.optimizationLevel = options.optimizationLevel || 2 // 1-3, 优化级别
  }

  /**
   * 缩放 GIF 图片
   * @param {File|Blob|ArrayBuffer} gifFile - GIF 文件
   * @param {Object} options - 缩放选项
   * @param {number} options.maxWidth - 最大宽度
   * @param {number} options.maxHeight - 最大高度
   * @param {boolean} options.keepAspectRatio - 是否保持宽高比，默认 true
   * @param {boolean} options.optimize - 是否优化，默认 true
   * @param {number} options.lossy - lossy 压缩质量 (1-200)，默认使用实例配置
   * @param {number} options.loopCount - 循环次数，0 表示无限循环（默认），-1 表示保持原样
   * @returns {Promise<Blob>} 缩放后的 GIF Blob
   */
  async scaleGif(gifFile, options = {}) {
    const {
      maxWidth,
      maxHeight,
      keepAspectRatio = true,
      optimize = this.optimize,
      lossy = this.quality,
      loopCount = 0  // 默认无限循环
    } = options

    if (!maxWidth && !maxHeight) {
      throw new Error('必须指定 maxWidth 或 maxHeight')
    }

    try {
      // 构建 resize 命令
      let resizeCmd
      if (keepAspectRatio) {
        // 保持宽高比的缩放，使用 --resize-fit
        const width = maxWidth || '_'
        const height = maxHeight || '_'
        resizeCmd = `--resize-fit ${width}x${height}`
      } else {
        // 强制缩放到指定尺寸，使用 --resize
        const width = maxWidth || '_'
        const height = maxHeight || '_'
        resizeCmd = `--resize ${width}x${height}!`
      }

      // 构建完整的 gifsicle 命令
      const commandParts = []

      // 添加 unoptimize 确保正确处理
      commandParts.push('-U')

      // 添加 resize 命令
      commandParts.push(resizeCmd)

      // 添加循环次数设置（loopCount >= 0 时生效，-1 表示不设置）
      if (loopCount >= 0) {
        commandParts.push(`--loopcount=${loopCount}`)
      }

      // 添加 lossy 压缩
      if (lossy && lossy > 0) {
        commandParts.push(`--lossy=${lossy}`)
      }

      // 添加优化
      if (optimize) {
        commandParts.push(`-O${this.optimizationLevel}`)
      }

      // 输入输出
      commandParts.push('1.gif')
      commandParts.push('-o /out/output.gif')

      const command = commandParts.join(' ')

      if (this.debug) {
        console.log('GIF 缩放命令:', command)
        console.log('输入文件大小:', gifFile.size || '未知')
      }

      // 调用 gifsicle
      const result = await gifsicle.run({
        input: [{
          file: gifFile,
          name: '1.gif'
        }],
        command: [command]
      })

      if (!result || result.length === 0) {
        throw new Error('gifsicle 处理失败，未返回结果')
      }

      const outputFile = result[0]

      if (this.debug) {
        console.log('GIF 缩放完成')
        console.log('输出文件大小:', outputFile.size)
        if (gifFile.size) {
          const ratio = ((1 - outputFile.size / gifFile.size) * 100).toFixed(2)
          console.log(`压缩率: ${ratio}%`)
        }
      }

      // 转换为 Blob
      return new Blob([outputFile], { type: 'image/gif' })

    } catch (error) {
      console.error('GIF 缩放失败:', error)
      throw new Error(`GIF 缩放失败: ${error.message}`)
    }
  }

  /**
   * 批量缩放 GIF 图片
   * @param {Array} files - GIF 文件数组 [{file, options}]
   * @returns {Promise<Array>} 缩放后的 GIF Blob 数组
   */
  async scaleGifBatch(files) {
    const results = []

    for (let i = 0; i < files.length; i++) {
      const { file, options } = files[i]
      try {
        const result = await this.scaleGif(file, options)
        results.push(result)
      } catch (error) {
        console.error(`批量缩放第 ${i + 1} 个文件失败:`, error)
        results.push(null)
      }
    }

    return results
  }

  /**
   * 优化 GIF（不改变尺寸）
   * @param {File|Blob|ArrayBuffer} gifFile - GIF 文件
   * @param {Object} options - 优化选项
   * @param {number} options.lossy - lossy 压缩质量 (1-200)
   * @param {number} options.level - 优化级别 (1-3)
   * @param {number} options.loopCount - 循环次数，0 表示无限循环（默认），-1 表示保持原样
   * @returns {Promise<Blob>} 优化后的 GIF Blob
   */
  async optimizeGif(gifFile, options = {}) {
    const {
      lossy = this.quality,
      level = this.optimizationLevel,
      loopCount = 0  // 默认无限循环
    } = options

    try {
      const commandParts = ['-U']

      // 添加循环次数设置
      if (loopCount >= 0) {
        commandParts.push(`--loopcount=${loopCount}`)
      }

      if (lossy && lossy > 0) {
        commandParts.push(`--lossy=${lossy}`)
      }

      commandParts.push(`-O${level}`)
      commandParts.push('1.gif')
      commandParts.push('-o /out/output.gif')

      const command = commandParts.join(' ')

      if (this.debug) {
        console.log('GIF 优化命令:', command)
      }

      const result = await gifsicle.run({
        input: [{
          file: gifFile,
          name: '1.gif'
        }],
        command: [command]
      })

      if (!result || result.length === 0) {
        throw new Error('gifsicle 优化失败')
      }

      return new Blob([result[0]], { type: 'image/gif' })

    } catch (error) {
      console.error('GIF 优化失败:', error)
      throw new Error(`GIF 优化失败: ${error.message}`)
    }
  }

  /**
   * 获取 GIF 信息
   * @param {File|Blob|ArrayBuffer} gifFile - GIF 文件
   * @returns {Promise<Object>} GIF 信息
   */
  async getGifInfo(gifFile) {
    try {
      const result = await gifsicle.run({
        input: [{
          file: gifFile,
          name: '1.gif'
        }],
        command: ['--info 1.gif -o /out/info.txt']
      })

      if (!result || result.length === 0) {
        throw new Error('无法获取 GIF 信息')
      }

      const infoFile = result[0]
      const infoText = await infoFile.text()

      // 解析信息文本
      const info = this.parseGifInfo(infoText)

      return info

    } catch (error) {
      console.error('获取 GIF 信息失败:', error)
      // 返回基本信息
      return {
        size: gifFile.size || 0,
        type: 'image/gif'
      }
    }
  }

  /**
   * 解析 GIF 信息文本
   * @param {string} infoText - gifsicle --info 输出的文本
   * @returns {Object} 解析后的信息对象
   */
  parseGifInfo(infoText) {
    const info = {
      frames: 0,
      width: 0,
      height: 0,
      colors: 0,
      loopCount: 0
    }

    try {
      // 解析帧数
      const framesMatch = infoText.match(/(\d+) images?/)
      if (framesMatch) {
        info.frames = parseInt(framesMatch[1])
      }

      // 解析尺寸
      const sizeMatch = infoText.match(/logical screen (\d+)x(\d+)/)
      if (sizeMatch) {
        info.width = parseInt(sizeMatch[1])
        info.height = parseInt(sizeMatch[2])
      }

      // 解析颜色数
      const colorsMatch = infoText.match(/(\d+) colors/)
      if (colorsMatch) {
        info.colors = parseInt(colorsMatch[1])
      }

      // 解析循环次数
      if (infoText.includes('loop forever')) {
        info.loopCount = 0
      } else {
        const loopMatch = infoText.match(/loop count (\d+)/)
        if (loopMatch) {
          info.loopCount = parseInt(loopMatch[1])
        }
      }
    } catch (error) {
      console.warn('解析 GIF 信息时出错:', error)
    }

    return info
  }

  /**
   * 裁剪 GIF
   * @param {File|Blob|ArrayBuffer} gifFile - GIF 文件
   * @param {Object} cropRect - 裁剪区域 {x, y, width, height}
   * @returns {Promise<Blob>} 裁剪后的 GIF Blob
   */
  async cropGif(gifFile, cropRect) {
    const { x, y, width, height } = cropRect

    try {
      const command = [
        '-U',
        `--crop ${x},${y}+${width}x${height}`,
        '1.gif',
        '-o /out/output.gif'
      ].join(' ')

      if (this.debug) {
        console.log('GIF 裁剪命令:', command)
      }

      const result = await gifsicle.run({
        input: [{
          file: gifFile,
          name: '1.gif'
        }],
        command: [command]
      })

      if (!result || result.length === 0) {
        throw new Error('gifsicle 裁剪失败')
      }

      return new Blob([result[0]], { type: 'image/gif' })

    } catch (error) {
      console.error('GIF 裁剪失败:', error)
      throw new Error(`GIF 裁剪失败: ${error.message}`)
    }
  }

  /**
   * 清理资源
   */
  dispose() {
    // gifsicle-wasm-browser 不需要特殊的清理
    if (this.debug) {
      console.log('WasmGifScaler disposed')
    }
  }

  /**
   * 设置调试模式
   * @param {boolean} enabled - 是否启用调试
   */
  setDebug(enabled) {
    this.debug = enabled
  }

  /**
   * 设置压缩质量
   * @param {number} quality - 压缩质量 (1-200)
   */
  setQuality(quality) {
    if (quality < 1 || quality > 200) {
      throw new Error('质量参数必须在 1-200 之间')
    }
    this.quality = quality
  }

  /**
   * 设置优化级别
   * @param {number} level - 优化级别 (1-3)
   */
  setOptimizationLevel(level) {
    if (level < 1 || level > 3) {
      throw new Error('优化级别必须在 1-3 之间')
    }
    this.optimizationLevel = level
  }
}

export default WasmGifScaler

class WebSocketTransfer {
  constructor(token) {
    this.token = token
    this.ws = null
    this.isConnected = false
    this.isCancelled = false
    this.chunkSize = 64 * 1024 // 64KB per chunk
    this.onProgress = null
    this.onError = null
    this.onComplete = null
    this.onDownloadUrlReady = null
    this.onTransferStarted = null // 新增：transfer_started事件回调
    this.currentSession = null
    this.totalBytesSent = 0 // 新增：总发送字节数跟踪
    this.isSendingChunk = false // 新增：标记是否正在发送数据块
  }

  // 连接到transfer服务器
  async connect() {
    return new Promise((resolve, reject) => {
      try {
        // 使用固定的transfer服务器地址
        const wsUrl = `wss://api.tenclass.net/transfer/?token=${encodeURIComponent(this.token)}`
        this.ws = new WebSocket(wsUrl)

        this.ws.onopen = () => {
          this.isConnected = true
          console.log('WebSocket connected to transfer server')
          resolve()
        }

        this.ws.onmessage = (event) => {
          this.handleMessage(event)
        }

        this.ws.onerror = (error) => {
          console.error('WebSocket error:', error)
          this.isConnected = false
          reject(new Error('WebSocket connection failed'))
        }

        this.ws.onclose = (event) => {
          console.log('WebSocket closed:', event.code, event.reason)
          this.isConnected = false
        }

        // 设置连接超时
        setTimeout(() => {
          if (!this.isConnected) {
            this.ws.close()
            reject(new Error('WebSocket connection timeout'))
          }
        }, 10000)

      } catch (error) {
        reject(new Error(`Failed to create WebSocket connection: ${error.message}`))
      }
    })
  }

  // 处理WebSocket消息
  handleMessage(event) {
    try {
      if (typeof event.data === 'string') {
        const message = JSON.parse(event.data)

        switch (message.type) {
          case 'file_created':
            if (this.currentSession) {
              this.currentSession.url = message.url
              // 通知下载URL已准备就绪
              if (this.onDownloadUrlReady) {
                this.onDownloadUrlReady(message.url)
              }
              // 等待transfer_started消息后再开始发送数据
            }
            break

          case 'transfer_started':
            if (this.currentSession) {
              // 标记已收到transfer_started消息
              this.currentSession.transferStarted = true

              // 通知外部监听器
              if (this.onTransferStarted) {
                this.onTransferStarted()
              }

              // 如果传输已准备好，开始发送文件数据
              if (this.currentSession.transferReady) {
                this.sendFileData()
              }
            }
            break

          case 'ack':
            // 收到确认，验证并更新bytesSent
            if (this.currentSession) {
              const { blob } = this.currentSession
              const totalSize = blob.size
              const serverBytesSent = message.bytesSent

              // 验证服务器报告的bytesSent
              if (serverBytesSent < 0) {
                console.error('Invalid server bytesSent (negative):', serverBytesSent)
                this.isSendingChunk = false // 重置发送标志
                if (this.onError) {
                  this.onError(new Error('Server returned invalid byte count'))
                }
                return
              }

              if (serverBytesSent > totalSize) {
                console.error(`Server bytesSent (${serverBytesSent}) exceeds fileSize (${totalSize})`)
                this.isSendingChunk = false // 重置发送标志
                if (this.onError) {
                  this.onError(new Error('Server byte count exceeds file size'))
                }
                return
              }

              // 标记当前数据块已发送完成
              this.isSendingChunk = false

              // 使用服务器确认的bytesSent
              if (serverBytesSent > this.currentSession.bytesSent) {
                this.currentSession.bytesSent = serverBytesSent
              }

              // 发送下一块数据
              this.sendFileData()
            }
            break

          case 'transfer_completed':
            // 验证传输完整性
            if (this.currentSession) {
              const expectedSize = this.currentSession.blob.size
              if (this.totalBytesSent !== expectedSize) {
                console.warn(`Transfer size mismatch: sent ${this.totalBytesSent} bytes, expected ${expectedSize} bytes`)
              }
            }

            if (this.onComplete) {
              this.onComplete()
            }
            break

          case 'error':
            console.error('Transfer error:', message.message)
            if (this.onError) {
              this.onError(new Error(message.message))
            }
            break
        }
      }
    } catch (error) {
      console.error('Error handling message:', error)
      if (this.onError) {
        this.onError(error)
      }
    }
  }

  // 发送文件数据
  async sendFileData() {
    // 防止并发发送
    if (this.isSendingChunk) {
      return
    }

    if (!this.currentSession || this.isCancelled) {
      return
    }

    const { blob } = this.currentSession
    const totalSize = blob.size
    let bytesSent = this.currentSession.bytesSent

    // 严格检查：确保不会发送超出文件大小的数据
    if (bytesSent >= totalSize) {
      if (this.onProgress) {
        this.onProgress(100, 'Transfer completed, waiting for device confirmation...')
      }
      return
    }

    this.isSendingChunk = true

    // 再次验证bytesSent不超过文件大小
    if (bytesSent > totalSize) {
      console.error(`Critical error: bytesSent (${bytesSent}) exceeds fileSize (${totalSize})`)
      if (this.onError) {
        this.onError(new Error('Transfer byte count exceeds file size'))
      }
      return
    }

    // 计算下一块的大小，确保不会超出文件边界
    const remainingBytes = Math.max(0, totalSize - bytesSent)
    const chunkSize = Math.min(this.chunkSize, remainingBytes)

    if (chunkSize <= 0) {
      return
    }

    const chunk = blob.slice(bytesSent, bytesSent + chunkSize)

    try {
      // 读取文件块
      const arrayBuffer = await new Promise((resolve, reject) => {
        const reader = new FileReader()
        reader.onload = () => resolve(reader.result)
        reader.onerror = () => reject(new Error('File read failed'))
        reader.readAsArrayBuffer(chunk)
      })

      if (this.isCancelled) {
        return
      }

      // 发送二进制数据
      this.ws.send(arrayBuffer)

      // 更新本地bytesSent计数（乐观更新）
      const newBytesSent = bytesSent + chunkSize
      this.currentSession.bytesSent = newBytesSent
      this.totalBytesSent += chunkSize // 更新总发送字节数

      // 验证更新后的bytesSent不超过文件大小
      if (newBytesSent > totalSize) {
        console.error(`Critical error: bytesSent (${newBytesSent}) exceeds fileSize (${totalSize})`)
        if (this.onError) {
          this.onError(new Error('Transfer byte count exceeds file size'))
        }
        return
      }

      // 额外验证：总发送字节数也不应该超过文件大小
      if (this.totalBytesSent > totalSize) {
        console.error(`Critical error: totalBytesSent (${this.totalBytesSent}) exceeds fileSize (${totalSize})`)
        if (this.onError) {
          this.onError(new Error('Total sent bytes exceed file size'))
        }
        return
      }

      // 更新进度（只更新传输进度部分）
      const transferProgress = Math.round(newBytesSent / totalSize * 60) + 40 // 40-100范围
      const step = `Transferring... ${Math.round(newBytesSent / 1024)}KB / ${Math.round(totalSize / 1024)}KB`

      if (this.onProgress) {
        this.onProgress(transferProgress, step)
      }

    } catch (error) {
      console.error('Error sending file chunk:', error)
      this.isSendingChunk = false // 重置发送标志
      if (this.onError) {
        this.onError(error)
      }
    }
  }

  // 初始化传输会话（只建立连接和获取URL）
  async initializeSession(blob, onProgress, onError, onDownloadUrlReady) {
    return new Promise((resolve, reject) => {
      this.onProgress = onProgress
      this.onError = (error) => {
        if (onError) onError(error)
        reject(error)
      }
      this.onDownloadUrlReady = (url) => {
        if (onDownloadUrlReady) onDownloadUrlReady(url)
        resolve(url)
      }
      this.isCancelled = false

      try {
        // 连接到WebSocket服务器
        if (this.onProgress) {
          this.onProgress(5, 'Connecting to transfer server...')
        }

        this.connect().then(() => {
          // 发送文件创建请求
          if (this.onProgress) {
            this.onProgress(10, 'Creating file session...')
          }

          const createMessage = {
            type: 'create_file',
            fileName: 'assets.bin',
            fileSize: blob.size
          }

          this.ws.send(JSON.stringify(createMessage))

          // 保存blob引用，等待file_created消息
          this.currentSession = {
            blob: blob,
            bytesSent: 0,
            fileSize: blob.size,
            transferStarted: false,
            transferReady: true // 初始化时就设置为true，因为initializeSession后就可以开始传输
          }
          // 重置总发送字节数
          this.totalBytesSent = 0
        }).catch(error => {
          console.error('Transfer initialization failed:', error)
          if (this.onError) {
            this.onError(error)
          }
        })

      } catch (error) {
        console.error('Transfer initialization failed:', error)
        if (this.onError) {
          this.onError(error)
        }
      }
    })
  }

  // 开始传输文件数据（假设会话已初始化）
  async startTransfer(onProgress, onError, onComplete) {
    return new Promise((resolve, reject) => {
      this.onProgress = onProgress
      this.onError = (error) => {
        this.isSendingChunk = false // 重置发送标志
        if (onError) onError(error)
        reject(error)
      }
      this.onComplete = () => {
        this.isSendingChunk = false // 重置发送标志
        if (onComplete) onComplete()
        resolve()
      }

      if (!this.currentSession || !this.currentSession.blob) {
        const error = new Error('Transfer session not initialized')
        if (this.onError) this.onError(error)
        reject(error)
        return
      }

      // 设置传输状态，等待transfer_started消息
      this.currentSession.transferReady = true

      // 如果已经收到了transfer_started消息，开始传输
      if (this.currentSession.transferStarted) {
        this.sendFileData()
      } else {
      }
      // 否则等待transfer_started消息
    })
  }

  // 开始传输文件
  async transferFile(blob, onProgress, onError, onComplete, onDownloadUrlReady) {
    // 如果提供了onDownloadUrlReady回调，使用分阶段传输
    if (onDownloadUrlReady) {
      await this.initializeSession(blob, onProgress, onError, onDownloadUrlReady)
      // 返回，让调用者决定何时开始传输
      return
    }

    // 否则，使用传统的一次性传输
    this.onProgress = onProgress
    this.onError = onError
    this.onComplete = onComplete
    this.isCancelled = false

    try {
      // 连接到WebSocket服务器
      if (this.onProgress) {
        this.onProgress(5, 'Connecting to transfer server...')
      }

      await this.connect()

      // 发送文件创建请求
      if (this.onProgress) {
        this.onProgress(10, 'Creating file session...')
      }

      const createMessage = {
        type: 'create_file',
        fileName: 'assets.bin',
        fileSize: blob.size
      }

      this.ws.send(JSON.stringify(createMessage))

      // 保存blob引用，等待file_created消息
      this.currentSession = {
        blob: blob,
        bytesSent: 0,
        fileSize: blob.size,
        transferStarted: false,
        transferReady: true // 传统模式下直接设置为true
      }

    } catch (error) {
      console.error('Transfer initialization failed:', error)
      if (this.onError) {
        this.onError(error)
      }
    }
  }

  // 取消传输
  cancel() {
    this.isCancelled = true
    this.isSendingChunk = false // 重置发送标志
    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
      this.ws.close()
    }
  }

  // 清理资源
  destroy() {
    this.cancel()
    this.onProgress = null
    this.onError = null
    this.onComplete = null
    this.onDownloadUrlReady = null
    this.onTransferStarted = null
    this.totalBytesSent = 0
    this.isSendingChunk = false
  }
}

export default WebSocketTransfer

// Custom Error type to simplify error messaging
// ES6 版本

class AppError extends Error {
  constructor(message) {
    super(message)
    this.name = 'AppError'

    // 保持堆栈跟踪 (仅在 V8 引擎中可用)
    if (Error.captureStackTrace) {
      Error.captureStackTrace(this, AppError)
    }
  }
}

export default AppError

/**
 * BrowserFontConverter - 完整的浏览器端字体转换器
 * 基于 lv_font_conv 的核心逻辑，适配浏览器环境
 */

import opentype from 'opentype.js'
import collect_font_data from './CollectFontData.js'
import AppError from './AppError.js'
import write_cbin from './writers/CBinWriter.js'

class BrowserFontConverter {
  constructor() {
    this.initialized = false
    this.supportedFormats = ['ttf', 'woff', 'woff2', 'otf']
    this.charsetCache = new Map() // 缓存已加载的字符集
  }

  /**
   * 初始化转换器
   */
  async initialize() {
    if (this.initialized) return

    try {
      // 检查依赖是否可用
      if (typeof opentype === 'undefined') {
        throw new Error('opentype.js not loaded')
      }

      this.initialized = true
      console.log('BrowserFontConverter 初始化完成')
    } catch (error) {
      console.error('BrowserFontConverter initialization failed:', error)
      throw error
    }
  }

  /**
   * 验证字体文件
   */
  validateFont(fontFile) {
    if (!fontFile) return false

    if (fontFile instanceof File) {
      const fileName = fontFile.name.toLowerCase()
      const fileType = fontFile.type.toLowerCase()

      const validExtension = this.supportedFormats.some(ext => 
        fileName.endsWith(`.${ext}`)
      )

      const validMimeType = [
        'font/ttf', 'font/truetype', 'application/x-font-ttf',
        'font/woff', 'font/woff2', 'application/font-woff',
        'font/otf', 'application/x-font-otf'
      ].some(type => fileType.includes(type))

      return validExtension || validMimeType
    }

    return fontFile instanceof ArrayBuffer && fontFile.byteLength > 0
  }

  /**
   * 获取字体信息
   */
  async getFontInfo(fontFile) {
    try {
      let buffer

      if (fontFile instanceof File) {
        buffer = await fontFile.arrayBuffer()
      } else if (fontFile instanceof ArrayBuffer) {
        buffer = fontFile
      } else {
        throw new Error('Unsupported font file type')
      }

      const font = opentype.parse(buffer)

      return {
        familyName: this.getLocalizedName(font.names.fontFamily) || 'Unknown',
        fullName: this.getLocalizedName(font.names.fullName) || 'Unknown',
        postScriptName: this.getLocalizedName(font.names.postScriptName) || 'Unknown',
        version: this.getLocalizedName(font.names.version) || 'Unknown',
        unitsPerEm: font.unitsPerEm,
        ascender: font.ascender,
        descender: font.descender,
        numGlyphs: font.numGlyphs,
        supported: true
      }
    } catch (error) {
      console.error('Failed to get font information:', error)
      return {
        familyName: 'Unknown',
        supported: false,
        error: error.message
      }
    }
  }

  /**
   * 获取本地化名称
   */
  getLocalizedName(nameObj) {
    if (!nameObj) return null

    // 优先级：中文 > 英文 > 第一个可用的
    return nameObj['zh'] || nameObj['zh-CN'] || nameObj['en'] || 
           nameObj[Object.keys(nameObj)[0]]
  }

  /**
   * 转换字体为 CBIN 格式
   */
  async convertToCBIN(options) {
    if (!this.initialized) {
      await this.initialize()
    }

    const {
      fontFile,
      fontName,
      fontSize = 20,
      bpp = 4,
      charset = 'deepseek',
      symbols = '',
      range = '',
      compression = false,
      lcd = false,
      lcd_v = false,
      progressCallback = null
    } = options

    if (!this.validateFont(fontFile)) {
      throw new AppError('不支持的字体文件格式')
    }

    try {
      if (progressCallback) progressCallback(0, 'Starting font processing...')

      // 准备字体数据
      let fontBuffer
      if (fontFile instanceof File) {
        fontBuffer = await fontFile.arrayBuffer()
      } else {
        fontBuffer = fontFile
      }

      if (progressCallback) progressCallback(10, 'Parsing font structure...')

      // 构建字符范围和符号（使用异步版本支持从文件加载字符集）
      const { ranges, charSymbols } = await this.parseCharacterInputAsync(charset, symbols, range)

      if (progressCallback) progressCallback(20, 'Preparing conversion parameters...')

      // 构建转换参数
      const convertArgs = {
        font: [{
          source_path: fontName || 'custom_font',
          source_bin: fontBuffer,
          ranges: [{ 
            range: ranges, 
            symbols: charSymbols 
          }],
          autohint_off: false,
          autohint_strong: false
        }],
        size: fontSize,
        bpp: bpp,
        lcd: lcd,
        lcd_v: lcd_v,
        no_compress: !compression,
        no_kerning: false,
        use_color_info: false,
        format: 'cbin',
        output: fontName || 'font'
      }

      if (progressCallback) progressCallback(30, 'Collecting font data...')

      // 收集字体数据
      const fontData = await collect_font_data(convertArgs)

      if (progressCallback) progressCallback(70, 'Generating CBIN format...')

      // 生成 CBIN 数据
      const result = write_cbin(convertArgs, fontData)
      const outputName = convertArgs.output

      if (progressCallback) progressCallback(100, 'Conversion completed!')

      return result[outputName]

    } catch (error) {
      console.error('Font conversion failed:', error)
      throw new AppError(`Font conversion failed: ${error.message}`)
    }
  }

  /**
   * 解析字符输入（字符集、符号、范围）- 异步版本
   */
  async parseCharacterInputAsync(charset, symbols, range) {
    let ranges = []
    let charSymbols = symbols || ''

    // 处理完整字符集 - 使用 Unicode 范围 0x0-0xFFFF
    if (charset === 'full') {
      ranges = [0x0, 0xFFFF, 0x0]
      // 完整字符集不需要额外的符号
      return { ranges, charSymbols }
    }

    // 处理预设字符集
    if (charset && charset !== 'custom') {
      const presetChars = await this.getCharsetContentAsync(charset)
      charSymbols = presetChars + charSymbols
    }

    // 处理 Unicode 范围
    if (range) {
      ranges = this.parseUnicodeRange(range)
    }

    return { ranges, charSymbols }
  }

  /**
   * 解析字符输入（字符集、符号、范围）- 同步版本（向后兼容）
   */
  parseCharacterInput(charset, symbols, range) {
    let ranges = []
    let charSymbols = symbols || ''

    // 处理完整字符集 - 使用 Unicode 范围 0x0-0xFFFF
    if (charset === 'full') {
      ranges = [0x0, 0xFFFF, 0x0]
      // 完整字符集不需要额外的符号
      return { ranges, charSymbols }
    }

    // 处理预设字符集
    if (charset && charset !== 'custom') {
      const presetChars = this.getCharsetContent(charset)
      charSymbols = presetChars + charSymbols
    }

    // 处理 Unicode 范围
    if (range) {
      ranges = this.parseUnicodeRange(range)
    }

    return { ranges, charSymbols }
  }


  /**
   * 异步加载字符集文件
   */
  async loadCharsetFromFile(charset) {
    const charsetFiles = {
      latin: './static/charsets/latin1.txt',
      deepseek: './static/charsets/deepseek.txt',
      gb2312: './static/charsets/gb2312.txt',
      qwen: './static/charsets/qwen18409.txt'
    }

    const filePath = charsetFiles[charset]
    if (!filePath) {
      return null
    }

    try {
      const response = await fetch(filePath)
      if (!response.ok) {
        throw new Error(`Failed to load charset file: ${response.status}`)
      }

      const text = await response.text()
      // 将每行的字符连接成一个字符串，保留所有字符（包括空白字符）
      const characters = text.split('\n').join('')

      // 缓存结果
      this.charsetCache.set(charset, characters)
      return characters
    } catch (error) {
      console.error(`Failed to load charset ${charset}:`, error)
      return null
    }
  }

  /**
   * 获取字符集内容（同步方法，用于已缓存的字符集）
   */
  getCharsetContent(charset) {
    const charsets = {}

    // 如果是需要从文件加载的字符集，先检查缓存
    if ((charset === 'latin' || charset === 'deepseek' || charset === 'gb2312') && this.charsetCache.has(charset)) {
      return this.charsetCache.get(charset)
    }

    // 如果请求 basic，重定向到 latin（向后兼容）
    if (charset === 'basic') {
      return this.getCharsetContent('latin')
    }

    // 默认返回空字符串，需要先调用异步方法加载
    return charsets[charset] || ''
  }

  /**
   * 异步获取字符集内容
   */
  async getCharsetContentAsync(charset) {
    // 如果请求 basic，重定向到 latin（向后兼容）
    if (charset === 'basic') {
      charset = 'latin'
    }

    // 如果字符集已缓存，直接返回
    if (this.charsetCache.has(charset)) {
      return this.charsetCache.get(charset)
    }

    // 对于需要从文件加载的字符集
    if (charset === 'latin' || charset === 'deepseek' || charset === 'gb2312' || charset === 'qwen') {
      const loadedCharset = await this.loadCharsetFromFile(charset)
      if (loadedCharset) {
        return loadedCharset
      }
    }

    // 回退到同步方法
    return this.getCharsetContent(charset)
  }

  /**
   * 解析 Unicode 范围字符串
   */
  parseUnicodeRange(rangeStr) {
    const ranges = []
    const parts = rangeStr.split(',')

    for (const part of parts) {
      const trimmed = part.trim()
      if (!trimmed) continue

      if (trimmed.includes('-')) {
        const [start, end] = trimmed.split('-')
        const startCode = this.parseHexOrDec(start)
        const endCode = this.parseHexOrDec(end)

        if (startCode !== null && endCode !== null) {
          ranges.push(startCode, endCode, startCode)
        }
      } else {
        const code = this.parseHexOrDec(trimmed)
        if (code !== null) {
          ranges.push(code, code, code)
        }
      }
    }

    return ranges
  }

  /**
   * 解析十六进制或十进制数字
   */
  parseHexOrDec(str) {
    const trimmed = str.trim()

    if (trimmed.startsWith('0x') || trimmed.startsWith('0X')) {
      const parsed = parseInt(trimmed, 16)
      return isNaN(parsed) ? null : parsed
    }

    const parsed = parseInt(trimmed, 10)
    return isNaN(parsed) ? null : parsed
  }

  /**
   * 估算输出大小 - 异步版本
   */
  async estimateSizeAsync(options) {
    const { fontSize = 20, bpp = 4, charset = 'latin', symbols = '', range = '' } = options

    // 计算字符数量
    let charCount = symbols.length

    // 处理完整字符集 - 包含 0x0-0xFFFF (65536 个字符)
    if (charset === 'full') {
      charCount = 65536
    } else if (charset && charset !== 'custom') {
      const charsetContent = await this.getCharsetContentAsync(charset)
      charCount += charsetContent.length
    }

    if (range) {
      const ranges = this.parseUnicodeRange(range)
      for (let i = 0; i < ranges.length; i += 3) {
        charCount += ranges[i + 1] - ranges[i] + 1
      }
    }

    // 去重字符数（粗略估算），但完整字符集不去重
    if (charset !== 'full') {
      charCount = Math.min(charCount, charCount * 0.8)
    }

    // 估算每个字符的字节数
    const avgBytesPerChar = Math.ceil((fontSize * fontSize * bpp) / 8) + 40

    const estimatedSize = charCount * avgBytesPerChar + 2048 // 加上头部和索引

    return {
      characterCount: Math.floor(charCount),
      avgBytesPerChar,
      estimatedSize,
      formattedSize: this.formatBytes(estimatedSize)
    }
  }

  /**
   * 估算输出大小 - 同步版本（向后兼容）
   */
  estimateSize(options) {
    const { fontSize = 20, bpp = 4, charset = 'latin', symbols = '', range = '' } = options

    // 计算字符数量
    let charCount = symbols.length

    // 处理完整字符集 - 包含 0x0-0xFFFF (65536 个字符)
    if (charset === 'full') {
      charCount = 65536
    } else if (charset && charset !== 'custom') {
      const charsetContent = this.getCharsetContent(charset)
      charCount += charsetContent.length
    }

    if (range) {
      const ranges = this.parseUnicodeRange(range)
      for (let i = 0; i < ranges.length; i += 3) {
        charCount += ranges[i + 1] - ranges[i] + 1
      }
    }

    // 去重字符数（粗略估算），但完整字符集不去重
    if (charset !== 'full') {
      charCount = Math.min(charCount, charCount * 0.8)
    }

    // 估算每个字符的字节数
    const avgBytesPerChar = Math.ceil((fontSize * fontSize * bpp) / 8) + 40

    const estimatedSize = charCount * avgBytesPerChar + 2048 // 加上头部和索引

    return {
      characterCount: Math.floor(charCount),
      avgBytesPerChar,
      estimatedSize,
      formattedSize: this.formatBytes(estimatedSize)
    }
  }

  /**
   * 格式化字节大小
   */
  formatBytes(bytes) {
    if (bytes === 0) return '0 Bytes'

    const k = 1024
    const sizes = ['Bytes', 'KB', 'MB', 'GB']
    const i = Math.floor(Math.log(bytes) / Math.log(k))

    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i]
  }

  /**
   * 清理资源
   */
  cleanup() {
    // 清理可能的资源引用
    this.initialized = false
  }
}

// 创建单例实例
const browserFontConverter = new BrowserFontConverter()

export default browserFontConverter
export { BrowserFontConverter }

// Read fonts - ES6 version for browser
// 核心字体数据收集模块

import opentype from 'opentype.js'
import * as ft_render from './FreeType.js'
import AppError from './AppError.js' 
import Ranger from './Ranger.js'

export default async function collect_font_data(args) {
  await ft_render.init()

  // Duplicate font options as k/v for quick access
  let fonts_options = {}
  args.font.forEach(f => { fonts_options[f.source_path] = f })

  // read fonts
  let fonts_opentype = {}
  let fonts_freetype = {}

  for (let { source_path, source_bin } of args.font) {
    // don't load font again if it's specified multiple times in args
    if (fonts_opentype[source_path]) continue

    try {
      let b = source_bin

      // 处理不同类型的输入数据
      if (b instanceof File) {
        b = await b.arrayBuffer()
      } else if (b instanceof Uint8Array) {
        // Uint8Array
        b = b.buffer.slice(b.byteOffset, b.byteOffset + b.byteLength)
      }

      fonts_opentype[source_path] = opentype.parse(b)

      // 使用处理后的数据创建 FreeType 字体实例
      fonts_freetype[source_path] = ft_render.fontface_create(b, args.size)
    } catch (err) {
      throw new AppError(`Cannot load font "${source_path}": ${err.message}`)
    }
  }

  // merge all ranges
  let ranger = new Ranger()

  for (let { source_path, ranges } of args.font) {
    let font = fonts_freetype[source_path]

    for (let item of ranges) {
      /* eslint-disable max-depth */
      if (item.range) {
        for (let i = 0; i < item.range.length; i += 3) {
          let range = item.range.slice(i, i + 3)
          let chars = ranger.add_range(source_path, ...range)
          let is_empty = true

          for (let code of chars) {
            if (ft_render.glyph_exists(font, code)) {
              is_empty = false
              break
            }
          }

          if (is_empty) {
            let a = '0x' + range[0].toString(16)
            let b = '0x' + range[1].toString(16)
            throw new AppError(`Font "${source_path}" doesn't have any characters included in range ${a}-${b}`)
          }
        }
      }

      if (item.symbols) {
        let chars = ranger.add_symbols(source_path, item.symbols)
        let is_empty = true

        for (let code of chars) {
          if (ft_render.glyph_exists(font, code)) {
            is_empty = false
            break
          }
        }

        if (is_empty) {
          throw new AppError(`Font "${source_path}" doesn't have any characters included in "${item.symbols}"`)
        }
      }
    }
  }

  let mapping = ranger.get()
  let glyphs = []
  let all_dst_charcodes = Object.keys(mapping).sort((a, b) => a - b).map(Number)

  for (let dst_code of all_dst_charcodes) {
    let src_code = mapping[dst_code].code
    let src_font = mapping[dst_code].font

    if (!ft_render.glyph_exists(fonts_freetype[src_font], src_code)) continue

    let ft_result = ft_render.glyph_render(
      fonts_freetype[src_font],
      src_code,
      {
        autohint_off: fonts_options[src_font].autohint_off,
        autohint_strong: fonts_options[src_font].autohint_strong,
        lcd: args.lcd,
        lcd_v: args.lcd_v,
        mono: !args.lcd && !args.lcd_v && args.bpp === 1,
        use_color_info: args.use_color_info
      }
    )

    glyphs.push({
      code: dst_code,
      advanceWidth: ft_result.advance_x,
      bbox: {
        x: ft_result.x,
        y: ft_result.y - ft_result.height,
        width: ft_result.width,
        height: ft_result.height
      },
      kerning: {},
      freetype: ft_result.freetype,
      pixels: ft_result.pixels
    })
  }

  if (!args.no_kerning) {
    let existing_dst_charcodes = glyphs.map(g => g.code)

    for (let { code, kerning } of glyphs) {
      let src_code = mapping[code].code
      let src_font = mapping[code].font
      let font     = fonts_opentype[src_font]
      let glyph    = font.charToGlyph(String.fromCodePoint(src_code))

      for (let dst_code2 of existing_dst_charcodes) {
        // can't merge kerning values from 2 different fonts
        if (mapping[dst_code2].font !== src_font) continue

        let src_code2 = mapping[dst_code2].code
        let glyph2 = font.charToGlyph(String.fromCodePoint(src_code2))
        let krn_value = font.getKerningValue(glyph, glyph2)

        if (krn_value) kerning[dst_code2] = krn_value * args.size / font.unitsPerEm

        //let krn_value = ft_render.get_kerning(font, src_code, src_code2).x;
        //if (krn_value) kerning[dst_code2] = krn_value;
      }
    }
  }

  let first_font = fonts_freetype[args.font[0].source_path]
  let first_font_scale = args.size / first_font.units_per_em
  let os2_metrics = ft_render.fontface_os2_table(first_font)
  let post_table = fonts_opentype[args.font[0].source_path].tables.post

  for (let font of Object.values(fonts_freetype)) ft_render.fontface_destroy(font)

  ft_render.destroy()

  return {
    ascent:      Math.max(...glyphs.map(g => g.bbox.y + g.bbox.height)),
    descent:     Math.min(...glyphs.map(g => g.bbox.y)),
    typoAscent:  Math.round(os2_metrics.typoAscent * first_font_scale),
    typoDescent: Math.round(os2_metrics.typoDescent * first_font_scale),
    typoLineGap: Math.round(os2_metrics.typoLineGap * first_font_scale),
    size:        args.size,
    glyphs,
    underlinePosition:  Math.round(post_table.underlinePosition * first_font_scale),
    underlineThickness: Math.round(post_table.underlineThickness * first_font_scale)
  }
}

// FreeType interface for browser
// ES6 版本，适配浏览器环境

const ft_render_fabric = () => import('./freetype_build/ft_render.js')

let m = null     // compiled module instance
let library = 0  // pointer to library struct in wasm memory

// workaround because of bug in emscripten:
// https://github.com/emscripten-core/emscripten/issues/5820
const runtime_initialized = new Promise(resolve => {
  ft_render_fabric().then(module => {
    module.default().then(module_instance => {
      m = module_instance
      resolve()
    })
  })
})

function from_16_16(fixed_point) {
  return fixed_point / (1 << 16)
}

function from_26_6(fixed_point) {
  return fixed_point / (1 << 6)
}

function int8_to_uint8(value) {
  return value >= 0 ? value : value + 0x100
}

let FT_New_Memory_Face,
    FT_Set_Char_Size,
    FT_Set_Pixel_Sizes,
    FT_Get_Char_Index,
    FT_Load_Glyph,
    FT_Get_Sfnt_Table,
    FT_Get_Kerning,
    FT_Done_Face

export async function init() {
  await runtime_initialized
  m._init_constants()

  FT_New_Memory_Face = 
    m.cwrap('FT_New_Memory_Face', 'number', [ 'number', 'number', 'number', 'number', 'number' ])

  FT_Set_Char_Size = 
    m.cwrap('FT_Set_Char_Size', 'number', [ 'number', 'number', 'number', 'number', 'number' ])

  FT_Set_Pixel_Sizes = 
    m.cwrap('FT_Set_Pixel_Sizes', 'number', [ 'number', 'number', 'number' ])

  FT_Get_Char_Index = 
    m.cwrap('FT_Get_Char_Index', 'number', [ 'number', 'number' ])

  FT_Load_Glyph = 
    m.cwrap('FT_Load_Glyph', 'number', [ 'number', 'number', 'number' ])

  FT_Get_Sfnt_Table = 
    m.cwrap('FT_Get_Sfnt_Table', 'number', [ 'number', 'number' ])

  FT_Get_Kerning = 
    m.cwrap('FT_Get_Kerning', 'number', [ 'number', 'number', 'number', 'number', 'number' ])

  FT_Done_Face = 
    m.cwrap('FT_Done_Face', 'number', [ 'number' ])

  if (!library) {
    let ptr = m._malloc(4)

    try {
      let error = m.ccall('FT_Init_FreeType', 'number', [ 'number' ], [ ptr ])

      if (error) throw new Error(`error in FT_Init_FreeType: ${error}`)

      library = m.getValue(ptr, 'i32')
    } finally {
      m._free(ptr)
    }
  }
}

export function fontface_create(source, size) {
  let error

  // 正确计算字体数据的长度
  let fontLength
  if (source instanceof ArrayBuffer) {
    fontLength = source.byteLength
  } else if (source instanceof Uint8Array) {
    fontLength = source.byteLength
  } else if (source && typeof source.length === 'number') {
    fontLength = source.length
  } else {
    throw new Error('Invalid font source format')
  }

  let face = {
    ptr: 0,
    font: m._malloc(fontLength)
  }

  // 将 ArrayBuffer 或 Uint8Array 转换为内存
  const sourceArray = source instanceof ArrayBuffer ? new Uint8Array(source) : source
  m.writeArrayToMemory(sourceArray, face.font)

  let ptr = m._malloc(4)

  try {
    error = FT_New_Memory_Face(library, face.font, fontLength, 0, ptr)

    if (error) throw new Error(`error in FT_New_Memory_Face: ${error}`)

    face.ptr = m.getValue(ptr, 'i32')
  } finally {
    m._free(ptr)
  }

  error = FT_Set_Char_Size(face.ptr, 0, size * 64, 300, 300)

  if (error) throw new Error(`error in FT_Set_Char_Size: ${error}`)

  error = FT_Set_Pixel_Sizes(face.ptr, 0, size)

  if (error) throw new Error(`error in FT_Set_Pixel_Sizes: ${error}`)

  let units_per_em = m.getValue(face.ptr + m.OFFSET_FACE_UNITS_PER_EM, 'i16')
  let ascender     = m.getValue(face.ptr + m.OFFSET_FACE_ASCENDER, 'i16')
  let descender    = m.getValue(face.ptr + m.OFFSET_FACE_DESCENDER, 'i16')
  let height       = m.getValue(face.ptr + m.OFFSET_FACE_HEIGHT, 'i16')

  return Object.assign(face, {
    units_per_em,
    ascender,
    descender,
    height
  })
}

export function fontface_os2_table(face) {
  let sfnt_ptr = FT_Get_Sfnt_Table(face.ptr, m.FT_SFNT_OS2)

  if (!sfnt_ptr) throw new Error('os/2 table not found for this font')

  let typoAscent  = m.getValue(sfnt_ptr + m.OFFSET_TT_OS2_ASCENDER, 'i16')
  let typoDescent = m.getValue(sfnt_ptr + m.OFFSET_TT_OS2_DESCENDER, 'i16')
  let typoLineGap = m.getValue(sfnt_ptr + m.OFFSET_TT_OS2_LINEGAP, 'i16')

  return {
    typoAscent,
    typoDescent,
    typoLineGap
  }
}

export function get_kerning(face, code1, code2) {
  let glyph1 = FT_Get_Char_Index(face.ptr, code1)
  let glyph2 = FT_Get_Char_Index(face.ptr, code2)
  let ptr = m._malloc(4 * 2)

  try {
    let error = FT_Get_Kerning(face.ptr, glyph1, glyph2, m.FT_KERNING_DEFAULT, ptr)

    if (error) throw new Error(`error in FT_Get_Kerning: ${error}`)

    return {
      x: from_26_6(m.getValue(ptr, 'i32')),
      y: from_26_6(m.getValue(ptr + 4, 'i32'))
    }
  } finally {
    m._free(ptr)
  }
}

export function glyph_exists(face, code) {
  let glyph_index = FT_Get_Char_Index(face.ptr, code)

  return glyph_index !== 0
}

export function glyph_render(face, code, opts = {}) {
  let glyph_index = FT_Get_Char_Index(face.ptr, code)

  if (glyph_index === 0) throw new Error(`glyph does not exist for codepoint ${code}`)

  let load_flags = m.FT_LOAD_RENDER

  if (opts.mono) {
    load_flags |= m.FT_LOAD_TARGET_MONO

  } else if (opts.lcd) {
    load_flags |= m.FT_LOAD_TARGET_LCD

  } else if (opts.lcd_v) {
    load_flags |= m.FT_LOAD_TARGET_LCD_V

  } else {
    /* eslint-disable no-lonely-if */

    // Use "light" by default, it changes horizontal lines only.
    // "normal" is more strong (with vertical lines), but will break kerning, if
    // no additional care taken. More advanced rendering requires upper level
    // layout support (via Harfbuzz, for example).
    if (!opts.autohint_strong) load_flags |= m.FT_LOAD_TARGET_LIGHT
    else load_flags |= m.FT_LOAD_TARGET_NORMAL
  }

  if (opts.autohint_off) load_flags |= m.FT_LOAD_NO_AUTOHINT
  else load_flags |= m.FT_LOAD_FORCE_AUTOHINT

  if (opts.use_color_info) load_flags |= m.FT_LOAD_COLOR

  let error = FT_Load_Glyph(face.ptr, glyph_index, load_flags)

  if (error) throw new Error(`error in FT_Load_Glyph: ${error}`)

  let glyph = m.getValue(face.ptr + m.OFFSET_FACE_GLYPH, 'i32')

  let glyph_data = {
    glyph_index: m.getValue(glyph + m.OFFSET_GLYPH_INDEX, 'i32'),
    metrics: {
      width:        from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_WIDTH, 'i32')),
      height:       from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_HEIGHT, 'i32')),
      horiBearingX: from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_HORI_BEARING_X, 'i32')),
      horiBearingY: from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_HORI_BEARING_Y, 'i32')),
      horiAdvance:  from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_HORI_ADVANCE, 'i32')),
      vertBearingX: from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_VERT_BEARING_X, 'i32')),
      vertBearingY: from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_VERT_BEARING_Y, 'i32')),
      vertAdvance:  from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_METRICS_VERT_ADVANCE, 'i32'))
    },
    linearHoriAdvance: from_16_16(m.getValue(glyph + m.OFFSET_GLYPH_LINEAR_HORI_ADVANCE, 'i32')),
    linearVertAdvance: from_16_16(m.getValue(glyph + m.OFFSET_GLYPH_LINEAR_VERT_ADVANCE, 'i32')),
    advance: {
      x: from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_ADVANCE_X, 'i32')),
      y: from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_ADVANCE_Y, 'i32'))
    },
    bitmap: {
      width:        m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_WIDTH, 'i32'),
      rows:         m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_ROWS, 'i32'),
      pitch:        m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_PITCH, 'i32'),
      num_grays:    m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_NUM_GRAYS, 'i16'),
      pixel_mode:   m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_PIXEL_MODE, 'i8'),
      palette_mode: m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_PALETTE_MODE, 'i8')
    },
    bitmap_left: m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_LEFT, 'i32'),
    bitmap_top:  m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_TOP, 'i32'),
    lsb_delta:   from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_LSB_DELTA, 'i32')),
    rsb_delta:   from_26_6(m.getValue(glyph + m.OFFSET_GLYPH_RSB_DELTA, 'i32'))
  }

  let g_w = glyph_data.bitmap.width
  let g_h = glyph_data.bitmap.rows
  let g_x = glyph_data.bitmap_left
  let g_y = glyph_data.bitmap_top

  let buffer = m.getValue(glyph + m.OFFSET_GLYPH_BITMAP_BUFFER, 'i32')
  let pitch  = Math.abs(glyph_data.bitmap.pitch)

  let advance_x = glyph_data.linearHoriAdvance
  let advance_y = glyph_data.linearVertAdvance

  let pixel_mode = glyph_data.bitmap.pixel_mode

  let output = []

  for (let y = 0; y < g_h; y++) {
    let row_start = buffer + y * pitch
    let line = []

    for (let x = 0; x < g_w; x++) {
      if (pixel_mode === m.FT_PIXEL_MODE_MONO) {
        let value = m.getValue(row_start + ~~(x / 8), 'i8')
        line.push(value & (1 << (7 - (x % 8))) ? 255 : 0)
      } else if (pixel_mode === m.FT_PIXEL_MODE_BGRA) {
        let blue  = int8_to_uint8(m.getValue(row_start + (x * 4) + 0, 'i8'))
        let green = int8_to_uint8(m.getValue(row_start + (x * 4) + 1, 'i8'))
        let red   = int8_to_uint8(m.getValue(row_start + (x * 4) + 2, 'i8'))
        let alpha = int8_to_uint8(m.getValue(row_start + (x * 4) + 3, 'i8'))
        // convert RGBA to grayscale
        let grayscale = Math.round(0.299 * red + 0.587 * green + 0.114 * blue)
        if (grayscale > 255) grayscale = 255
        // meld grayscale into alpha channel
        alpha = ((255 - grayscale) * alpha) / 255
        line.push(alpha)
      } else {
        let value = m.getValue(row_start + x, 'i8')
        line.push(int8_to_uint8(value))
      }
    }

    output.push(line)
  }

  return {
    x: g_x,
    y: g_y,
    width: g_w,
    height: g_h,
    advance_x,
    advance_y,
    pixels: output,
    freetype: glyph_data
  }
}

export function fontface_destroy(face) {
  let error = FT_Done_Face(face.ptr)

  if (error) throw new Error(`error in FT_Done_Face: ${error}`)

  m._free(face.font)
  face.ptr = 0
  face.font = 0
}

export function destroy() {
  let error = m.ccall('FT_Done_FreeType', 'number', [ 'number' ], [ library ])

  if (error) throw new Error(`error in FT_Done_FreeType: ${error}`)

  library = 0

  // don't unload wasm - slows down tests too much
  //m = null
}

// Merge ranges into single object
// ES6 版本

class Ranger {
  constructor() {
    this.data = {}
  }

  // input:
  //  -r 0x1F450 - single value, dec or hex format
  //  -r 0x1F450-0x1F470 - range
  //  -r 0x1F450=>0xF005 - single glyph with mapping
  //  -r 0x1F450-0x1F470=>0xF005 - range with mapping
  add_range(font, start, end, mapped_start) {
    let offset = mapped_start - start
    let output = []

    for (let i = start; i <= end; i++) {
      this._set_char(font, i, i + offset)
      output.push(i)
    }

    return output
  }

  // input: characters to copy, e.g. '1234567890abcdef'
  add_symbols(font, str) {
    let output = []

    for (let chr of str) {
      let code = chr.codePointAt(0)
      this._set_char(font, code, code)
      output.push(code)
    }

    return output
  }

  _set_char(font, code, mapped_to) {
    this.data[mapped_to] = { font, code }
  }

  get() {
    return this.data
  }
}

export default Ranger

// Font processing utilities
// ES6 版本，适配浏览器环境

function set_byte_depth(depth) {
  return function (byte) {
    // calculate significant bits, e.g. for depth=2 it's 0, 1, 2 or 3
    let value = ~~(byte / (256 >> depth))

    // spread those bits around 0..255 range, e.g. for depth=2 it's 0, 85, 170 or 255
    let scale = (2 << (depth - 1)) - 1

    return (value * 0xFFFF / scale) >> 8
  }
}

export function set_depth(glyph, depth) {
  let pixels = []
  let fn = set_byte_depth(depth)

  for (let y = 0; y < glyph.bbox.height; y++) {
    pixels.push(glyph.pixels[y].map(fn))
  }

  return Object.assign({}, glyph, { pixels })
}

function count_bits(val) {
  let count = 0
  val = ~~val

  while (val) {
    count++
    val >>= 1
  }

  return count
}

// Minimal number of bits to store unsigned value
export const unsigned_bits = count_bits

// Minimal number of bits to store signed value
export function signed_bits(val) {
  if (val >= 0) return count_bits(val) + 1

  return count_bits(Math.abs(val) - 1) + 1
}

// Align value to 4x - useful to create word-aligned arrays
function align4(size) {
  if (size % 4 === 0) return size
  return size + 4 - (size % 4)
}

export { align4 }

// Align buffer length to 4x (returns copy with zero-filled tail)
export function balign4(buf) {
  const alignedLength = align4(buf.length)
  const alignedBuf = new Uint8Array(alignedLength)
  alignedBuf.set(new Uint8Array(buf))
  return alignedBuf.buffer
}

// Pre-filter image to improve compression ratio
// In this case - XOR lines, because it's very effective
// in decompressor and does not depend on bpp.
export function prefilter(pixels) {
  return pixels.map((line, l_idx, arr) => {
    if (l_idx === 0) return line.slice()

    return line.map((p, idx) => p ^ arr[l_idx - 1][idx])
  })
}

// Convert array with uint16 data to buffer
export function bFromA16(arr) {
  const buf = new ArrayBuffer(arr.length * 2)
  const view = new DataView(buf)

  for (let i = 0; i < arr.length; i++) {
    view.setUint16(i * 2, arr[i], true) // little endian
  }

  return buf
}

// Convert array with uint32 data to buffer
export function bFromA32(arr) {
  const buf = new ArrayBuffer(arr.length * 4)
  const view = new DataView(buf)

  for (let i = 0; i < arr.length; i++) {
    view.setUint32(i * 4, arr[i], true) // little endian
  }

  return buf
}

function chunk(arr, size) {
  const result = []
  for (let i = 0; i < arr.length; i += size) {
    result.push(arr.slice(i, i + size))
  }
  return result
}

// Dump long array to multiline format with X columns and Y indent
export function long_dump(arr, options = {}) {
  const defaults = {
    col: 8,
    indent: 4,
    hex: false
  }

  let opts = Object.assign({}, defaults, options)
  let indent = ' '.repeat(opts.indent)

  return chunk(Array.from(arr), opts.col)
    .map(l => l.map(v => (opts.hex ? `0x${v.toString(16)}` : v.toString())))
    .map(l => `${indent}${l.join(', ')}`)
    .join(',\n')
}

// stable sort by pick() result
export function sort_by(arr, pick) {
  return arr
    .map((el, idx) => ({ el, idx }))
    .sort((a, b) => (pick(a.el) - pick(b.el)) || (a.idx - b.idx))
    .map(({ el }) => el)
}

export function sum(arr) {
  return arr.reduce((a, v) => a + v, 0)
}

// 默认导出所有函数
const utils = {
  set_depth,
  unsigned_bits,
  signed_bits,
  align4,
  balign4,
  prefilter,
  bFromA16,
  bFromA32,
  long_dump,
  sort_by,
  sum
}

export default utils

// Find an optimal configuration of cmap tables representing set of codepoints,
// using simple breadth-first algorithm
//
// Assume that:
//  - codepoints have one-to-one correspondence to glyph ids
//  - glyph ids are always bigger for bigger codepoints
//  - glyph ids are always consecutive (1..N without gaps)
//
// This way we can omit glyph ids from all calculations entirely: if codepoints
// fit in format0, then glyph ids also will.
//
// format6 is not considered, because if glyph ids can be delta-coded,
// multiple format0 tables are guaranteed to be smaller than a single format6.
//
// sparse format is not used because as long as glyph ids are consecutive,
// sparse_tiny will always be preferred.
//

'use strict';


function estimate_format0_tiny_size(/*start_code, end_code*/) {
  return 16;
}

function estimate_format0_size(start_code, end_code) {
  return 16 + (end_code - start_code + 1);
}

//function estimate_sparse_size(count) {
//  return 16 + count * 4;
//}

function estimate_sparse_tiny_size(count) {
  return 16 + count * 2;
}

export default function cmap_split(all_codepoints) {
  all_codepoints = all_codepoints.sort((a, b) => a - b);

  let min_paths = [];

  for (let i = 0; i < all_codepoints.length; i++) {
    let min = { dist: Infinity };

    for (let j = 0; j <= i; j++) {
      let prev_dist = (j - 1 >= 0) ? min_paths[j - 1].dist : 0;
      let s;

      if (all_codepoints[i] - all_codepoints[j] < 256) {
        s = estimate_format0_size(all_codepoints[j], all_codepoints[i]);

        /* eslint-disable max-depth */
        if (prev_dist + s < min.dist) {
          min = {
            dist: prev_dist + s,
            start: j,
            end: i,
            format: 'format0'
          };
        }
      }

      if (all_codepoints[i] - all_codepoints[j] < 256 && all_codepoints[i] - i === all_codepoints[j] - j) {
        s = estimate_format0_tiny_size(all_codepoints[j], all_codepoints[i]);

        /* eslint-disable max-depth */
        if (prev_dist + s < min.dist) {
          min = {
            dist: prev_dist + s,
            start: j,
            end: i,
            format: 'format0_tiny'
          };
        }
      }

      // tiny sparse will always be preferred over full sparse because glyph ids are consecutive
      if (all_codepoints[i] - all_codepoints[j] < 65536) {
        s = estimate_sparse_tiny_size(i - j + 1);

        if (prev_dist + s < min.dist) {
          min = {
            dist: prev_dist + s,
            start: j,
            end: i,
            format: 'sparse_tiny'
          };
        }
      }
    }

    min_paths[i] = min;
  }

  let result = [];

  for (let i = all_codepoints.length - 1; i >= 0;) {
    let path = min_paths[i];
    result.unshift([ path.format, all_codepoints.slice(path.start, path.end + 1) ]);
    i = path.start - 1;
  }

  return result;
}

// CBIN Font writer - 严格按照官方实现（浏览器兼容版）
// 遵循 font_conv_lib/writers/cbin/ 的格式

import AppError from '../AppError.js';
import cmap_build_subtables from '../cmap_build_subtables.js';

// 32位指针大小，保持与官方一致
const ptr_size = 4;

// 浏览器版本的 writeUInt64LE 实现
const writeUInt64LE = (view, val, pos) => {
  view.setUint32(pos, val, true);
  view.setUint32(pos + 4, 0, true);
};

class CBinFont {
  constructor(fontData, options) {
    this.src = fontData;
    this.opts = options;

    this.font_name = options.lv_font_name;
    if (!this.font_name) {
      this.font_name = options.output || 'font';
    }

    if (options.bpp === 3 && options.no_compress) {
      throw new AppError('LVGL supports "--bpp 3" with compression only');
    }

    // 初始化各个表格处理器
    this.init_tables();
  }

  init_tables() {
    this.head = new HeadTable(this);
    this.glyf = new GlyfTable(this); 
    this.cmap = new CmapTable(this);
    this.kern = new KernTable(this);
  }

  toCBin() {
    // 严格按照 lv_font.js 的实现（浏览器兼容版）
    const [bitmap_buf, glyph_dsc_buf] = this.glyf.toCBin();
    const cmaps_buf = this.cmap.toCBin(ptr_size);
    const kern_buf = this.kern.toCBin(ptr_size);

    const sz_font = 12 + ptr_size * 6 + (ptr_size == 4 ? 0 : 4); // add pad, see below
    const sz_font_dsc = 8 + ptr_size * 4; // add space for stride
    const head_buf = new ArrayBuffer(sz_font + sz_font_dsc);
    const head_view = new DataView(head_buf);

    const writePTR = ptr_size == 4 ? 
      (val, pos) => head_view.setUint32(pos, val, true) : 
      (val, pos) => writeUInt64LE(head_view, val, pos);

    var pos = 0;
    // write lv_font_t 
    writePTR(0, pos); pos += ptr_size;
    writePTR(0, pos); pos += ptr_size;
    writePTR(0, pos); pos += ptr_size;
    head_view.setUint32(pos, this.src.ascent - this.src.descent, true); pos += 4; // line_height
    head_view.setInt32(pos, -this.src.descent, true); pos += 4; // base_line

    head_view.setUint8(pos, this.src.subpixels_mode || 0); pos += 1;
    head_view.setInt8(pos, this.src.underlinePosition || 0); pos += 1;
    head_view.setInt8(pos, this.src.underlineThickness || 0); pos += 1;
    pos += 1 + (ptr_size == 4 ? 0 : 4); // pad

    writePTR(sz_font, pos); pos += ptr_size; // offset relative to start of lv_font_t
    writePTR(0, pos); pos += ptr_size;
    writePTR(0, pos); pos += ptr_size;

    const kern = this.head.kern_ref();
    // write lv_font_fmt_txt_dsc_t
    writePTR(sz_font_dsc + kern_buf.byteLength, pos); pos += ptr_size;  // glyph_bitmap offset relative to start of lv_font_fmt_txt_dsc_t
    writePTR(sz_font_dsc + kern_buf.byteLength + bitmap_buf.byteLength, pos); pos += ptr_size;  // glyph_dsc ofs
    writePTR(sz_font_dsc + kern_buf.byteLength + bitmap_buf.byteLength + glyph_dsc_buf.byteLength, pos); pos += ptr_size;  // cmaps ofs
    writePTR(kern.dsc === 'NULL' ? 0 : sz_font_dsc, pos); pos += ptr_size; // kern ofs
    head_view.setUint16(pos, kern.scale, true); pos += 2;

    const cmap_num = this.cmap.getMapNumber();
    const bpp = this.opts.bpp;
    const kern_classes = kern.classes;
    const bitmap_format = this.glyf.getCompressionCode();
    head_view.setUint16(pos, cmap_num | (bpp << 9) | (kern_classes << (9 + 4)) | (bitmap_format << (9 + 4 + 1)), true); pos += 2;

    return this.concatArrayBuffers([
      head_buf,
      kern_buf,
      bitmap_buf,
      glyph_dsc_buf,
      cmaps_buf
    ]);
  }

  concatArrayBuffers(buffers) {
    // 浏览器兼容的 ArrayBuffer 合并方法
    const totalLength = buffers.reduce((sum, buf) => sum + buf.byteLength, 0);
    const result = new ArrayBuffer(totalLength);
    const view = new Uint8Array(result);

    let offset = 0;
    for (const buf of buffers) {
      view.set(new Uint8Array(buf), offset);
      offset += buf.byteLength;
    }

    return result;
  }
}

// 各个表格处理类的实现

// Head 表格处理器
class HeadTable {
  constructor(font) {
    this.font = font;
  }

  kern_ref() {
    const f = this.font;

    // 简化版：不支持 kerning
    return {
      scale: 0,
      dsc: 'NULL', 
      classes: 0
    };
  }
}

// 浏览器兼容的简化 BitStream 实现
class SimpleBitStream {
  constructor(buffer) {
    this.buffer = new Uint8Array(buffer);
    this.byteIndex = 0;
    this.bitIndex = 0;
    this.bigEndian = true;
  }

  writeBits(value, bits) {
    while (bits > 0) {
      const bitsToWrite = Math.min(8 - this.bitIndex, bits);
      const mask = (1 << bitsToWrite) - 1;
      const bitValue = (value >> (bits - bitsToWrite)) & mask;

      if (this.bigEndian) {
        this.buffer[this.byteIndex] |= (bitValue << (8 - this.bitIndex - bitsToWrite));
      } else {
        this.buffer[this.byteIndex] |= (bitValue << this.bitIndex);
      }

      this.bitIndex += bitsToWrite;
      if (this.bitIndex >= 8) {
        this.byteIndex++;
        this.bitIndex = 0;
      }

      bits -= bitsToWrite;
    }
  }

  getUsedBytes() {
    return this.bitIndex > 0 ? this.byteIndex + 1 : this.byteIndex;
  }
}

// Glyf 表格处理器 - 严格按照官方 lv_table_glyf.js 实现
class GlyfTable {
  constructor(font) {
    this.font = font;
    this.lv_data = [];
    this.lv_compiled = false;
  }

  // 严格按照官方 table_glyf.js 的 pixelsToBpp 实现
  pixelsToBpp(pixels) {
    const bpp = this.font.opts.bpp;
    return pixels.map(line => line.map(p => (p >>> (8 - bpp))));
  }

  // 严格按照官方的 storePixels 实现
  storePixels(bitStream, pixels) {
    if (this.getCompressionCode() === 0) this.storePixelsRaw(bitStream, pixels);
    else this.storePixelsCompressed(bitStream, pixels);
  }

  storePixelsRaw(bitStream, pixels) {
    const bpp = this.font.opts.bpp;

    for (let y = 0; y < pixels.length; y++) {
      const line = pixels[y];
      for (let x = 0; x < line.length; x++) {
        bitStream.writeBits(line[x], bpp);
      }
    }
  }

  storePixelsCompressed(bitStream, pixels) {
    // 简化版：暂不支持压缩，直接调用 raw 版本
    this.storePixelsRaw(bitStream, pixels);
  }

  lv_bitmap(glyph) {
    // 严格按照官方实现
    const bufSize = 100 + glyph.bbox.width * glyph.bbox.height * 4;
    const buf = new ArrayBuffer(bufSize);
    const bs = new SimpleBitStream(buf);
    bs.bigEndian = true;

    const pixels = this.pixelsToBpp(glyph.pixels);
    this.storePixels(bs, pixels);

    // 创建实际使用的 buffer
    const glyph_bitmap = new ArrayBuffer(bs.getUsedBytes());
    const srcView = new Uint8Array(buf);
    const destView = new Uint8Array(glyph_bitmap);
    destView.set(srcView.subarray(0, bs.getUsedBytes()));

    return glyph_bitmap;
  }

  lv_compile() {
    if (this.lv_compiled) return;

    this.lv_compiled = true;

    const f = this.font;
    this.lv_data = [];
    let offset = 0;

    // 严格按照官方逻辑：使用 f.glyph_id[g.code] 作为索引
    f.src.glyphs.forEach(g => {
      const id = f.glyph_id[g.code];
      const bin = this.lv_bitmap(g);
      this.lv_data[id] = {
        bin,
        offset,
        glyph: g
      };
      offset += bin.byteLength;
    });
  }

  toCBin() {
    // LV_FONT_FMT_TXT_LARGE == 1
    this.lv_compile();

    // 严格按照官方实现：slice(1) 跳过索引0，然后过滤有效数据
    const validBins = this.lv_data.slice(1).filter(d => d).map(d => d.bin);
    const bitmap_buf = this.balign4(this.concatArrayBuffers(validBins));
    const glyph_dsc_buf = new ArrayBuffer(this.lv_data.length * 16 + 16);
    const glyph_dsc_view = new DataView(glyph_dsc_buf);

    let i = 1;
    this.lv_data.forEach(d => {
      if (d) {
        const adv_w = Math.round(d.glyph.advanceWidth * 16);
        glyph_dsc_view.setUint32(i * 16, d.offset, true);
        glyph_dsc_view.setUint32(i * 16 + 4, adv_w, true);
        glyph_dsc_view.setUint16(i * 16 + 8, d.glyph.bbox.width, true);
        glyph_dsc_view.setUint16(i * 16 + 10, d.glyph.bbox.height, true);
        glyph_dsc_view.setInt16(i * 16 + 12, d.glyph.bbox.x, true);
        glyph_dsc_view.setInt16(i * 16 + 14, d.glyph.bbox.y, true);
      }
      i++;
    });

    return [bitmap_buf, glyph_dsc_buf];
  }

  balign4(buf) {
    const remainder = buf.byteLength % 4;
    if (remainder === 0) return buf;
    const padding = 4 - remainder;
    const paddingBuf = new ArrayBuffer(padding);
    return this.concatArrayBuffers([buf, paddingBuf]);
  }

  concatArrayBuffers(buffers) {
    const totalLength = buffers.reduce((sum, buf) => sum + buf.byteLength, 0);
    const result = new ArrayBuffer(totalLength);
    const view = new Uint8Array(result);

    let offset = 0;
    for (const buf of buffers) {
      view.set(new Uint8Array(buf), offset);
      offset += buf.byteLength;
    }

    return result;
  }

  getCompressionCode() {
    if (this.font.opts.no_compress) return 0;
    if (this.font.opts.bpp === 1) return 0;

    if (this.font.opts.no_prefilter) return 2;
    return 1;
  }
}

// Cmap 表格处理器 - 严格按照官方 lv_table_cmap.js 实现
class CmapTable {
  constructor(font) {
    this.font = font;
    this.lv_compiled = false;
    this.lv_subtables = [];
    this.subtables_plan = null;

    // 建立字形ID映射，按照官方逻辑
    this.buildGlyphIdMap();
  }

  buildGlyphIdMap() {
    const f = this.font;
    f.glyph_id = {};

    if (f.src.glyphs) {
      f.src.glyphs.forEach((glyph, index) => {
        f.glyph_id[glyph.code] = index + 1; // 字形ID从1开始
      });
    }
  }

  lv_format2enum(name) {
    switch (name) {
      case 'format0_tiny': return 'LV_FONT_FMT_TXT_CMAP_FORMAT0_TINY';
      case 'format0': return 'LV_FONT_FMT_TXT_CMAP_FORMAT0_FULL';
      case 'sparse_tiny': return 'LV_FONT_FMT_TXT_CMAP_SPARSE_TINY';
      case 'sparse': return 'LV_FONT_FMT_TXT_CMAP_SPARSE_FULL';
      default: throw new Error('Unknown subtable format');
    }
  }

  lv_format2int(name) {
    return ['format0','sparse','format0_tiny','sparse_tiny'].indexOf(name);
  }

  getMapNumber() {
    // 返回子表数量，需要先确保已经生成了子表计划
    if (!this.subtables_plan) {
      const f = this.font;
      if (!f.src.glyphs || f.src.glyphs.length === 0) {
        return 0;
      }
      this.subtables_plan = cmap_build_subtables(f.src.glyphs.map(g => g.code));
    }
    return this.subtables_plan.length;
  }

  glyphByCode(code) {
    const f = this.font;
    return f.src.glyphs ? f.src.glyphs.find(g => g.code === code) : null;
  }

  collect_format0_data(min_code, max_code, start_glyph_id) {
    const f = this.font;
    const data = [];

    for (let code = min_code; code <= max_code; code++) {
      const glyph_id = f.glyph_id[code] || 0;
      // format0的数据格式是相对于start_glyph_id的偏移
      data.push(glyph_id ? glyph_id - start_glyph_id : 0);
    }

    return data;
  }

  collect_sparse_data(codepoints, start_glyph_id) {
    const f = this.font;
    let codepoints_list = [];
    let ids_list = [];

    for (let code of codepoints) {
      let g = this.glyphByCode(code);
      let id = f.glyph_id[g.code];

      let code_delta = code - codepoints[0];  // 关键：相对于第一个代码点的偏移
      let id_delta = id - start_glyph_id;

      if (code_delta < 0 || code_delta > 65535) throw new Error('Codepoint delta out of range');
      if (id_delta < 0 || id_delta > 65535) throw new Error('Glyph ID delta out of range');

      codepoints_list.push(code_delta);  // 推入 delta，不是原始 code
      ids_list.push(id_delta);
    }

    return {
      codes: codepoints_list,
      ids: ids_list
    };
  }

  toCBin(ptr_size) {
    const f = this.font;

    if (!f.src.glyphs || f.src.glyphs.length === 0) {
      return new ArrayBuffer(0);
    }

    // 确保只计算一次 subtables_plan
    if (!this.subtables_plan) {
      this.subtables_plan = cmap_build_subtables(f.src.glyphs.map(g => g.code));
    }
    const subtables_plan = this.subtables_plan;
    let idx = 0;

    const cmap_size = 12 + ptr_size * 2 + (ptr_size == 4 ? 0 : 4);
    const cmaps_buf = new ArrayBuffer(subtables_plan.length * cmap_size);
    const cmaps_view = new DataView(cmaps_buf);

    const writePTR = ptr_size == 4 ? 
      (val, ofs) => cmaps_view.setUint32(ofs, val, true) : 
      (val, ofs) => writeUInt64LE(cmaps_view, val, ofs);

    const arr_list = [];
    let total_data_offset = cmaps_buf.byteLength;

    for (let [format, codepoints] of subtables_plan) {
      let g = this.glyphByCode(codepoints[0]);
      let start_glyph_id = f.glyph_id[g.code];
      let min_code = codepoints[0];
      let max_code = codepoints[codepoints.length - 1];

      let has_charcodes = false;
      let has_ids = false;
      let entries_count = 0;

      let glyph_ptr = new ArrayBuffer(0);
      let unicode_ptr = new ArrayBuffer(0);

      if (format === 'format0_tiny') {
        // use default empty values
      } else if (format === 'format0') {
        has_ids = true;
        let d = this.collect_format0_data(min_code, max_code, start_glyph_id);
        entries_count = d.length;
        // 严格按照官方：Buffer.from(d)
        glyph_ptr = this.balign4(this.uint8ArrayToBuffer(new Uint8Array(d)));
      } else if (format === 'sparse_tiny') {
        has_charcodes = true;
        let d = this.collect_sparse_data(codepoints, start_glyph_id);
        entries_count = d.codes.length;
        unicode_ptr = this.balign4(this.uint16ArrayToBuffer(new Uint16Array(d.codes)));
      } else { // assume format === 'sparse'
        has_charcodes = true;
        has_ids = true;
        let d = this.collect_sparse_data(codepoints, start_glyph_id);
        entries_count = d.codes.length;
        unicode_ptr = this.balign4(this.uint16ArrayToBuffer(new Uint16Array(d.codes)));
        glyph_ptr = this.align4(this.uint16ArrayToBuffer(new Uint16Array(d.ids)));
      }

      // 写入 cmap 头部 - 严格按照官方逻辑
      let ofs = idx * cmap_size;
      cmaps_view.setUint32(ofs, min_code, true); ofs += 4;
      cmaps_view.setUint16(ofs, max_code - min_code + 1, true); ofs += 2;
      cmaps_view.setUint16(ofs, start_glyph_id, true); ofs += 2;
      // 关键：写入指针的同时立即更新 total_data_offset
      writePTR(has_charcodes ? total_data_offset : 0, ofs); ofs += ptr_size; 
      total_data_offset += unicode_ptr.byteLength;
      writePTR(has_ids ? total_data_offset : 0, ofs); ofs += ptr_size; 
      total_data_offset += glyph_ptr.byteLength;
      cmaps_view.setUint16(ofs, entries_count, true); ofs += 2;
      cmaps_view.setUint8(ofs, this.lv_format2int(format)); ofs += 1;

      arr_list.push(unicode_ptr);
      arr_list.push(glyph_ptr);

      idx++;
    }
    return this.concatArrayBuffers([cmaps_buf, ...arr_list]);
  }

  balign4(buf) {
    const remainder = buf.byteLength % 4;
    if (remainder === 0) return buf;
    const padding = 4 - remainder;
    const paddingBuf = new ArrayBuffer(padding);
    return this.concatArrayBuffers([buf, paddingBuf]);
  }

  align4(buf) {
    const remainder = buf.byteLength % 4;
    if (remainder === 0) return buf;
    const padding = 4 - remainder;
    const paddingBuf = new ArrayBuffer(padding);
    return this.concatArrayBuffers([buf, paddingBuf]);
  }

  uint8ArrayToBuffer(uint8Array) {
    const buffer = new ArrayBuffer(uint8Array.byteLength);
    const view = new Uint8Array(buffer);
    view.set(uint8Array);
    return buffer;
  }

  uint16ArrayToBuffer(uint16Array) {
    // 严格按照官方的处理方式：直接使用 Uint16Array 的 buffer
    // 这等价于官方的 Buffer.from(Uint16Array.from(d.codes).buffer)
    return uint16Array.buffer.slice(0, uint16Array.byteLength);
  }

  concatArrayBuffers(buffers) {
    const totalLength = buffers.reduce((sum, buf) => sum + buf.byteLength, 0);
    const result = new ArrayBuffer(totalLength);
    const view = new Uint8Array(result);

    let offset = 0;
    for (const buf of buffers) {
      view.set(new Uint8Array(buf), offset);
      offset += buf.byteLength;
    }

    return result;
  }
}

