import { getActiveElement, focusFirstVisibleElement } from "./dom";

export const getVoteButton = (activeElement, voteType) => {
  if (activeElement.tagName === "ARTICLE") {
    return activeElement
      .querySelector("shreddit-post")
      .shadowRoot.querySelector(`button[${voteType}]`);
  } else if (activeElement.tagName === "SHREDDIT-COMMENT") {
    return activeElement
      .querySelector("shreddit-comment-action-row")
      .shadowRoot.querySelector(`button[${voteType}]`);
  }
  return null;
};

export const handleUpvote = () => {
  const activeElement = getActiveElement();
  if (!activeElement) return;

  const upvoteBtn = getVoteButton(activeElement, "upvote");
  upvoteBtn.click();
};

export const handleDownvote = () => {
  const activeElement = getActiveElement();
  if (!activeElement) return;

  const downvoteBtn = getVoteButton(activeElement, "downvote");
  if (downvoteBtn) {
    downvoteBtn.click();
  }
};

export const addComment = () => {
  let commentBtn;
  const activeElement = getActiveElement() || focusFirstVisibleElement();

  if (activeElement.tagName === "SHREDDIT-COMMENT") {
    commentBtn = activeElement.querySelector(
      "shreddit-comment-action-row faceplate-tracker button",
    );
  } else {
    commentBtn = activeElement
      .querySelector("shreddit-post")
      .shadowRoot.querySelector("a[data-post-click-location]");
  }

  commentBtn.click();
};

import { isVisible } from "./utils";

export const FOCUSSED_CLASSNAME = "vimmit-card__focussed";

export const focusElement = (element) => {
  if (!element) return;

  document
    .querySelectorAll(`.${FOCUSSED_CLASSNAME}`)
    .forEach((element) => element.classList.remove(FOCUSSED_CLASSNAME));

  element.classList.add(FOCUSSED_CLASSNAME);

  const elementHeight = element.offsetHeight;
  const viewportHeight = window.innerHeight;

  if (elementHeight > viewportHeight) {
    // For large posts/comment, scroll to place the top of the element in the
    // middle of the viewport.
    const elementTopRelativeToDocument =
      element.getBoundingClientRect().top + window.scrollY;
    const desiredScrollPosition =
      elementTopRelativeToDocument - viewportHeight / 3;

    window.scrollTo({
      top: desiredScrollPosition,
      behavior: "smooth",
    });
  } else {
    // For smaller posts/comments, center the entire element in the viewport.
    element.scrollIntoView({
      behavior: "smooth",
      block: "center",
    });
  }
};

export const getPostsAndComments = () => {
  return Array.from(
    document.querySelectorAll("shreddit-feed article, shreddit-comment"),
  );
};

export const getActiveElement = () => {
  return document.querySelector(`.${FOCUSSED_CLASSNAME}`);
};

export const focusFirstVisibleElement = (posts) => {
  for (const post of posts) {
    if (post && post.offsetParent && post.offsetParent !== null && post.offsetParent.offsetParent !== null && isVisible(post)) {
      focusElement(post);
      return post;
    }
  }

  focusElement(posts[0]);
  return posts[0];
};

import { disableKeybindings } from "./utils";
import {
  gotoNextPostOrComment,
  gotoPrevPostOrComment,
  selectPost,
  gotoNewPost,
  gotoHome,
  gotoPopularTab,
} from "./navigation";
import { handleUpvote, handleDownvote, addComment } from "./actions";

const KEYBINDINGS = {
  j: gotoNextPostOrComment,
  k: gotoPrevPostOrComment,
  u: handleUpvote,
  d: handleDownvote,
  c: addComment,
  Enter: selectPost,
  n: gotoNewPost,
  h: gotoHome,
  p: gotoPopularTab,
};

const keybindingsListener = (event) => {
  event.stopImmediatePropagation();
  if (disableKeybindings()) return;

  try {
    const handler = KEYBINDINGS[event.key];
    if (handler) {
      event.preventDefault();
      handler();
    }
  } catch (error) {
    console.error("Vimmit:", error);
  }
};

window.addEventListener("keydown", keybindingsListener, true);

import { getActiveElement, getPostsAndComments, focusElement, focusFirstVisibleElement } from "./dom";

export const gotoNextPostOrComment = () => {
  const posts = getPostsAndComments();
  if (posts.length === 0) return;

  const activeElement = getActiveElement();
  if (activeElement) {
    const currentIndex = posts.indexOf(activeElement);
    if (currentIndex < posts.length - 1) {
      focusElement(posts[currentIndex + 1]);
    }
    return;
  }

  focusFirstVisibleElement(posts);
};

export const gotoPrevPostOrComment = () => {
  const posts = getPostsAndComments();
  if (posts.length === 0) return;

  const activeElement = getActiveElement();
  if (activeElement) {
    const currentIndex = posts.indexOf(activeElement);
    if (currentIndex > 0) {
      focusElement(posts[currentIndex - 1]);
    }
    return;
  }

  focusFirstVisibleElement(posts);
};

export const selectPost = () => {
  const activeElement = getActiveElement();
  if (!activeElement) return;

  activeElement.querySelector("a").click();
};

export const gotoHome = () => {
  window.location.href = "/?feed=home";
};

export const gotoPopularTab = () => {
  window.location.href = "/r/popular";
};

export const gotoNewPost = () => {
  window.location.href = "/submit";
};

export const isVisible = (element) => {
  if (!element) return false;
  const rect = element.getBoundingClientRect();
  return (
    (rect.top >= 0 && rect.bottom <= window.innerHeight) ||
    (rect.top >= 0 && rect.bottom <= window.innerHeight)
  );
};

export const disableKeybindings = () => {
  const activeElement = document.activeElement;

  if (!activeElement) return false;

  // workaround: disable keybindings in settings
  if (window.location.href.includes("/settings")) {
    return true;
  }

  // workaround for messages tab
  if (activeElement.parentElement.tagName.toLowerCase() === "shreddit-app") {
    return true;
  }

  if (activeElement.contentEditable === "true") return true;

  const tagName = activeElement.tagName.toLowerCase();

  return [
    "input",
    "textarea",
    "select",
    "shreddit-composer", // comments input
    "faceplate-text-input", // comments input
    "reddit-search-large", // search bar
    "shreddit-slotter", // add communities form
    "custom-feed-details-form", // create custom feed form
  ].includes(tagName);
};

document.addEventListener("DOMContentLoaded", function () {
  const keybindingsList = document.getElementById("keybindings-list");

  const keybindings = {
    j: "Next Post/Comment",
    k: "Previous Post/Comment",
    u: "Upvote",
    d: "Downvote",
    c: "Add a comment",
    Enter: "Select/Open Post",
    n: "New Post",
    h: "Go to Home",
    p: "Go to Popular",
  };

  for (const key in keybindings) {
    const listItem = document.createElement("li");

    const keySpan = document.createElement("span");
    keySpan.className = "key";
    keySpan.textContent = key;

    const actionSpan = document.createElement("span");
    actionSpan.className = "action";
    actionSpan.textContent = keybindings[key];

    listItem.appendChild(actionSpan);
    listItem.appendChild(keySpan);

    keybindingsList.appendChild(listItem);
  }
});

