const rejectResponse = body => {
    const mention = body.item.message.from.mention_name;
    const responses = [
        `@${mention} You wish!`,
        `@${mention} Do I look like your meme monkey, ${body.item.message.from.name}?`,
        `@${mention} I don't feel like it.`,
        `@${mention} Yes?`,
        `@${mention} YOU SHALL NOT QUOTE!`,
        `@${mention} Nice try!`,
        `@${mention} Over my dead body.`,
        `@${mention} The bot you have called is currently not available.`,
        `@${mention} I'll do it later. I promise.`
    ];

    return responses[Math.floor(Math.random() * responses.length)];
};

const inspiroMe = async () => {
    return await fetch('http://inspirobot.me/api?generate=true')
        .then(response => response.text());
};

app.post('/inspirobot', async (req, res) => {
    try {
        if (Math.random() <= 0.2) {
            return res.json(fromText(rejectResponse(req.body)));
        }

        const url = await inspiroMe();
        return res.json(fromText(url));
    } catch (err) {
        console.error(err);
    }
});

app.listen(app.get('port'), () => {
    console.log(`Find the server at: http://localhost:${app.get('port')}/`);
});

'use strict';

const toStr = input => '' + input;
const defaultTo = (input, value) => input === null || input === undefined ? value : input;

module.exports = (input, len, char = ' ', rtl = false) => {
    const strInput = toStr(input);
    const pad = toStr(defaultTo(char, ' ')).repeat(Math.max(0, len - strInput.length));
    return rtl
        ? strInput + pad
        : pad + strInput;
};

const leftPad = require('./');
const test = require('tape');

test('leftPad', assert => {
    assert.plan(24);

    assert.strictEqual(leftPad('Foo', 5), '  Foo');
    assert.strictEqual(leftPad('Foo', 3), 'Foo');
    assert.strictEqual(leftPad('Foo', 1), 'Foo');
    assert.strictEqual(leftPad('Foo', -1), 'Foo');

    assert.strictEqual(leftPad('Foo', 5, 'x'), 'xxFoo');
    assert.strictEqual(leftPad('Foo', 3, 'x'), 'Foo');
    assert.strictEqual(leftPad('Foo', 1, 'x'), 'Foo');
    assert.strictEqual(leftPad('Foo', -1, 'x'), 'Foo');

    assert.strictEqual(leftPad(null, 1), 'null');
    assert.strictEqual(leftPad(null, 5), ' null');
    assert.strictEqual(leftPad(10, 4), '  10');
    assert.strictEqual(leftPad(10, 4, 0), '0010');

    assert.strictEqual(leftPad('Foo', 5, ' ', true), 'Foo  ');
    assert.strictEqual(leftPad('Foo', 3, ' ', true), 'Foo');
    assert.strictEqual(leftPad('Foo', 1, ' ', true), 'Foo');
    assert.strictEqual(leftPad('Foo', -1, ' ', true), 'Foo');

    assert.strictEqual(leftPad('Foo', 5, 'x', true), 'Fooxx');
    assert.strictEqual(leftPad('Foo', 3, 'x', true), 'Foo');
    assert.strictEqual(leftPad('Foo', 1, 'x', true), 'Foo');
    assert.strictEqual(leftPad('Foo', -1, 'x', true), 'Foo');

    assert.strictEqual(leftPad(null, 1, ' ', true), 'null');
    assert.strictEqual(leftPad(null, 5, ' ', true), 'null ');
    assert.strictEqual(leftPad(10, 4, ' ', true), '10  ');
    assert.strictEqual(leftPad(10, 4, 0, true), '1000');
});

