#!/usr/bin/env node

/**
 * Apply SVG frames (header and footer) to all markdown documents
 * Excludes: LICENSE, node_modules, .git, .venv, .serena, .pytest_cache
 */

import { execSync } from "node:child_process";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = join(__dirname, "..");

// Frame files
const HEADER_FILE = "docs/.frames-static/09-header.svg";
const FOOTER_FILE = "docs/.frames-static/09-footer.svg";

// Exclusion patterns
const EXCLUDE_PATTERNS = [
	"LICENSE",
	"LICENSE.md",
	"node_modules",
	".git",
	".venv",
	".serena",
	".pytest_cache",
	"dist-info",
];

/**
 * Check if a file path should be excluded
 */
function shouldExclude(filePath) {
	return EXCLUDE_PATTERNS.some((pattern) => filePath.includes(pattern));
}

/**
 * Find all markdown files in the repository
 */
function findMarkdownFiles() {
	try {
		const output = execSync('find . -name "*.md" -type f', {
			cwd: rootDir,
			encoding: "utf-8",
		});

		return output
			.split("\n")
			.filter((line) => line.trim())
			.filter((file) => !shouldExclude(file))
			.map((file) => file.replace(/^\.\//, ""));
	} catch (error) {
		console.error("Error finding markdown files:", error.message);
		return [];
	}
}

/**
 * Calculate relative path from markdown file to frame SVG
 */
function getRelativePath(markdownFile, svgFile) {
	const mdDir = dirname(markdownFile);
	const relPath = relative(mdDir, svgFile);
	// Normalize to forward slashes for SVG URLs
	return relPath.replace(/\\/g, "/");
}

/**
 * Remove existing frame markers from content
 */
function removeExistingFrames(content) {
	// Remove HTML comment markers and everything between them
	const headerPattern = /<!-- HEADER:START -->[\s\S]*?<!-- HEADER:END -->\n*/g;
	const footerPattern = /<!-- FOOTER:START -->[\s\S]*?<!-- FOOTER:END -->\n*/g;

	let cleaned = content.replace(headerPattern, "");
	cleaned = cleaned.replace(footerPattern, "");

	return cleaned.trim();
}

/**
 * Apply frames to a markdown file
 */
function applyFrames(markdownFile) {
	const filePath = join(rootDir, markdownFile);

	if (!existsSync(filePath)) {
		console.warn(`File not found: ${markdownFile}`);
		return false;
	}

	try {
		// Read current content
		let content = readFileSync(filePath, "utf-8");

		// Remove existing frames
		content = removeExistingFrames(content);

		// Calculate relative paths
		const headerPath = getRelativePath(markdownFile, HEADER_FILE);
		const footerPath = getRelativePath(markdownFile, FOOTER_FILE);

		// Create frame markers
		const header = `<!-- HEADER:START -->
![Header](${headerPath})
<!-- HEADER:END -->

`;

		const footer = `

<!-- FOOTER:START -->
![Footer](${footerPath})
<!-- FOOTER:END -->`;

		// Apply frames
		const framedContent = header + content + footer;

		// Write back
		writeFileSync(filePath, framedContent, "utf-8");

		console.log(`✓ Applied frames to: ${markdownFile}`);
		return true;
	} catch (error) {
		console.error(`✗ Error processing ${markdownFile}:`, error.message);
		return false;
	}
}

/**
 * Main execution
 */
function main() {
	console.log("🎨 Applying SVG frames to markdown documents...\n");

	// Verify frame files exist
	const headerPath = join(rootDir, HEADER_FILE);
	const footerPath = join(rootDir, FOOTER_FILE);

	if (!existsSync(headerPath)) {
		console.error(`❌ Header file not found: ${HEADER_FILE}`);
		process.exit(1);
	}

	if (!existsSync(footerPath)) {
		console.error(`❌ Footer file not found: ${FOOTER_FILE}`);
		process.exit(1);
	}

	console.log(`Using frames:`);
	console.log(`  Header: ${HEADER_FILE}`);
	console.log(`  Footer: ${FOOTER_FILE}\n`);

	// Find all markdown files
	const markdownFiles = findMarkdownFiles();

	console.log(`Found ${markdownFiles.length} markdown files\n`);

	if (markdownFiles.length === 0) {
		console.log("No markdown files found to process");
		return;
	}

	// Apply frames to each file
	let successCount = 0;
	let failCount = 0;

	for (const file of markdownFiles) {
		if (applyFrames(file)) {
			successCount++;
		} else {
			failCount++;
		}
	}

	// Summary
	console.log("\n📊 Summary:");
	console.log(`  ✓ Success: ${successCount}`);
	console.log(`  ✗ Failed: ${failCount}`);
	console.log(`  📁 Total: ${markdownFiles.length}`);

	if (failCount > 0) {
		process.exit(1);
	}
}

// Run the script
main();

#!/usr/bin/env node

/**
 * Apply Minimalistic Documentation Frames to Markdown Files
 *
 * Idempotently injects iframe references with hardcoded absolute GitHub URLs
 * for compatibility with GitHub markdown rendering.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

// GitHub repository information
const GITHUB_REPO = "Anselmoo/mcp-ai-agent-guidelines";
const GITHUB_BRANCH = "main";
const FRAMES_BASE_URL = `https://raw.githubusercontent.com/${GITHUB_REPO}/${GITHUB_BRANCH}/docs/.frames-interactive`;

// Injection markers
const HEADER_START = "<!-- AUTO-GENERATED INTERACTIVE HEADER - DO NOT EDIT -->";
const HEADER_END = "<!-- END AUTO-GENERATED INTERACTIVE HEADER -->";
const FOOTER_START = "<!-- AUTO-GENERATED INTERACTIVE FOOTER - DO NOT EDIT -->";
const FOOTER_END = "<!-- END AUTO-GENERATED INTERACTIVE FOOTER -->";

// File mappings: markdown file -> frame file base name
const FILE_MAPPINGS = {
	"README.md": "README",
	"CHANGELOG.md": "CHANGELOG",
	"CONTRIBUTING.md": "CONTRIBUTING",
	"DISCLAIMER.md": "DISCLAIMER",
	"docs/README.md": "docs-README",
	"docs/tips/README.md": "tips-README",
	"docs/about/README.md": "about-README",
	"docs/tools/README.md": "tools-README",
};

/**
 * Remove existing frames from content
 */
function removeExistingFrames(content) {
	// Remove header
	const headerRegex = new RegExp(
		`${HEADER_START}[\\s\\S]*?${HEADER_END}\\n*`,
		"g",
	);
	content = content.replace(headerRegex, "");

	// Remove footer
	const footerRegex = new RegExp(
		`${FOOTER_START}[\\s\\S]*?${FOOTER_END}\\n*`,
		"g",
	);
	content = content.replace(footerRegex, "");

	return content;
}

/**
 * Create iframe HTML with hardcoded absolute URL
 */
function createFrameHTML(frameFile, type) {
	const height = type === "header" ? "120px" : "80px";
	const frameUrl = `${FRAMES_BASE_URL}/${frameFile}`;

	return `${type === "header" ? HEADER_START : FOOTER_START}
<iframe
    src="${frameUrl}"
    style="width: 100%; height: ${height}; border: none; display: block; margin: 0; padding: 0;"
    title="${type === "header" ? "Interactive Header" : "Interactive Footer"}"
    loading="lazy"
    sandbox="allow-scripts allow-same-origin"
></iframe>
${type === "header" ? HEADER_END : FOOTER_END}

`;
}

/**
 * Apply frames to a single markdown file
 */
function applyFramesToFile(filePath, frameBaseName, dryRun = false) {
	const projectRoot = dirname(__dirname);
	const fullPath = join(projectRoot, filePath);

	try {
		// Read file
		let content = readFileSync(fullPath, "utf-8");
		const originalContent = content;

		// Remove existing frames
		content = removeExistingFrames(content);

		// Create header and footer HTML with absolute URLs
		const headerHTML = createFrameHTML(
			`header-${frameBaseName}.html`,
			"header",
		);
		const footerHTML = createFrameHTML(
			`footer-${frameBaseName}.html`,
			"footer",
		);

		// Inject frames
		const newContent = `${headerHTML}${content}\n${footerHTML}`;

		// Check if content changed
		if (newContent === originalContent) {
			console.log(`  ⊝ No changes needed: ${filePath}`);
			return false;
		}

		if (dryRun) {
			console.log(`  ⊕ Would update: ${filePath}`);
			console.log(
				`    - Header: ${FRAMES_BASE_URL}/header-${frameBaseName}.html`,
			);
			console.log(
				`    - Footer: ${FRAMES_BASE_URL}/footer-${frameBaseName}.html`,
			);
			return true;
		}

		// Write file
		writeFileSync(fullPath, newContent, "utf-8");
		console.log(`  ✓ Updated: ${filePath}`);
		console.log(
			`    - Header: ${FRAMES_BASE_URL}/header-${frameBaseName}.html`,
		);
		console.log(
			`    - Footer: ${FRAMES_BASE_URL}/footer-${frameBaseName}.html`,
		);
		return true;
	} catch (error) {
		console.error(`  ✗ Error processing ${filePath}: ${error.message}`);
		return false;
	}
}

/**
 * Main application function
 */
function applyFrames() {
	// Check for dry-run flag
	const dryRun = process.argv.includes("--dry-run");

	console.log("🎨 Applying Minimalistic Documentation Frames...\n");
	console.log(`🔗 Base URL: ${FRAMES_BASE_URL}\n`);

	if (dryRun) {
		console.log("🔍 DRY RUN MODE - No files will be modified\n");
	}

	let filesProcessed = 0;
	let filesUpdated = 0;

	// Process each file
	for (const [filePath, frameBaseName] of Object.entries(FILE_MAPPINGS)) {
		filesProcessed++;
		const updated = applyFramesToFile(filePath, frameBaseName, dryRun);
		if (updated) {
			filesUpdated++;
		}
	}

	console.log(`\n📊 Summary:`);
	console.log(`  Files processed: ${filesProcessed}`);
	console.log(
		`  Files ${dryRun ? "to be updated" : "updated"}: ${filesUpdated}`,
	);

	if (dryRun) {
		console.log(
			"\n💡 Run without --dry-run flag to apply changes:\n   npm run frames:apply-interactive",
		);
	} else {
		console.log("\n✅ Minimalistic frames applied successfully!");
		console.log(`🔗 Frames are hosted at: ${FRAMES_BASE_URL}`);
	}
}

// Run application
applyFrames();

#!/usr/bin/env node
import { readFileSync } from "node:fs";
import path from "node:path";

// Use parseLCOV/getFileSnippet helpers from coverage-patch.mjs to compute per-file branch diagnostics
import { getFileSnippet, parseLCOV } from "./coverage-patch.mjs";

const argv = process.argv.slice(2);
const opts = { lcov: "coverage/lcov.info", threshold: 90, top: 10 };
for (let i = 0; i < argv.length; i++) {
	const a = argv[i];
	if (a === "--lcov") opts.lcov = argv[++i];
	else if (a === "--threshold") opts.threshold = Number(argv[++i]);
	else if (a === "--top") opts.top = Number(argv[++i]);
}

try {
	const txt = readFileSync(opts.lcov, "utf8");
	const lcov = parseLCOV(txt);
	let totalBranches = 0;
	let coveredBranches = 0;
	const perFile = [];
	for (const [file, data] of Object.entries(lcov)) {
		let fileTotal = 0;
		let fileCovered = 0;
		const missingLines = [];
		for (const [lnStr, brs] of Object.entries(data.branches || {})) {
			const ln = Number(lnStr);
			for (const t of brs) {
				fileTotal++;
				if (t !== null && t !== 0) fileCovered++;
			}
			if (brs.some((t) => t === null || t === 0))
				missingLines.push({ line: ln, branches: brs });
		}
		if (fileTotal > 0) {
			totalBranches += fileTotal;
			coveredBranches += fileCovered;
			perFile.push({
				file,
				total: fileTotal,
				covered: fileCovered,
				missingLines,
			});
		}
	}

	const globalPct =
		totalBranches === 0
			? 100
			: Math.round((coveredBranches / totalBranches) * 100);
	console.log(
		`Branch coverage: ${globalPct}% (${coveredBranches}/${totalBranches} branches)`,
	);

	if (globalPct < opts.threshold) {
		console.error(
			`Branch coverage ${globalPct}% < threshold ${opts.threshold}%.`,
		);
	}

	// Show top files with most missing branches
	perFile.sort((a, b) => b.missingLines.length - a.missingLines.length);
	const top = perFile.slice(0, opts.top);
	if (top.length) {
		console.log(
			`\nTop ${Math.min(opts.top, top.length)} files with missing branches:`,
		);
		for (const f of top) {
			console.log(
				`\n${f.file} — ${f.missingLines.length} lines with missing branches (${f.covered}/${f.total} branches covered)`,
			);
			for (const ml of f.missingLines.slice(0, 5)) {
				const snippet = getFileSnippet(
					path.resolve(ml.file || f.file),
					ml.line,
					2,
				);
				console.log(`  Line ${ml.line}: branches=${JSON.stringify(ml.branches)}
${snippet ? snippet.split("\n")[0] : "(no snippet)"}\n`);
			}
		}
	}

	if (globalPct < opts.threshold) process.exit(2);
	process.exit(0);
} catch (err) {
	console.error("Failed to read lcov file:", err.message);
	process.exit(3);
}

#!/usr/bin/env node
const fs = require("fs");
const path = require("path");

function usage() {
	console.log("Usage: node scripts/check-coverage.cjs [--threshold=NUM]");
	console.log(
		"Reads coverage/lcov.info and fails if any file is below the threshold (percentage).",
	);
}

const argv = process.argv.slice(2);
let threshold = 90;
for (const a of argv) {
	if (a.startsWith("--threshold=")) threshold = parseFloat(a.split("=")[1]);
	if (a === "--help" || a === "-h") {
		usage();
		process.exit(0);
	}
}
if (Number.isNaN(threshold)) {
	console.error("Invalid threshold");
	process.exit(2);
}

const lcovPath = path.resolve(process.cwd(), "coverage", "lcov.info");
if (!fs.existsSync(lcovPath)) {
	console.error(
		"coverage/lcov.info not found. Run coverage first (npm run test:coverage:vitest).",
	);
	process.exit(2);
}

const content = fs.readFileSync(lcovPath, "utf8");
const lines = content.split("\n");

const results = [];
let currentFile = null;
let lf = null;
let lh = null;

for (const line of lines) {
	if (line.startsWith("SF:")) {
		if (currentFile) {
			results.push({ file: currentFile, lf, lh });
		}
		currentFile = line.slice(3).trim();
		lf = null;
		lh = null;
	} else if (line.startsWith("LF:")) {
		lf = parseInt(line.slice(3).trim(), 10);
	} else if (line.startsWith("LH:")) {
		lh = parseInt(line.slice(3).trim(), 10);
	}
}
if (currentFile) results.push({ file: currentFile, lf, lh });

const failing = [];
for (const r of results) {
	const { file } = r;
	if (r.lf == null || r.lh == null) {
		failing.push({ file, pct: "NA", lf: r.lf, lh: r.lh });
		continue;
	}
	const pct = (r.lh / r.lf) * 100;
	if (pct < threshold)
		failing.push({ file, pct: pct.toFixed(2), lf: r.lf, lh: r.lh });
}

if (failing.length === 0) {
	console.log(`All files meet the coverage threshold of ${threshold}%`);
	process.exit(0);
}

console.log(`Files below coverage threshold (${threshold}%):`);
for (const f of failing) {
	console.log(`${f.file} — ${f.pct}% (LH:${f.lh || "NA"}/LF:${f.lf || "NA"})`);
}
process.exit(1);

