#!/usr/bin/env node
import { execSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

function parseLCOV(lcovText) {
	const lines = lcovText.split(/\r?\n/);
	const files = {};
	let current = null;
	for (const line of lines) {
		if (!line) continue;
		if (line.startsWith("SF:")) {
			current = line.slice(3);
			files[current] = files[current] || { lines: {}, branches: {} };
			continue;
		}
		if (!current) continue;
		if (line.startsWith("DA:")) {
			const [, rest] = line.split("DA:");
			const [numStr, countStr] = rest.split(",");
			const num = Number(numStr);
			const count = Number(countStr);
			files[current].lines[num] = (files[current].lines[num] || 0) + count;
		} else if (line.startsWith("BRDA:")) {
			const [, rest] = line.split("BRDA:");
			const [numStr, _block, _branch, takenStr] = rest.split(",");
			const num = Number(numStr);
			const taken = takenStr === "-" ? null : Number(takenStr);
			files[current].branches[num] = files[current].branches[num] || [];
			files[current].branches[num].push(taken);
		}
	}
	return files;
}

function parseGitDiffRanges(baseRef, headRef, repoPath = ".") {
	// returns map file -> set of changed line numbers (new file line numbers)
	const cmd = `git -C "${repoPath}" fetch --no-tags origin ${baseRef} --quiet || true && git -C "${repoPath}" diff --unified=0 origin/${baseRef}...${headRef}`;
	const raw = execSync(cmd, {
		encoding: "utf8",
		stdio: ["pipe", "pipe", "ignore"],
	});
	const files = {};
	const lines = raw.split(/\r?\n/);
	let currentFile = null;
	for (const l of lines) {
		if (l.startsWith("+++ b/")) {
			currentFile = l.slice(6);
			files[currentFile] = files[currentFile] || new Set();
		}
		if (!currentFile) continue;
		if (l.startsWith("@@")) {
			// @@ -a,b +c,d @@
			const m = /@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/.exec(l);
			if (m) {
				const start = Number(m[1]);
				const len = m[2] ? Number(m[2]) : 1;
				for (let i = start; i < start + len; i++) files[currentFile].add(i);
			}
		}
	}
	return files;
}

function classifyLine(fileCoverage, lineNum) {
	const da = fileCoverage.lines?.[lineNum] || 0;
	const brs = fileCoverage.branches?.[lineNum];
	if (!brs) {
		return da > 0 ? { kind: "hit" } : { kind: "miss" };
	}
	// branch entries exist
	let anyZero = false;
	let anyNonZero = false;
	for (const t of brs) {
		if (t === null || t === 0) anyZero = true;
		else anyNonZero = true;
	}
	if (anyZero && anyNonZero) return { kind: "partial" };
	if (anyNonZero && !anyZero) return { kind: "hit" };
	return { kind: "miss" };
}

function getFileSnippet(filePath, lineNum, ctx = 2) {
	try {
		const txt = readFileSync(filePath, "utf8");
		const lines = txt.split(/\r?\n/);
		const start = Math.max(0, lineNum - 1 - ctx);
		const end = Math.min(lines.length, lineNum - 1 + ctx + 1);
		const snippet = lines
			.slice(start, end)
			.map((l, i) => `${start + i + 1}: ${l}`);
		return snippet.join("\n");
	} catch (err) {
		return null;
	}
}

function computePatchReportFromStrings(
	lcovText,
	diffRanges,
	repoPath = process.cwd(),
) {
	const lcov = parseLCOV(lcovText);
	const report = { files: {} };
	for (const [file, setLines] of Object.entries(diffRanges)) {
		const covFileKey =
			Object.keys(lcov).find((k) => k.endsWith(file) || k === file) || file;
		const cov = lcov[covFileKey] || { lines: {}, branches: {} };
		const details = [];
		let hits = 0,
			partials = 0,
			misses = 0,
			total = 0;
		for (const ln of setLines instanceof Set ? [...setLines] : setLines) {
			total++;
			const cls = classifyLine(cov, ln);
			if (cls.kind === "hit") hits++;
			else if (cls.kind === "partial") partials++;
			else misses++;

			// collect branch information for the line if present
			const branchInfo = cov.branches?.[ln] ? [...cov.branches[ln]] : undefined;
			const execCount = cov.lines?.[ln] ?? 0;

			// source snippet to help locate the symbol
			const absPath = path.resolve(repoPath, file);
			const snippet = getFileSnippet(absPath, ln, 2);

			// suggestion text — include details for branch entries when present
			let suggestion = null;
			let uncoveredBranches;
			if (branchInfo) {
				uncoveredBranches = [];
				branchInfo.forEach((t, idx) => {
					if (t === null || t === 0) uncoveredBranches.push(idx);
				});
				if (uncoveredBranches.length) {
					suggestion = `Branches present but not all taken (${uncoveredBranches.length} uncovered). Add tests to exercise alternate branch paths (branch indexes: ${uncoveredBranches.join(", ")}).`;
				}
			}
			if (!suggestion) {
				if (cls.kind === "partial") {
					suggestion =
						"Partial coverage detected. Add tests to exercise both branches around this line (e.g., success and failure paths). Inspect nearby conditional expressions or ternary operators.";
				} else if (cls.kind === "miss") {
					suggestion =
						"Line not covered: add a focused unit test to execute this code path.";
				}
			}

			details.push({
				line: ln,
				kind: cls.kind,
				execCount,
				branches: branchInfo,
				uncoveredBranches,
				snippet,
				suggestion,
			});
		}
		report.files[file] = { total, hits, partials, misses, details };
	}
	return report;
}

function printSummary(report) {
	const perFile = Object.entries(report.files).map(
		([f, r]) =>
			`${f}: changed ${r.total} lines → ${r.hits} hits, ${r.partials} partials, ${r.misses} misses`,
	);
	console.log("\n=== Coverage Patch Summary ===\n");
	for (const line of perFile) console.log(line);

	console.log("\nTop non-hit details (per file):");
	for (const [f, r] of Object.entries(report.files)) {
		const bad = r.details.filter((d) => d.kind !== "hit");
		if (!bad.length) continue;
		console.log(`\n${f} — ${bad.length} non-hit lines (showing up to 5):`);
		for (const d of bad.slice(0, 5)) {
			console.log(`  ${f}:${d.line} → ${d.kind} — ${d.suggestion}`);
			if (d.snippet) {
				console.log(d.snippet.split("\n")[0] + "\n");
			}
		}
	}

	console.log("\nDetailed (all non-hits):");
	for (const [f, r] of Object.entries(report.files)) {
		for (const d of r.details) {
			if (d.kind !== "hit")
				console.log(`  ${f}:${d.line} → ${d.kind} — ${d.suggestion}`);
		}
	}
}

import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);

// CLI - only run when executed directly, not when imported for tests
if (process.argv[1] === __filename) {
	const argv = process.argv.slice(2);
	const opts = {};
	for (let i = 0; i < argv.length; i++) {
		const a = argv[i];
		if (a === "--lcov") opts.lcov = argv[++i];
		else if (a === "--base") opts.base = argv[++i];
		else if (a === "--head") opts.head = argv[++i];
		else if (a === "--output") opts.output = argv[++i];
		else if (a === "--threshold") opts.threshold = Number(argv[++i]);
	}
	opts.lcov = opts.lcov || "coverage/lcov.info";
	opts.base = opts.base || "main";
	opts.head = opts.head || "HEAD";
	opts.output = opts.output || "artifacts/coverage-patch.json";
	opts.threshold = typeof opts.threshold === "number" ? opts.threshold : null;

	if (!existsSync(opts.lcov)) {
		console.error(`LCOV file not found: ${opts.lcov}`);
		process.exit(2);
	}

	const lcovText = readFileSync(opts.lcov, "utf8");
	const diffRanges = parseGitDiffRanges(opts.base, opts.head, process.cwd());

	// Filter out non-code files (markdown demos, docs, ADRs, tests, node_modules) so they don't skew patch coverage
	function isIgnoredPath(p) {
		return (
			p.endsWith(".md") ||
			p.startsWith("demos/") ||
			p.startsWith("docs/") ||
			p.includes("/docs/") ||
			p.includes("/demos/") ||
			p.startsWith("tests/") ||
			p.includes("/tests/") ||
			p.endsWith(".spec.ts") ||
			p.endsWith(".test.ts") ||
			p.endsWith(".spec.js") ||
			p.endsWith(".test.js") ||
			p.includes("node_modules")
		);
	}
	const filteredDiffRanges = {};
	for (const [f, s] of Object.entries(diffRanges)) {
		if (!isIgnoredPath(f)) filteredDiffRanges[f] = s;
	}

	const report = computePatchReportFromStrings(lcovText, filteredDiffRanges);

	// ensure artifact dir
	const outDir = path.dirname(opts.output);
	if (!existsSync(outDir)) mkdirSync(outDir, { recursive: true });
	writeFileSync(opts.output, JSON.stringify(report, null, 2));
	printSummary(report);

	// optional threshold check
	if (opts.threshold !== null) {
		// compute weighted patch coverage: hits/(hits+partials+misses) but partial counts as half (optional). We'll follow Codecov: hits / (hits+partials+misses)
		let _totalChanged = 0,
			totalHits = 0,
			totalPartials = 0,
			totalMisses = 0;
		for (const r of Object.values(report.files)) {
			_totalChanged += r.total;
			totalHits += r.hits;
			totalPartials += r.partials;
			totalMisses += r.misses;
		}
		const denom = totalHits + totalPartials + totalMisses;
		const ratio = denom === 0 ? 1 : totalHits / denom;
		const pct = Math.round(ratio * 100);
		console.log(
			`\nPatch coverage: ${pct}% (${totalHits} hits / ${denom} lines)`,
		);
		if (pct < opts.threshold) {
			console.error(`Patch coverage ${pct}% < threshold ${opts.threshold}%`);
			process.exit(3);
		}
	}
}

// Exports for unit testing
export {
	parseLCOV,
	computePatchReportFromStrings,
	classifyLine,
	parseGitDiffRanges,
	getFileSnippet,
};

import fs from "fs";
import path from "path";

function findCoverageJson() {
	const cwd = process.cwd();
	const candidates = [
		"coverage/coverage-final.json",
		"coverage/coverage-summary.json",
		"coverage/v8-to-istanbul/coverage-final.json",
		"coverage/lcov-report/coverage-summary.json",
	];
	for (const rel of candidates) {
		const p = path.join(cwd, rel);
		if (fs.existsSync(p)) return p;
	}
	return null;
}

function parseAndWrite(found) {
	const raw = fs.readFileSync(found, "utf8");
	let data;
	try {
		data = JSON.parse(raw);
	} catch (err) {
		console.error("Failed to parse coverage JSON:", err.message);
		process.exitCode = 2;
		return;
	}

	const entries = [];

	// coverage-final.json format: file -> { statements: { pct }, lines: { pct }, functions: { pct }, branches: { pct } }
	// coverage-summary.json format: similar but usually { "file": { statements: { pct: x }, ... }, "total": {...} }

	if (
		"total" in data ||
		Object.values(data).some(
			(v) => v?.statements && typeof v.statements.pct === "number",
		)
	) {
		for (const [file, obj] of Object.entries(data)) {
			if (file === "total") continue;
			const s = obj?.statements?.pct ?? obj?.lines?.pct ?? 0;
			const l = obj?.lines?.pct ?? 0;
			const f = obj?.functions?.pct ?? 0;
			const b = obj?.branches?.pct ?? 0;
			entries.push({
				file,
				stat: s || 0,
				lines: l || 0,
				funcs: f || 0,
				branches: b || 0,
			});
		}
	} else {
		// Fallback: if structure is different, try to iterate top-level keys
		for (const [file, obj] of Object.entries(data)) {
			if (file === "total") continue;
			const s =
				typeof obj?.statements?.pct === "number" ? obj.statements.pct : 0;
			const l = typeof obj?.lines?.pct === "number" ? obj.lines.pct : 0;
			const f = typeof obj?.functions?.pct === "number" ? obj.functions.pct : 0;
			const b = typeof obj?.branches?.pct === "number" ? obj.branches.pct : 0;
			entries.push({ file, stat: s, lines: l, funcs: f, branches: b });
		}
	}

	entries.sort((a, b) => a.stat - b.stat);

	const outLines = entries
		.slice(0, 50)
		.map(
			(e) =>
				`${e.stat.toFixed(1)}%\t${e.lines.toFixed(1)}%\t${e.funcs.toFixed(1)}%\t${e.branches.toFixed(1)}%\t${e.file}`,
		);

	const outDir = path.join(process.cwd(), "coverage");
	if (!fs.existsSync(outDir)) fs.mkdirSync(outDir, { recursive: true });
	const outPath = path.join(outDir, "low-coverage.txt");
	fs.writeFileSync(outPath, outLines.join("\n"));
	console.log(`Wrote low-coverage summary to ${outPath}`);
}

const found = findCoverageJson();
if (!found) {
	console.error(
		"No coverage JSON found. Ensure vitest wrote coverage into the coverage/ directory.",
	);
	process.exitCode = 1;
} else {
	parseAndWrite(found);
}

#!/usr/bin/env node

/**
 * Create All Issues in Correct Order
 *
 * Creates parent and sub-issues in the correct sequence.
 * Files should already have correct issue numbers populated.
 *
 * Usage:
 *   node scripts/create-all-issues.js [--dry-run] [--parents-only] [--subs-only]
 */

import { execFileSync, execSync } from "node:child_process";
import { promises as fs, unlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ISSUES_DRAFT_DIR = "plan-v0.13.x/issues-draft";
const REPO = "Anselmoo/mcp-ai-agent-guidelines";
const MAPPING_FILE = "artifacts/issue-number-mapping.json";

// Parent issue files in order
const PARENT_FILES = [
	"001-parent-phase1-discoverability.md",
	"002-parent-phase2-domain-extraction.md",
	"003-parent-phase3-broken-tools.md",
	"004-parent-phase4-speckit-integration.md",
];

// Parse command line arguments
const args = process.argv.slice(2);
const dryRun = args.includes("--dry-run");
const parentsOnly = args.includes("--parents-only");
const subsOnly = args.includes("--subs-only");

/**
 * Extract metadata from markdown
 */
function extractMetadata(content) {
	const metadata = {};

	const titleMatch = content.match(/^# (.+)$/m);
	if (titleMatch) {
		metadata.title = titleMatch[1];
	}

	const labelsMatch = content.match(/> \*\*Labels\*\*:\s*(.+)/);
	if (labelsMatch) {
		metadata.labels = labelsMatch[1]
			.split(",")
			.map((l) => l.trim().replace(/`/g, ""));
	}

	const milestoneMatch = content.match(/> \*\*Milestone\*\*:\s*(.+)/);
	if (milestoneMatch) {
		metadata.milestone = milestoneMatch[1].trim();
	}

	return metadata;
}

/**
 * Find matching milestone
 */
function findMatchingMilestone(milestoneTitle) {
	try {
		const output = execSync(
			`gh api 'repos/${REPO}/milestones' | jq -r '.[].title'`,
			{ encoding: "utf-8", shell: "/bin/bash" },
		);
		const milestones = output.trim().split("\n");

		if (milestones.includes(milestoneTitle)) {
			return milestoneTitle;
		}

		const prefixMatch = milestones.find((m) => m.startsWith(milestoneTitle));
		return prefixMatch || null;
	} catch {
		return null;
	}
}

/**
 * Create GitHub issue
 */
function createGitHubIssue(issueData, expectedNumber, dryRun = false) {
	const { title, body, labels, milestone } = issueData;

	if (dryRun) {
		console.log(`\n📄 [DRY RUN] Would create issue #${expectedNumber}:`);
		console.log(`   Title: ${title}`);
		console.log(`   Labels: ${labels.join(", ")}`);
		console.log(`   Milestone: ${milestone || "None"}`);
		return expectedNumber;
	}

	const bodyFile = `/tmp/gh-issue-${Date.now()}.md`;
	writeFileSync(bodyFile, body);

	try {
		const args = [
			"issue",
			"create",
			"--repo",
			REPO,
			"--title",
			title,
			"--body-file",
			bodyFile,
		];

		for (const label of labels) {
			args.push("--label", label);
		}

		if (milestone) {
			const shortMilestone = milestone.split("(")[0].trim();
			const matched = findMatchingMilestone(shortMilestone);
			if (matched) {
				args.push("--milestone", matched);
			}
		}

		const output = execFileSync("gh", args, { encoding: "utf-8" });
		const issueUrl = output.trim();
		const actualNumber = Number.parseInt(issueUrl.split("/").pop(), 10);

		unlinkSync(bodyFile);

		if (actualNumber !== expectedNumber) {
			console.error(
				`⚠️  WARNING: Expected #${expectedNumber} but got #${actualNumber}`,
			);
			console.error(`   This may indicate concurrent issue creation!`);
		} else {
			console.log(`✅ Created #${actualNumber}: ${title}`);
		}

		return actualNumber;
	} catch (error) {
		try {
			unlinkSync(bodyFile);
		} catch {
			// Ignore
		}
		console.error(`❌ Failed to create issue: ${title}`);
		console.error(error.message);
		return null;
	}
}

/**
 * Process issue file
 */
async function processIssueFile(filename, expectedNumber) {
	const filePath = join(ISSUES_DRAFT_DIR, filename);
	const content = await fs.readFile(filePath, "utf-8");
	const metadata = extractMetadata(content);

	if (!metadata.title) {
		console.warn(`⚠️  Skipping ${filename}: No title found`);
		return null;
	}

	return {
		file: filename,
		expectedNumber,
		title: metadata.title,
		body: content,
		labels: metadata.labels || [],
		milestone: metadata.milestone,
	};
}

async function main() {
	console.log("🚀 Creating All GitHub Issues\n");

	if (dryRun) {
		console.log("📋 DRY RUN MODE\n");
	}

	// Load mapping
	let mapping;
	try {
		const content = await fs.readFile(MAPPING_FILE, "utf-8");
		mapping = JSON.parse(content);
		console.log(`📋 Using pre-calculated numbers from ${MAPPING_FILE}\n`);
	} catch {
		console.error("❌ Mapping file not found!");
		console.error("   Run: node scripts/pre-calculate-issue-numbers.js");
		process.exit(1);
	}

	const created = [];

	// Create parent issues first (unless --subs-only)
	if (!subsOnly) {
		console.log("📋 Creating Parent Issues:\n");
		for (const filename of PARENT_FILES) {
			const expectedNumber = mapping.parents[filename];
			const issue = await processIssueFile(filename, expectedNumber);

			if (issue) {
				const actualNumber = createGitHubIssue(issue, expectedNumber, dryRun);
				if (actualNumber) {
					created.push({ ...issue, actualNumber });
				}

				// Rate limit
				if (!dryRun) {
					await new Promise((resolve) => setTimeout(resolve, 1000));
				}
			}
		}
	}

	// Create sub-issues (unless --parents-only)
	if (!parentsOnly) {
		console.log("\n📋 Creating Sub-Issues:\n");
		const subFiles = Object.keys(mapping.subIssues).sort();

		for (const filename of subFiles) {
			const expectedNumber = mapping.subIssues[filename];
			const issue = await processIssueFile(filename, expectedNumber);

			if (issue) {
				const actualNumber = createGitHubIssue(issue, expectedNumber, dryRun);
				if (actualNumber) {
					created.push({ ...issue, actualNumber });
				}

				// Rate limit
				if (!dryRun) {
					await new Promise((resolve) => setTimeout(resolve, 1000));
				}
			}
		}
	}

	console.log(
		`\n✨ Done! ${dryRun ? "Would create" : "Created"} ${created.length} issues`,
	);

	if (!dryRun && created.length > 0) {
		// Verify all got expected numbers
		const mismatches = created.filter(
			(c) => c.actualNumber !== c.expectedNumber,
		);
		if (mismatches.length > 0) {
			console.warn(`\n⚠️  ${mismatches.length} issues got unexpected numbers!`);
			console.warn("   This may require manual fixing of references.");
		} else {
			console.log("\n✅ All issues got expected numbers!");
			console.log("   All #references should work correctly.");
		}
	}
}

main().catch(console.error);

#!/usr/bin/env node

/**
 * Automated GitHub Issue Creation from Markdown Drafts
 *
 * Reads issue draft files with metadata headers and creates GitHub issues
 * using the GitHub CLI (gh).
 *
 * Usage:
 *   node scripts/create-github-issues.js [options]
 *
 * Options:
 *   --dry-run            Preview issues without creating them
 *   --phase <number>     Only create issues for specific phase (0-4)
 *   --parallel           Only create parallel issues (can run concurrently)
 *   --serial             Only create serial issues (must run sequentially)
 *   --skip-parents       Skip parent issues (only create sub-tasks)
 *   --create-milestones  Create GitHub milestones from milestones.md
 *   --milestone <id>     Only create specific milestone (requires --create-milestones)
 *   --link-sub-issues    Link sub-issues to parent epics (requires existing issues)
 *   --update-parents     Update parent issue bodies to replace #TBD with issue numbers
 *   --export-mapping     Export task-ID-to-issue-number mapping to unique JSON file
 *   --mapping <file>     Use specific mapping file for --update-parents
 */

import { execFileSync, execSync } from "node:child_process";
import { promises as fs, unlinkSync, writeFileSync } from "node:fs";
import { basename, join } from "node:path";

const ISSUES_DRAFT_DIR = "plan-v0.13.x/issues-draft";
const MILESTONES_FILE = "plan-v0.13.x/issues-draft/milestones.md";
const REPO = "Anselmoo/mcp-ai-agent-guidelines";

// Label definitions with colors (for auto-creation)
const LABEL_DEFINITIONS = {
	"phase-1": {
		color: "1d76db",
		description: "Phase 1: LLM Tool Discoverability",
	},
	"phase-2": {
		color: "0e8a16",
		description: "Phase 2: Domain Layer Extraction",
	},
	"phase-3": { color: "d93f0b", description: "Phase 3: Broken Tools Fix" },
	"phase-4": { color: "5319e7", description: "Phase 4: Spec-Kit Integration" },
	"phase-4a": {
		color: "6f42c1",
		description: "Phase 4a: Constitution & Generation",
	},
	"phase-4b": {
		color: "7c3aed",
		description: "Phase 4b: Validation & Progress",
	},
	"priority-critical": { color: "b60205", description: "Critical priority" },
	"priority-high": { color: "d93f0b", description: "High priority" },
	"priority-medium": { color: "fbca04", description: "Medium priority" },
	"priority-low": { color: "0e8a16", description: "Low priority" },
	"copilot-suitable": {
		color: "84b6eb",
		description: "Suitable for GitHub Copilot Coding Agent",
	},
	"mcp-serena": {
		color: "c5def5",
		description: "Recommend MCP Serena for semantic code operations",
	},
	"human-required": {
		color: "e99695",
		description: "Requires human decision or review",
	},
	serial: { color: "fef2c0", description: "Must be executed sequentially" },
	parallel: { color: "c2e0c6", description: "Can be executed in parallel" },
	epic: { color: "3e4b9e", description: "Epic/Parent issue" },
};

// Cache for existing labels
let existingLabelsCache = null;

// Cache for existing milestones
let existingMilestonesCache = null;

/**
 * Get existing labels from repo (cached)
 */
function getExistingLabels() {
	if (existingLabelsCache !== null) {
		return existingLabelsCache;
	}

	try {
		const output = execSync(
			`gh label list --repo ${REPO} --json name --limit 200`,
			{
				encoding: "utf-8",
			},
		);
		const labels = JSON.parse(output);
		existingLabelsCache = new Set(labels.map((l) => l.name));
		return existingLabelsCache;
	} catch {
		existingLabelsCache = new Set();
		return existingLabelsCache;
	}
}

/**
 * Get existing milestones from repo (cached)
 */
function getExistingMilestones() {
	if (existingMilestonesCache !== null) {
		return existingMilestonesCache;
	}

	try {
		const output = execSync(
			`gh api repos/${REPO}/milestones --jq '.[].title'`,
			{
				encoding: "utf-8",
			},
		);
		existingMilestonesCache = output.trim().split("\n").filter(Boolean);
		return existingMilestonesCache;
	} catch {
		existingMilestonesCache = [];
		return existingMilestonesCache;
	}
}

/**
 * Find matching milestone by prefix (e.g., "M2: Discoverability" matches "M2: Discoverability (End Week 4)")
 */
function findMatchingMilestone(milestoneName) {
	const milestones = getExistingMilestones();

	// Try exact match first
	if (milestones.includes(milestoneName)) {
		return milestoneName;
	}

	// Try prefix match (milestone name starts with the short version)
	const match = milestones.find((m) => m.startsWith(milestoneName));
	if (match) {
		return match;
	}

	// Try matching by milestone ID (e.g., "M2:")
	const idMatch = milestoneName.match(/^(M\d+):/);
	if (idMatch) {
		const idPrefix = idMatch[1] + ":";
		const idMatched = milestones.find((m) => m.startsWith(idPrefix));
		if (idMatched) {
			return idMatched;
		}
	}

	return null;
}

/**
 * Create a label if it doesn't exist
 */
function ensureLabel(labelName) {
	const existing = getExistingLabels();
	if (existing.has(labelName)) {
		return true;
	}

	const definition = LABEL_DEFINITIONS[labelName];
	if (!definition) {
		console.warn(
			`⚠️  Unknown label: ${labelName} (will attempt to create with default color)`,
		);
	}

	const color = definition?.color || "ededed";
	const description = definition?.description || "";

	try {
		execFileSync(
			"gh",
			[
				"label",
				"create",
				labelName,
				"--repo",
				REPO,
				"--color",
				color,
				"--description",
				description,
				"--force",
			],
			{ encoding: "utf-8" },
		);
		console.log(`🏷️  Created label: ${labelName}`);
		existingLabelsCache.add(labelName);
		return true;
	} catch {
		console.error(`❌ Failed to create label: ${labelName}`);
		return false;
	}
}

// Parse command line arguments
