	mappingFile: args.find((a) => a.startsWith("--mapping="))?.split("=")[1],
};

/**
 * Parse milestones from milestones.md
 */
function parseMilestones(content) {
	const milestones = [];
	const milestoneBlocks = content.split(/^### M\d+:/gm).slice(1);

	for (const block of milestoneBlocks) {
		const yamlMatch = block.match(/```yaml\n([\s\S]+?)\n```/);
		if (!yamlMatch) continue;

		const yamlContent = yamlMatch[1];
		const milestone = {};

		// Parse YAML manually (simple key: value format)
		const lines = yamlContent.split("\n");
		let currentKey = null;
		let currentValue = [];

		for (const line of lines) {
			if (line.match(/^[a-z_]+:/)) {
				// Save previous key if exists
				if (currentKey) {
					milestone[currentKey] = currentValue.join("\n").trim();
				}

				// Start new key
				const [key, ...valueParts] = line.split(":");
				currentKey = key.trim();
				currentValue = [valueParts.join(":").trim()];
			} else if (currentKey && line.trim()) {
				// Continue multi-line value
				currentValue.push(line.trim());
			}
		}

		// Save last key
		if (currentKey) {
			milestone[currentKey] = currentValue.join("\n").trim();
		}

		// Remove pipe character from description
		if (milestone.description) {
			milestone.description = milestone.description.replace(/^\|/gm, "").trim();
		}

		if (milestone.id && milestone.title) {
			milestones.push(milestone);
		}
	}

	return milestones;
}

/**
 * Create GitHub milestone using gh CLI
 */
function createGitHubMilestone(milestoneData, dryRun = false) {
	const { id, title, description, due_on, state } = milestoneData;

	// Clean title - remove surrounding quotes if present
	const cleanTitle = title.replace(/^"|"$/g, "");
	// Clean due_on - remove surrounding quotes if present
	const cleanDueOn = due_on.replace(/^"|"$/g, "");

	if (dryRun) {
		console.log(`\n📅 [DRY RUN] Would create milestone:`);
		console.log(`   ID: ${id}`);
		console.log(`   Title: ${cleanTitle}`);
		console.log(`   Due: ${cleanDueOn}`);
		console.log(`   State: ${state}`);
		return null;
	}

	try {
		// Use JSON input via stdin to avoid shell escaping issues
		const payload = JSON.stringify({
			title: cleanTitle,
			description: description || "",
			due_on: cleanDueOn,
			state: state || "open",
		});

		const output = execSync(
			`gh api repos/${REPO}/milestones --method POST --input -`,
			{
				encoding: "utf-8",
				input: payload,
			},
		);
		const result = JSON.parse(output);

		console.log(`✅ Created milestone: ${cleanTitle}`);
		console.log(`   Number: ${result.number}`);
		console.log(`   URL: ${result.html_url}`);

		return result;
	} catch (error) {
		// Check if milestone already exists
		if (error.message.includes("already_exists")) {
			console.log(`⚠️  Milestone already exists: ${cleanTitle}`);
			return null;
		}

		console.error(`❌ Failed to create milestone: ${cleanTitle}`);
		console.error(error.message);
		return null;
	}
}

/**
 * Extract metadata from issue markdown header
 * Parses format like:
 *   # 🔧 P4-001: Title [serial]
 *   > **Labels**: `phase-4a`, `priority-high`, `serial`, `copilot-suitable`
 *   > **Milestone**: M5: Spec-Kit Core
 *   > **Estimate**: 2 hours
 *   > **Depends On**: None
 *   > **Blocks**: P4-002, P4-003
 */
function extractMetadata(content) {
	const metadata = {};

	// Extract title and execution mode
	const titleMatch = content.match(/^# (.+)$/m);
	if (titleMatch) {
		const fullTitle = titleMatch[1];

		// Extract task ID first
		const taskIdMatch = fullTitle.match(/(P\d+-\d+):/);
		if (taskIdMatch) {
			metadata.taskId = taskIdMatch[1];
		}

		// Extract mode from brackets
		if (fullTitle.includes("[serial]")) {
			metadata.mode = "serial";
		} else if (fullTitle.includes("[parallel]")) {
			metadata.mode = "parallel";
		}

		// Keep full title as-is
		metadata.title = fullTitle;
	}

	// Extract labels (format: `label1`, `label2`, ...)
	const labelsMatch = content.match(/> \*\*Labels\*\*:\s*`(.+)`/);
	if (labelsMatch) {
		metadata.labels = labelsMatch[1]
			.split(/`,\s*`/)
			.map((l) => l.replace(/`/g, "").trim());
	}

	// Extract milestone
	const milestoneMatch = content.match(/> \*\*Milestone\*\*:\s*(.+)$/m);
	if (milestoneMatch) {
		metadata.milestone = milestoneMatch[1].trim();
	}

	// Extract estimate
	const estimateMatch = content.match(/> \*\*Estimate\*\*:\s*(.+)$/m);
	if (estimateMatch) {
		metadata.estimate = estimateMatch[1].trim();
	}

	// Extract dependencies
	const dependsMatch = content.match(
		/> \*\*(?:Depends On|Blocked by)\*\*:\s*(.+)$/m,
	);
	if (dependsMatch) {
		const deps = dependsMatch[1].trim();
		if (deps !== "None") {
			metadata.dependsOn = deps.split(",").map((d) => d.trim());
		}
	}

	// Extract blocks
	const blocksMatch = content.match(/> \*\*Blocks\*\*:\s*(.+)$/m);
	if (blocksMatch) {
		const blocks = blocksMatch[1].trim();
		if (blocks !== "None") {
			metadata.blocks = blocks.split(",").map((b) => b.trim());
		}
	}

	// Extract parent
	const parentMatch = content.match(/> \*\*Parent\*\*:\s*\[(.+?)\]/);
	if (parentMatch) {
		metadata.parent = parentMatch[1];
	}

	// Determine phase from labels
	const phaseLabel = metadata.labels?.find((l) => l.startsWith("phase-"));
	if (phaseLabel) {
		metadata.phase = phaseLabel;
	}

	// Determine priority from labels
	const priorityLabel = metadata.labels?.find((l) => l.startsWith("priority-"));
	if (priorityLabel) {
		metadata.priority = priorityLabel.replace("priority-", "");
	}

	// Check for copilot-suitable and mcp-serena
	metadata.copilotSuitable =
		metadata.labels?.includes("copilot-suitable") || false;
	metadata.mcpSerena = metadata.labels?.includes("mcp-serena") || false;

	return metadata;
}

/**
 * Create GitHub issue using gh CLI
 */
function createGitHubIssue(issueData, dryRun = false) {
	const { title, body, labels, milestone, assignee } = issueData;

	if (dryRun) {
		console.log(`\n📄 [DRY RUN] Would create issue:`);
		console.log(`   Title: ${title}`);
		console.log(`   Labels: ${labels.join(", ")}`);
		console.log(`   Milestone: ${milestone || "None"}`);
		console.log(`   Assignee: ${assignee || "None"}`);
		return null;
	}

	// Ensure all labels exist before creating the issue
	for (const label of labels) {
		ensureLabel(label);
	}

	// Create temporary file for issue body
	const bodyFile = `/tmp/gh-issue-${Date.now()}.md`;
	writeFileSync(bodyFile, body);

	try {
		// Build command with proper argument handling
		const args = [
			"issue",
			"create",
			"--repo",
			REPO,
			"--title",
			title, // Will be properly escaped by execFileSync
			"--body-file",
			bodyFile,
		];

		// Add labels
		for (const label of labels) {
			args.push("--label", label);
		}

		// Add milestone (find matching milestone by prefix)
		if (milestone) {
			// Clean up milestone name - extract just the short title if it's a full description
			const shortMilestone = milestone.split("(")[0].trim();
			const matchedMilestone = findMatchingMilestone(shortMilestone);
			if (matchedMilestone) {
				args.push("--milestone", matchedMilestone);
			} else {
				console.warn(`⚠️  Milestone not found: ${shortMilestone}`);
			}
		}

		// Add assignee
		if (assignee) {
			args.push("--assignee", assignee);
		}

		const output = execFileSync("gh", args, { encoding: "utf-8" });
		const issueUrl = output.trim();

		console.log(`✅ Created: ${title}`);
		console.log(`   ${issueUrl}`);

		// Clean up temp file
		unlinkSync(bodyFile);

		return issueUrl;
	} catch (error) {
		// Clean up temp file even on error
		try {
			unlinkSync(bodyFile);
		} catch {
			// Ignore cleanup errors
		}
		console.error(`❌ Failed to create issue: ${title}`);
		console.error(error.message);
		return null;
	}
}

/**
 * Process a single issue draft file
 */
async function processIssueFile(filePath) {
	const content = await fs.readFile(filePath, "utf-8");
	const metadata = extractMetadata(content);

	if (!metadata.title) {
		console.warn(`⚠️  Skipping ${basename(filePath)}: No title found`);
		return null;
	}

	// Determine if this is a parent issue
	const isParent = basename(filePath).match(/^\d{3}-parent-/);

	return {
		file: basename(filePath),
		isParent,
		title: metadata.title,
		taskId: metadata.taskId,
		body: content,
		labels: metadata.labels || [],
		milestone: metadata.milestone,
		mode: metadata.mode || "serial",
		phase: metadata.phase,
		priority: metadata.priority,
		dependsOn: metadata.dependsOn,
		blocks: metadata.blocks,
		estimate: metadata.estimate,
		copilotSuitable: metadata.copilotSuitable,
		mcpSerena: metadata.mcpSerena,
	};
}

/**
 * Create milestones from milestones.md
 */
async function createMilestones() {
	console.log("📅 GitHub Milestone Creation Tool\n");

	if (options.dryRun) {
		console.log("📋 Running in DRY RUN mode (no milestones will be created)\n");
	}

	// Read milestones file
	const content = await fs.readFile(MILESTONES_FILE, "utf-8");
	const milestones = parseMilestones(content);

	console.log(`Found ${milestones.length} milestone definitions\n`);

	// Filter by milestone if specified
	let filteredMilestones = milestones;
	if (options.milestone) {
		filteredMilestones = milestones.filter((m) => m.id === options.milestone);
		if (filteredMilestones.length === 0) {
			console.error(`❌ Milestone "${options.milestone}" not found`);
			process.exit(1);
		}
	}

	console.log(`Creating ${filteredMilestones.length} milestones...\n`);

	// Create milestones
	const created = [];
	for (const milestone of filteredMilestones) {
		const result = createGitHubMilestone(milestone, options.dryRun);
		if (result) {
			created.push(result);
		}

		// Rate limit
		if (!options.dryRun) {
			await new Promise((resolve) => setTimeout(resolve, 500));
		}
	}

	console.log(`\n✨ Done! Created ${created.length} milestones`);
}

/**
 * Get issue ID from GitHub API
 */
function getIssueId(issueNumber) {
	try {
		const output = execSync(
			`gh api repos/${REPO}/issues/${issueNumber} --jq '.node_id'`,
			{ encoding: "utf-8" },
		);
		return output.trim();
	} catch {
		console.error(`❌ Failed to get ID for issue #${issueNumber}`);
		return null;
	}
}

/**
 * Link sub-issues to parent epic using GitHub sub-issues API
 */
async function linkSubIssuesToParents() {
	console.log("🔗 Linking Sub-Issues to Parent Epics\n");

	// Get all epic issues
	const epicsOutput = execSync(
		`gh issue list --repo ${REPO} --label epic --state open --json number,title`,
		{ encoding: "utf-8" },
	);
	const epics = JSON.parse(epicsOutput);

	console.log(`Found ${epics.length} epic issues\n`);

	// For each epic, find matching sub-issues by phase
	for (const epic of epics) {
		const phaseMatch = epic.title.match(/Phase (\d+)/);
		if (!phaseMatch) continue;

		const phase = phaseMatch[1];
		console.log(`\n📋 Processing ${epic.title}`);

		// Get all phase issues that aren't epics
		const phaseIssuesOutput = execSync(
			`gh issue list --repo ${REPO} --label "phase-${phase}" --state open --json number,title,labels`,
			{ encoding: "utf-8" },
		);
		const allPhaseIssues = JSON.parse(phaseIssuesOutput);

		// Filter out epics in JavaScript
		const phaseIssues = allPhaseIssues.filter(
			(issue) => !issue.labels.some((label) => label.name === "epic"),
		);

		console.log(`   Found ${phaseIssues.length} sub-issues for phase ${phase}`);

		// Get parent issue ID
		const parentId = getIssueId(epic.number);
		if (!parentId) continue;

		// Link each sub-issue
		for (const subIssue of phaseIssues) {
			const subIssueId = getIssueId(subIssue.number);
			if (!subIssueId) continue;

			try {
				// Use GraphQL mutation to add sub-issue
				const mutation = `mutation {
					addSubIssue(input: {
						issueId: "${parentId}"
						subIssueId: "${subIssueId}"
					}) {
						issue {
							number
						}
					}
				}`;

				execSync(`gh api graphql -f query='${mutation}'`, {
					encoding: "utf-8",
				});

				console.log(`   ✅ Linked #${subIssue.number} to epic #${epic.number}`);

				// Rate limit
				await new Promise((resolve) => setTimeout(resolve, 300));
			} catch (error) {
				console.error(
					`   ⚠️  Failed to link #${subIssue.number}: ${error.message}`,
				);
			}
		}
	}

	console.log(`\n✨ Done linking sub-issues!`);
}

/**
 * Update parent issue bodies to replace #TBD with actual issue numbers
 */
async function updateParentIssueBodies() {
	console.log("📝 Updating Parent Issue Bodies\n");

	// Load mapping file if specified
	let mappingData = null;
	if (options.mappingFile) {
		try {
			const mappingContent = await fs.readFile(options.mappingFile, "utf-8");
			mappingData = JSON.parse(mappingContent);
			console.log(`📋 Loaded mapping from ${options.mappingFile}\n`);
		} catch (error) {
			console.error(`❌ Failed to load mapping file: ${error.message}`);
			process.exit(1);
		}
	}

	// Get all epic issues
	const epicsOutput = execSync(
		`gh issue list --repo ${REPO} --label epic --state open --json number,title,body`,
		{ encoding: "utf-8" },
	);
	const epics = JSON.parse(epicsOutput);

	console.log(`Found ${epics.length} epic issues\n`);

	for (const epic of epics) {
		const phaseMatch = epic.title.match(/Phase (\d+)/);
		if (!phaseMatch) continue;

		const phase = phaseMatch[1];
		console.log(`\n📋 Processing ${epic.title}`);

		// Check if body contains #TBD
		if (!epic.body.includes("#TBD")) {
			console.log(`   ℹ️  No #TBD placeholders found, skipping`);
			continue;
		}

		// Build task map from either mapping file or GitHub API
		const taskMap = {};

		if (mappingData) {
			// Use mapping file: convert P1-001 keys to numeric taskNum
			for (const [taskId, issueNum] of Object.entries(mappingData)) {
				const match = taskId.match(/P\d+-(\d+)/);
				if (match) {
					const taskNum = Number.parseInt(match[1], 10);
					taskMap[taskNum] = issueNum;
				}
			}
			console.log(`   Using ${Object.keys(taskMap).length} mappings from file`);
		} else {
			// Query GitHub API for phase issues
			const phaseIssuesOutput = execSync(
				`gh issue list --repo ${REPO} --label "phase-${phase}" --state open --json number,title,labels --limit 100`,
				{ encoding: "utf-8" },
			);
			const allPhaseIssues = JSON.parse(phaseIssuesOutput);

			// Filter out epics in JavaScript instead of jq
			const phaseIssues = allPhaseIssues
				.filter((issue) => !issue.labels.some((label) => label.name === "epic"))
				.sort((a, b) => a.number - b.number);

			console.log(`   Found ${phaseIssues.length} sub-issues from GitHub`);

			// Extract task IDs from sub-issue titles (e.g., "P1-001", "P2-015")
			for (const issue of phaseIssues) {
				const taskMatch = issue.title.match(/P\d+-(\d+)/);
				if (taskMatch) {
					const taskNum = Number.parseInt(taskMatch[1], 10);
					taskMap[taskNum] = issue.number;
				}
			}
		}

		// Replace #TBD with actual issue numbers
		let updatedBody = epic.body;
		const tableRows = updatedBody.match(/\|\s*\d+\s*\|\s*#TBD\s*\|[^\n]+/g);

		if (tableRows) {
			for (const row of tableRows) {
				const rowMatch = row.match(
					/\|\s*(\d+)\s*\|\s*#TBD\s*\|\s*P\d+-(\d+)\s*\|/,
				);
				if (rowMatch) {
					const taskNum = Number.parseInt(rowMatch[2], 10);
					const issueNumber = taskMap[taskNum];
					if (issueNumber) {
						const newRow = row.replace("#TBD", `#${issueNumber}`);
						updatedBody = updatedBody.replace(row, newRow);
						console.log(
							`   Updated row ${rowMatch[1]}: #TBD → #${issueNumber}`,
						);
					}
				}
			}

			// Update the issue body
			if (updatedBody !== epic.body) {
				if (options.dryRun) {
					console.log(`   [DRY RUN] Would update issue #${epic.number}`);
				} else {
					try {
						// Write body to temp file
						const bodyFile = `/tmp/gh-epic-body-${Date.now()}.md`;
						writeFileSync(bodyFile, updatedBody);

						execFileSync(
							"gh",
							[
								"issue",
								"edit",
								epic.number.toString(),
								"--body-file",
								bodyFile,
							],
							{ encoding: "utf-8" },
						);

						unlinkSync(bodyFile);
						console.log(`   ✅ Updated issue #${epic.number}`);

						// Rate limit
						await new Promise((resolve) => setTimeout(resolve, 500));
					} catch (error) {
						console.error(
							`   ❌ Failed to update #${epic.number}: ${error.message}`,
						);
					}
				}
			}
		}
	}

	console.log(`\n✨ Done updating parent issues!`);
}

/**
 * Main execution
 */
async function main() {
	// Handle milestone creation mode
	if (options.createMilestones) {
		await createMilestones();
		return;
	}

	// Handle link sub-issues mode
	if (options.linkSubIssues) {
		await linkSubIssuesToParents();
		return;
	}

	// Handle update parents mode
	if (options.updateParents) {
		await updateParentIssueBodies();
		return;
	}

	console.log("🚀 GitHub Issue Creation Tool\n");

	if (options.dryRun) {
		console.log("📋 Running in DRY RUN mode (no issues will be created)\n");
	}

	// Read all issue draft files
	const files = await fs.readdir(ISSUES_DRAFT_DIR);
	const issueFiles = files
		.filter((f) => f.match(/^(\d{3}-(sub|parent)-|p\d+-\d+-sub-).+\.md$/))
		.sort();

	console.log(`Found ${issueFiles.length} issue draft files\n`);

	// Process each file
	const issues = [];
	for (const file of issueFiles) {
		const filePath = join(ISSUES_DRAFT_DIR, file);
		const issue = await processIssueFile(filePath);

		if (issue) {
			// Apply filters
			if (options.skipParents && issue.isParent) {
				continue;
			}
			if (options.phase && !issue.phase?.includes(`phase-${options.phase}`)) {
				continue;
			}
			if (options.parallel && issue.mode !== "parallel") {
				continue;
			}
			if (options.serial && issue.mode !== "serial") {
				continue;
			}

			issues.push(issue);
		}
	}

	console.log(`\n📊 Summary:`);
	console.log(`   Total issues to create: ${issues.length}`);
	console.log(`   Parent issues: ${issues.filter((i) => i.isParent).length}`);
	console.log(
		`   Sub-task issues: ${issues.filter((i) => !i.isParent).length}`,
	);
	console.log(
		`   By mode: ${issues.filter((i) => i.mode === "parallel").length} parallel, ${issues.filter((i) => i.mode === "serial").length} serial`,
	);
	console.log(
		`   Copilot-suitable: ${issues.filter((i) => i.copilotSuitable).length}`,
	);
	console.log(
		`   Requires MCP Serena: ${issues.filter((i) => i.mcpSerena).length}\n`,
	);

	// Create issues
	const created = [];
	for (const issue of issues) {
		const url = createGitHubIssue(issue, options.dryRun);
		if (url) {
			created.push({ ...issue, url });
		}

		// Rate limit: wait 1 second between creates
		if (!options.dryRun) {
			await new Promise((resolve) => setTimeout(resolve, 1000));
		}
	}

	console.log(`\n✨ Done! Created ${created.length} issues`);

	// Save mapping file with unique timestamp
	if (!options.dryRun && created.length > 0) {
		const timestamp = new Date()
			.toISOString()
			.replace(/[:.]/g, "-")
			.slice(0, -5);
		const mappingFile = options.exportMapping
			? `artifacts/issue-mapping-${timestamp}.json`
			: "plan-v0.13.x/issue-mapping.json";

		// Ensure artifacts directory exists if using --export-mapping
		if (options.exportMapping) {
			await fs.mkdir("artifacts", { recursive: true });
		}

		// Create mapping with task IDs extracted from titles
		const mapping = {};
		for (const issue of created) {
			const taskMatch = issue.title.match(/P(\d+)-(\d+)/);
			if (taskMatch) {
				const taskId = `P${taskMatch[1]}-${taskMatch[2]}`;
				const issueNumber = issue.url.split("/").pop();
				mapping[taskId] = Number.parseInt(issueNumber, 10);
			}
		}

		await fs.writeFile(mappingFile, JSON.stringify(mapping, null, 2));

		console.log(`📝 Saved issue mapping to ${mappingFile}`);
		if (options.exportMapping) {
			console.log(`   Use: --mapping=${mappingFile} to update parent tables`);
		}
	}
}

main().catch(console.error);

#!/usr/bin/env node

/**
 * Create Parent Issues Only
 *
 * Creates the 4 parent (epic) issues and saves their issue numbers to a mapping file.
 *
 * Usage:
 *   node scripts/create-parent-issues.js [--dry-run]
 */

import { execFileSync, execSync } from "node:child_process";
import { promises as fs, unlinkSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const ISSUES_DRAFT_DIR = "plan-v0.13.x/issues-draft";
const REPO = "Anselmoo/mcp-ai-agent-guidelines";

// Parse command line arguments
const args = process.argv.slice(2);
const dryRun = args.includes("--dry-run");

// Parent issue files in order
const PARENT_FILES = [
	"001-parent-phase1-discoverability.md",
	"002-parent-phase2-domain-extraction.md",
	"003-parent-phase3-broken-tools.md",
	"004-parent-phase4-speckit-integration.md",
];

/**
 * Extract metadata from issue markdown header
 */
function extractMetadata(content) {
	const metadata = {};

	// Extract title
	const titleMatch = content.match(/^# (.+)$/m);
	if (titleMatch) {
		metadata.title = titleMatch[1];
	}

	// Extract labels
	const labelsMatch = content.match(/> \*\*Labels\*\*:\s*(.+)/);
	if (labelsMatch) {
		const labelsStr = labelsMatch[1];
		metadata.labels = labelsStr
			.split(",")
			.map((l) => l.trim().replace(/`/g, ""));
	}

	// Extract milestone
	const milestoneMatch = content.match(/> \*\*Milestone\*\*:\s*(.+)/);
	if (milestoneMatch) {
		metadata.milestone = milestoneMatch[1].trim();
	}

	return metadata;
}

/**
 * Find matching milestone by prefix
 */
function findMatchingMilestone(milestoneTitle) {
	try {
		const output = execSync(
			`gh api repos/${REPO}/milestones --jq '.[].title'`,
			{ encoding: "utf-8" },
		);
		const milestones = output.trim().split("\n");

		// Try exact match first
		if (milestones.includes(milestoneTitle)) {
			return milestoneTitle;
		}

		// Try prefix match (e.g., "M2: Discoverability" matches "M2: Discoverability (End Week 4)")
		const prefixMatch = milestones.find((m) => m.startsWith(milestoneTitle));
		return prefixMatch || null;
	} catch (error) {
		console.warn(`⚠️  Could not query milestones: ${error.message}`);
		return null;
	}
}

/**
 * Ensure label exists
 */
function ensureLabel(label) {
	try {
		const output = execSync(
			`gh label list --repo ${REPO} --json name --jq '.[].name'`,
			{ encoding: "utf-8" },
		);
		const labels = output.trim().split("\n");

		if (!labels.includes(label)) {
			console.warn(`⚠️  Label not found: ${label}`);
		}
	} catch {
		// Ignore - label might exist
	}
}

/**
 * Create GitHub issue
 */
function createGitHubIssue(issueData, dryRun = false) {
	const { title, body, labels, milestone } = issueData;

	if (dryRun) {
		console.log(`\n📄 [DRY RUN] Would create parent issue:`);
		console.log(`   Title: ${title}`);
		console.log(`   Labels: ${labels.join(", ")}`);
		console.log(`   Milestone: ${milestone || "None"}`);
		return null;
	}

	// Ensure all labels exist
	for (const label of labels) {
		ensureLabel(label);
	}

	// Create temporary file for issue body
	const bodyFile = `/tmp/gh-issue-${Date.now()}.md`;
	writeFileSync(bodyFile, body);

	try {
		const args = [
			"issue",
			"create",
			"--repo",
			REPO,
			"--title",
			title,
			"--body-file",
			bodyFile,
		];

		// Add labels
		for (const label of labels) {
			args.push("--label", label);
		}

		// Add milestone
		if (milestone) {
			const shortMilestone = milestone.split("(")[0].trim();
			const matchedMilestone = findMatchingMilestone(shortMilestone);
			if (matchedMilestone) {
				args.push("--milestone", matchedMilestone);
			} else {
				console.warn(`⚠️  Milestone not found: ${shortMilestone}`);
			}
		}

		const output = execFileSync("gh", args, { encoding: "utf-8" });
		const issueUrl = output.trim();
		const issueNumber = Number.parseInt(issueUrl.split("/").pop(), 10);

		console.log(`✅ Created: ${title}`);
		console.log(`   ${issueUrl}`);

		unlinkSync(bodyFile);

		return { url: issueUrl, number: issueNumber };
	} catch (error) {
		try {
			unlinkSync(bodyFile);
		} catch {
			// Ignore
		}
		console.error(`❌ Failed to create issue: ${title}`);
		console.error(error.message);
		return null;
	}
}

/**
 * Process parent issue file
 */
async function processParentFile(filename) {
	const filePath = join(ISSUES_DRAFT_DIR, filename);
	const content = await fs.readFile(filePath, "utf-8");
	const metadata = extractMetadata(content);

	if (!metadata.title) {
		console.warn(`⚠️  Skipping ${filename}: No title found`);
		return null;
	}

	return {
		file: filename,
		title: metadata.title,
		body: content,
		labels: metadata.labels || [],
		milestone: metadata.milestone,
	};
}

async function main() {
	console.log("🚀 Creating Parent (Epic) Issues\n");

	if (dryRun) {
		console.log("📋 Running in DRY RUN mode\n");
	}

	// Process parent files
	const parentIssues = [];
	for (const filename of PARENT_FILES) {
		const issue = await processParentFile(filename);
		if (issue) {
			parentIssues.push(issue);
		}
	}

	console.log(`Found ${parentIssues.length} parent issues to create\n`);

	// Create issues
	const created = [];
	for (const issue of parentIssues) {
		const result = createGitHubIssue(issue, dryRun);
		if (result) {
			created.push({
				file: issue.file,
				number: result.number,
				url: result.url,
			});
		}

		// Rate limit
		if (!dryRun) {
			await new Promise((resolve) => setTimeout(resolve, 1000));
		}
	}

	console.log(`\n✨ Done! Created ${created.length} parent issues`);

	// Save mapping
	if (!dryRun && created.length > 0) {
		await fs.mkdir("artifacts", { recursive: true });

		const mapping = {};
		for (const item of created) {
			mapping[item.file] = item.number;
		}

		const mappingFile = "artifacts/parent-mapping.json";
		await fs.writeFile(mappingFile, JSON.stringify(mapping, null, 2));

		console.log(`\n📝 Saved parent mapping to ${mappingFile}`);
		console.log("\nNext steps:");
		console.log(
			"1. Update sub-issue Parent headers: node scripts/update-parent-refs.js",
		);
		console.log(
			"2. Create sub-issues: node scripts/create-github-issues.js --skip-parents --export-mapping",
		);
		console.log(
			"3. Link sub-issues to parents: node scripts/create-github-issues.js --link-sub-issues",
		);
		console.log(
			"4. Update parent tables: node scripts/create-github-issues.js --update-parents --mapping <file>",
		);
	}
}

main().catch(console.error);

#!/usr/bin/env node

/**
 * Extract all external links from markdown files
 *
 * This script scans all markdown files in the repository and extracts
 * external links (http/https URLs) for review and validation.
 *
 * Usage:
 *   npm run links:extract
 *   npm run links:extract -- --format=json
 *   npm run links:extract -- --format=csv
 */

import { readdirSync, readFileSync, statSync } from "node:fs";
import { join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = join(__filename, "..");

// Configuration
const REPO_ROOT = join(__dirname, "..");
const EXCLUDED_DIRS = ["node_modules", "dist", "coverage", "build", ".git"];

// Parse command line arguments
const args = process.argv.slice(2);
const format =
	args.find((arg) => arg.startsWith("--format="))?.split("=")[1] || "table";
const outputFile = args
	.find((arg) => arg.startsWith("--output="))
	?.split("=")[1];

/**
 * Find all markdown files in directory recursively
 */
function findMarkdownFiles(dir, files = []) {
	const entries = readdirSync(dir);

	for (const entry of entries) {
		const fullPath = join(dir, entry);
		const stat = statSync(fullPath);

		if (stat.isDirectory()) {
			if (!EXCLUDED_DIRS.includes(entry)) {
				findMarkdownFiles(fullPath, files);
			}
		} else if (entry.endsWith(".md")) {
			files.push(fullPath);
		}
	}

	return files;
}

/**
 * Extract external links from markdown content
 *
 * Matches:
 * - [text](http://example.com)
 * - [text](https://example.com)
 * - <http://example.com>
 * - <https://example.com>
 * - Bare URLs: http://example.com or https://example.com
 */
function extractExternalLinks(content, filePath) {
	const links = [];

	// Markdown link pattern: [text](url)
	const markdownLinkPattern = /\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g;

	for (const match of content.matchAll(markdownLinkPattern)) {
		links.push({
			url: match[2],
			text: match[1],
			file: filePath,
			type: "markdown",
		});
	}

	// Angle bracket links: <url>
	const angleBracketPattern = /<(https?:\/\/[^>]+)>/g;

	for (const match of content.matchAll(angleBracketPattern)) {
		links.push({
			url: match[1],
			text: match[1],
			file: filePath,
			type: "angle-bracket",
		});
	}

	// Bare URLs (not in markdown links or angle brackets)
	// Negative lookbehind to exclude already matched patterns
	const bareUrlPattern = /(?<!\]\()(?<!<)(https?:\/\/[^\s)<>]+)/g;
	const alreadyMatched = new Set(links.map((l) => l.url));

	for (const match of content.matchAll(bareUrlPattern)) {
		const url = match[1];
		if (!alreadyMatched.has(url)) {
			links.push({
				url,
				text: url,
				file: filePath,
				type: "bare",
			});
			alreadyMatched.add(url);
		}
	}

	return links;
}

/**
 * Group links by domain
 */
function groupByDomain(links) {
	const grouped = {};

	for (const link of links) {
		try {
			const url = new URL(link.url);
			const domain = url.hostname;

			if (!grouped[domain]) {
				grouped[domain] = [];
			}

			grouped[domain].push(link);
		} catch (_error) {
			// Invalid URL, create 'invalid' group
			if (!grouped._invalid) {
				grouped._invalid = [];
			}
			grouped._invalid.push(link);
		}
	}

	return grouped;
}

/**
 * Output as table
 */
function outputTable(links) {
	console.log("\n=== External Links Found ===\n");

	const grouped = groupByDomain(links);
	const domains = Object.keys(grouped).sort();

	for (const domain of domains) {
		console.log(`\n📍 ${domain} (${grouped[domain].length} links)`);
		console.log("─".repeat(80));

		for (const link of grouped[domain]) {
			const relPath = relative(REPO_ROOT, link.file);
			console.log(`  ${link.url}`);
			console.log(`    📄 ${relPath}`);
			if (link.text !== link.url) {
				console.log(`    📝 "${link.text}"`);
			}
			console.log();
		}
	}

	console.log(`\n📊 Summary:`);
	console.log(`   Total links: ${links.length}`);
	console.log(`   Unique domains: ${domains.length}`);
	console.log();
}

/**
 * Output as JSON
 */
function outputJSON(links) {
	const output = {
		summary: {
			totalLinks: links.length,
			uniqueDomains: Object.keys(groupByDomain(links)).length,
			generatedAt: new Date().toISOString(),
		},
		byDomain: groupByDomain(links),
		allLinks: links.map((link) => ({
			...link,
			file: relative(REPO_ROOT, link.file),
		})),
	};

	console.log(JSON.stringify(output, null, 2));
}

/**
 * Output as CSV
 */
function outputCSV(links) {
	console.log("URL,Text,File,Type,Domain");

	for (const link of links) {
		const relPath = relative(REPO_ROOT, link.file);
		let domain = "";

		try {
			domain = new URL(link.url).hostname;
		} catch (_e) {
			domain = "invalid";
		} // Escape CSV fields
		const csvEscape = (str) => `"${str.replace(/"/g, '""')}"`;

		console.log(
			[
				csvEscape(link.url),
				csvEscape(link.text),
				csvEscape(relPath),
				link.type,
				domain,
			].join(","),
		);
	}
}

/**
 * Output as markdown
 */
function outputMarkdown(links) {
	console.log("# External Links Report\n");
	console.log(`Generated: ${new Date().toISOString()}\n`);

	const grouped = groupByDomain(links);
	const domains = Object.keys(grouped).sort();

	console.log("## Summary\n");
	console.log(`- **Total Links**: ${links.length}`);
	console.log(`- **Unique Domains**: ${domains.length}\n`);

	console.log("## Links by Domain\n");

	for (const domain of domains) {
		console.log(`### ${domain}\n`);
		console.log(`${grouped[domain].length} links found\n`);

		for (const link of grouped[domain]) {
			const relPath = relative(REPO_ROOT, link.file);
			console.log(`- [${link.text}](${link.url})`);
			console.log(`  - File: \`${relPath}\``);
			console.log();
		}
	}
}

/**
 * Main execution
 */
function main() {
	console.error("🔍 Scanning for markdown files...");
	const markdownFiles = findMarkdownFiles(REPO_ROOT);
	console.error(`   Found ${markdownFiles.length} markdown files\n`);

	console.error("🔗 Extracting external links...");
	const allLinks = [];

	for (const file of markdownFiles) {
		const content = readFileSync(file, "utf-8");
		const links = extractExternalLinks(content, file);
		allLinks.push(...links);
	}

	console.error(`   Found ${allLinks.length} external links\n`);

	// Output based on format
	switch (format) {
		case "json":
			outputJSON(allLinks);
			break;
		case "csv":
			outputCSV(allLinks);
			break;
		case "markdown":
		case "md":
			outputMarkdown(allLinks);
			break;
		default:
			outputTable(allLinks);
			break;
	} // Write to file if specified
	if (outputFile) {
		console.error(`\n💾 Output also written to: ${outputFile}`);
	}
}

main();

#!/usr/bin/env node

import { promises as fs } from "node:fs";
import { join, posix, resolve } from "node:path";

const PLAN_ROOT = "plan-v0.14.x";

const args = process.argv.slice(2);
const writeChanges = args.includes("--write");
const verbose = args.includes("--verbose");

const rootDir = resolve(process.cwd());
const planRootDir = resolve(rootDir, PLAN_ROOT);

function isExternalLink(link) {
	return /^(?:https?:|mailto:|tel:|#)/i.test(link);
}

function splitLink(link) {
	const hashIndex = link.indexOf("#");
	if (hashIndex === -1) {
		return { path: link, hash: "" };
	}
	return {
		path: link.slice(0, hashIndex),
		hash: link.slice(hashIndex),
	};
}

function toRepoPath(filePath) {
	const normalized = filePath.replace(/\\/g, "/");
	return normalized.startsWith("/") ? normalized.slice(1) : normalized;
}

function resolveRepoLink(link, sourcePath) {
	if (!link) return link;
	if (isExternalLink(link)) return link;
	const trimmed = link.trim();
	if (!trimmed) return link;

	const { path: linkPath, hash } = splitLink(trimmed);
	if (!linkPath) return link;

	const repoPath = toRepoPath(sourcePath);
	if (!repoPath) return link;

	if (linkPath.startsWith("/")) {
		return `${linkPath}${hash}`;
	}

	const baseDir = posix.dirname(repoPath);
	const resolved = posix.normalize(posix.join(baseDir, linkPath));
	return `/${resolved}${hash}`;
}

function shouldRewrite(resolvedPath) {
	if (!resolvedPath.startsWith("/")) return false;
	return resolvedPath.startsWith(`/${PLAN_ROOT}/`);
}

function rewriteMarkdownLinks(text, sourcePath) {
	let changed = false;
	const segments = text.split(/(```[\s\S]*?```)/g);
	const updated = segments
		.map((segment) => {
			if (segment.startsWith("```")) {
				return segment;
			}
			return segment.replace(
				/\[([^\]]+)\]\(([^)]+)\)/g,
				(match, label, link) => {
					const resolved = resolveRepoLink(link, sourcePath);
					if (resolved === link) return match;
					if (!shouldRewrite(resolved)) return match;
					changed = true;
					return `[${label}](${resolved})`;
				},
			);
		})
		.join("");
	return { text: updated, changed };
}

async function listMarkdownFiles(dir) {
	const entries = await fs.readdir(dir, { withFileTypes: true });
	const results = [];

	for (const entry of entries) {
		const fullPath = join(dir, entry.name);
		if (entry.isDirectory()) {
			const nested = await listMarkdownFiles(fullPath);
			results.push(...nested);
			continue;
		}
		if (entry.isFile() && entry.name.toLowerCase().endsWith(".md")) {
			results.push(fullPath);
		}
	}

	return results;
}

async function processFile(filePath) {
	const content = await fs.readFile(filePath, "utf-8");
	const repoPath = toRepoPath(
		path.relative(rootDir, filePath).replace(/\\/g, "/"),
	);
	const { text, changed } = rewriteMarkdownLinks(content, repoPath);

	if (!changed) {
		return { filePath, changed: false };
	}

	if (writeChanges) {
		await fs.writeFile(filePath, text, "utf-8");
	}

	return { filePath, changed: true };
}

async function main() {
	const targetDir = resolve(planRootDir);
	try {
		await fs.access(targetDir);
	} catch {
		console.error(`Plan directory not found: ${targetDir}`);
		process.exit(1);
	}

	const files = await listMarkdownFiles(targetDir);
	const results = [];

	for (const filePath of files) {
		const result = await processFile(filePath);
		if (result.changed || verbose) {
			results.push(result);
		}
	}

	const changedCount = results.filter((item) => item.changed).length;
	const mode = writeChanges ? "updated" : "would update";
	console.log(`Found ${files.length} markdown files. ${mode} ${changedCount}.`);

	for (const result of results) {
		const status = result.changed ? "UPDATED" : "SKIPPED";
		console.log(`${status}: ${result.filePath}`);
	}

	if (!writeChanges) {
		console.log("\nRun with --write to apply changes.");
	}
}

main().catch((error) => {
	console.error(error?.message ?? String(error));
	process.exit(1);
});

#!/usr/bin/env node

/**
 * SVG Visibility Fixer
 *
 * Fixes SVG text visibility issues in dark mode by:
 * 1. Adding explicit light-colored fills for text elements
 * 2. Using color schemes that work in both light and dark modes
 * 3. Adding fallback colors for better compatibility
 */

import { readdirSync, readFileSync, writeFileSync } from "node:fs";
import { extname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = fileURLToPath(new URL(".", import.meta.url));

const DOCS_DIR = join(__dirname, "..", "docs");
const DRY_RUN = process.argv.includes("--dry-run");

// Track changes
const changes = [];

/**
 * Fix SVG text visibility by ensuring proper color values
 *
 * Strategy:
 * - For dark mode, use light colors (#f0f6fc, #c9d1d9, #fff)
 * - For light mode, use dark colors (#24292f, #1f2328, #000)
 * - Add picture element suggestions for better GitHub rendering
 */
function fixSVGVisibility(_filepath, content) {
	let modified = content;
	const changesMade = [];

	// Check if SVG has dark mode media query
	const hasDarkMode = /@media \(prefers-color-scheme: dark\)/.test(content);

	if (!hasDarkMode) {
		// SVG doesn't use media queries, might need different approach
		return { modified: content, changes: [] };
	}

	// Ensure dark mode text colors are light
	// Pattern: find dark mode styles and ensure text fills are light
	modified = modified.replace(
		/@media \(prefers-color-scheme: dark\)\s*\{([^}]+)\}/gs,
		(_match, styles) => {
			let updatedStyles = styles;

			// Fix text-primary to use light color
			updatedStyles = updatedStyles.replace(
				/(\.text-primary\s*\{[^}]*fill:\s*)#[0-9a-fA-F]{6}/g,
				(m, prefix) => {
					if (!m.includes("#f0f6fc") && !m.includes("#fff")) {
						changesMade.push(
							"Updated text-primary fill in dark mode to #f0f6fc",
						);
						return `${prefix}#f0f6fc`;
					}
					return m;
				},
			);

			// Fix text-secondary to use light color
			updatedStyles = updatedStyles.replace(
				/(\.text-secondary\s*\{[^}]*fill:\s*)#[0-9a-fA-F]{6}/g,
				(m, prefix) => {
					if (!m.includes("#c9d1d9") && !m.includes("#fff")) {
						changesMade.push(
							"Updated text-secondary fill in dark mode to #c9d1d9",
						);
						return `${prefix}#c9d1d9`;
					}
					return m;
				},
			);

			return `@media (prefers-color-scheme: dark) {${updatedStyles}}`;
		},
	);

	// Add a default light fill for all text elements that don't have explicit fill
	// This acts as a fallback when media queries don't work
	modified = modified.replace(/<text([^>]*)>/g, (match, attrs) => {
		// If text doesn't have fill attribute, add a light fill
		if (!attrs.includes("fill=")) {
			const hasTextClass = attrs.includes('class="text-');
			const message = hasTextClass
				? "Added light fill to text element with class"
				: "Added default light fill to unclassed text element";
			changesMade.push(message);
			return `<text${attrs} fill="#f0f6fc">`;
		}
		return match;
	});

	return { modified, changes: changesMade };
}

/**
 * Create a markdown snippet showing how to use picture element for better rendering
 */
function generatePictureElementGuide() {
	return `
<!-- Alternative approach for SVG rendering in different themes -->
<!--
<picture>
  <source media="(prefers-color-scheme: dark)" srcset="../.frames-static/header-dark.svg">
  <source media="(prefers-color-scheme: light)" srcset="../.frames-static/header-light.svg">
  <img alt="Header" src="../.frames-static/header.svg">
</picture>
-->
`.trim();
}

/**
 * Scan and fix all SVG files
 */
function fixAllSVGs() {
	console.log("🔧 Fixing SVG visibility issues...\n");

	if (DRY_RUN) {
		console.log("🔍 DRY RUN MODE - No files will be modified\n");
	}

	const svgDir = join(DOCS_DIR, ".frames-static");
	const files = readdirSync(svgDir);

	let totalFixed = 0;
	let totalChanges = 0;

	for (const file of files) {
		if (extname(file) !== ".svg") continue;

		const filepath = join(svgDir, file);
		const content = readFileSync(filepath, "utf-8");

		const { modified, changes: fileChanges } = fixSVGVisibility(
			filepath,
			content,
		);

		if (fileChanges.length > 0) {
			totalFixed++;
			totalChanges += fileChanges.length;

			console.log(`📝 ${relative(DOCS_DIR, filepath)}`);
			for (const change of fileChanges) {
				console.log(`   ✓ ${change}`);
			}
			console.log();

			changes.push({
				file: relative(DOCS_DIR, filepath),
				changes: fileChanges,
			});

			if (!DRY_RUN) {
				writeFileSync(filepath, modified, "utf-8");
			}
		}
	}

	console.log("=".repeat(80));
	console.log(`\n✨ Summary:`);
	console.log(`   Files fixed: ${totalFixed}`);
	console.log(`   Total changes: ${totalChanges}`);

	if (DRY_RUN) {
		console.log("\n💡 Run without --dry-run to apply changes");
	} else if (totalFixed > 0) {
		console.log("\n✅ SVG files have been updated!");
	} else {
		console.log("\n✅ All SVG files already have proper visibility!");
	}

	// Print guide about picture element
	if (totalFixed > 0) {
		console.log("\n📖 Additional Recommendation:");
		console.log(
			"   For better GitHub dark mode support, consider using <picture> elements",
		);
		console.log("   or creating separate light/dark SVG variants.");
		console.log("\n   Example markdown:");
		console.log(generatePictureElementGuide());
	}

	console.log();
}

