	validation: 975,
};

const PRIORITY_LABELS = {
	P0: "P0-critical",
	P1: "P1-high",
	P2: "P2-medium",
	P3: "P3-low",
};

const MERMAID_PLACEHOLDERS = {
	flow: "graph TD\n  A[Load task file] --> B[Extract metadata]\n  B --> C[Normalize fields]\n  C --> D[Build issue body]\n  D --> E[Emit JSON]",
	class:
		"classDiagram\n  class Issue {\n    +title\n    +body\n    +labels\n    +milestone\n  }\n  class Mermaid {\n    +flow\n    +class\n    +sequence\n    +risk_matrix\n  }\n  Issue --> Mermaid",
	sequence:
		"sequenceDiagram\n  participant User\n  participant Script\n  participant GitHubCLI\n  participant GitHubAPI\n  User->>Script: Run generator\n  Script-->>User: JSON output\n  Script->>GitHubCLI: gh issue create (optional)\n  GitHubCLI->>GitHubAPI: Create issue\n  GitHubAPI-->>GitHubCLI: Issue URL\n  GitHubCLI-->>Script: URL\n  Script-->>User: Creation summary",
	risk_matrix:
		'quadrantChart\n  title Risk Matrix\n  x-axis Low Impact --> High Impact\n  y-axis Low Likelihood --> High Likelihood\n  quadrant-1 Low Likelihood / High Impact\n  quadrant-2 High Likelihood / High Impact\n  quadrant-3 High Likelihood / Low Impact\n  quadrant-4 Low Likelihood / Low Impact\n  "Schema mismatch" : [0.7, 0.3]\n  "Missing labels" : [0.6, 0.7]\n  "Dependency error" : [0.4, 0.6]\n  "Large payload" : [0.3, 0.4]',
};

let existingLabelsCache = null;

const args = process.argv.slice(2);
const dryRunIndex = args.findIndex((arg) => arg.startsWith("--dry-run-limit"));
const dryRunLimitValue =
	dryRunIndex === -1
		? null
		: args[dryRunIndex].includes("=")
			? args[dryRunIndex].split("=")[1]
			: args[dryRunIndex + 1];
const dryRunLimit = Math.max(1, Number(dryRunLimitValue || 4));

const options = {
	output: args.includes("--stdout"),
	create: args.includes("--create"),
	dryRun: args.includes("--dry-run"),
};

function getExistingLabels() {
	if (existingLabelsCache) {
		return existingLabelsCache;
	}
	try {
		const output = execSync(
			`gh label list --repo ${REPO} --json name --limit 200`,
			{ encoding: "utf-8" },
		);
		const labels = JSON.parse(output);
		existingLabelsCache = new Set(labels.map((label) => label.name));
		return existingLabelsCache;
	} catch {
		existingLabelsCache = null;
		return null;
	}
}

function getValidationLabelExists() {
	const labels = getExistingLabels();
	return labels ? labels.has("validation") : false;
}

function parseHeader(lines) {
	let title = null;
	let taskId = null;
	let phase = null;
	let priority = null;
	let estimate = null;
	let dependencies = null;

	if (lines.length > 0 && lines[0].startsWith("# ")) {
		title = lines[0].slice(2).trim();
		const match = title.match(/\b([TV]-\d+)\b/);
		if (match) {
			taskId = match[1];
		}
	}

	for (const line of lines) {
		if (line.startsWith("**Task ID**:")) {
			taskId = line.split(":", 2)[1].trim();
		}
		if (line.startsWith("**Phase**:")) {
			const phaseValue = line.split(":", 2)[1].trim();
			if (phaseValue.toLowerCase().startsWith("validation")) {
				phase = "validation";
			} else {
				const match = phaseValue.match(/^(\d+(?:\.5)?)/);
				phase = match ? match[1] : phaseValue;
			}
		}
		if (line.startsWith("**Priority**:")) {
			const match = line.match(/\b(P\d)\b/);
			if (match) {
				priority = match[1];
			}
		}
		if (line.startsWith("**Estimate**:")) {
			estimate = line.split(":", 2)[1].trim();
		}
		if (line.startsWith("**Dependencies**:")) {
			dependencies = line.split(":", 2)[1].trim();
		}
	}

	return { title, taskId, phase, priority, estimate, dependencies };
}

function parseEstimateHours(estimate) {
	if (!estimate) return null;
	const matches = estimate.match(/\d+(?:\.\d+)?/g);
	if (!matches) return null;
	const total = matches.reduce((sum, value) => sum + Number(value), 0);
	return Number.isInteger(total) ? total : Number(total.toFixed(2));
}

function extractDependencies(depText) {
	if (!depText || depText.toLowerCase() === "none") {
		return [];
	}
	const matches = depText.match(/[TV]-\d+/g);
	return matches ? matches : [];
}

function cleanBody(content) {
	// Parse content to identify fenced code blocks
	const lines = content.split("\n");
	const result = [];
	let inCodeBlock = false;

	for (let i = 0; i < lines.length; i++) {
		const line = lines[i];

		// Track code block boundaries
		if (line.trim().startsWith("```")) {
			inCodeBlock = !inCodeBlock;
		}

		// Filter out Owner/Reviewer lines
		if (line.startsWith("**Owner**:") || line.startsWith("**Reviewer**:")) {
			continue;
		}

		// Preserve trailing whitespace in code blocks, trim elsewhere
		const processedLine = inCodeBlock ? line : line.replace(/\s+$/g, "");
		result.push(processedLine);
	}

	return result.join("\n");
}

function ensureSectionsForCodeBlocks(text) {
	if (!text.includes("```")) {
		return text;
	}

	const hasOverview = /^##\s+Overview\b/m.test(text);
	const hasImplementation = /^##\s+Implementation Details\b/m.test(text);
	const lines = text.split("\n");

	if (!hasOverview) {
		let insertIndex = lines.findIndex((line) => line.startsWith("# "));
		insertIndex = insertIndex === -1 ? 0 : insertIndex + 1;
		while (insertIndex < lines.length && lines[insertIndex].trim() === "") {
			insertIndex += 1;
		}
		lines.splice(insertIndex, 0, "## Overview", "");
	}

	if (!hasImplementation) {
		const codeIndex = lines.findIndex((line) => line.trim().startsWith("```"));
		if (codeIndex !== -1) {
			lines.splice(
				codeIndex,
				0,
				"",
				"## Implementation Details",
				"",
				"Summary: See code snippets below for implementation guidance.",
			);
		}
	}

	return lines.join("\n");
}

function detectFooterPriorityMismatch(text, priority) {
	const match = text.match(
		/\*Task:\s*[TV]-\d+\s*\|\s*Phase:[^|]+\|\s*Priority:\s*([^*]+)\*/,
	);
	if (!match) return null;
	const footerPriority = match[1].trim();
	if (footerPriority === "TBD") {
		return `Footer priority is TBD; using header priority ${priority}.`;
	}
	return null;
}

function addInconsistencyNote(text, note) {
	if (!note) return text;
	const lines = text.split("\n");
	let insertIndex = lines.findIndex((line) => line.trim() === "---");
	if (insertIndex === -1) {
		insertIndex = lines.findIndex((line) => line.startsWith("# "));
		insertIndex = insertIndex === -1 ? 0 : insertIndex + 1;
	} else {
		insertIndex += 1;
	}
	lines.splice(insertIndex, 0, `**Note**: ${note}`, "");
	return lines.join("\n");
}

function categoryLabel(title, filename) {
	const lower = `${title} ${filename}`.toLowerCase();
	if (lower.includes("integration test")) return "integration-test";
	if (["test", "verify", "validation"].some((term) => lower.includes(term))) {
		return "testing";
	}
	if (
		["doc", "guide", "documentation", "adr"].some((term) =>
			lower.includes(term),
		)
	) {
		return "documentation";
	}
	if (
		["ci", "workflow", "pipeline", "cicd"].some((term) => lower.includes(term))
	) {
		return "ci-cd";
	}
	return "implementation";
}

async function listTaskFiles() {
	const files = [];
	for (const dir of TASK_DIRS) {
		const entries = await fs.readdir(dir);
		for (const entry of entries) {
			if (
				entry.toLowerCase() === "readme.md" ||
				entry.toLowerCase() === "migration-checklist.md"
			) {
				continue;
			}
			if (!/^[TV]-\d+.*\.md$/.test(entry)) {
				continue;
			}
			files.push(join(dir, entry));
		}
	}
	return files.sort();
}

function buildParentIssueBody(parent) {
	const childSearchUrl = buildChildIssueSearchUrl(parent.phase);
	return `# ${parent.title}\n\n## Summary\n\nPhase-level parent issue for ${parent.title}.\n\n## Scope\n\n- Track all ${parent.title} tasks\n- Monitor milestones and dependencies\n- Ensure validation tasks are completed\n\n## Child Issues\n\n- ${childSearchUrl}\n\n## Acceptance Criteria\n\n- [ ] All child issues for ${parent.title} are created\n- [ ] Milestone ${parent.milestone} assigned\n- [ ] Phase completion verified\n`;
}

function toRepoPath(filePath) {
	const normalized = filePath.replace(/\\/g, "/");
	return normalized.startsWith("/") ? normalized.slice(1) : normalized;
}

function buildBlobUrl(repoPath) {
	return `${REPO_BLOB}/${repoPath}`;
}

function buildIssueUrl(issueNumber) {
	return `${REPO_ISSUES}/${issueNumber}`;
}

function isExternalLink(link) {
	return /^(?:https?:|mailto:|tel:|#)/i.test(link);
}

function splitLink(link) {
	const hashIndex = link.indexOf("#");
	if (hashIndex === -1) {
		return { path: link, hash: "" };
	}
	return {
		path: link.slice(0, hashIndex),
		hash: link.slice(hashIndex),
	};
}

function resolveRepoLink(link, sourcePath) {
	if (!link) return link;
	if (isExternalLink(link)) return link;
	const { path: linkPath, hash } = splitLink(link.trim());
	const repoPath = toRepoPath(sourcePath);
	if (!repoPath) return link;
	if (linkPath.startsWith("/")) {
		return `${REPO_BLOB}/${linkPath.slice(1)}${hash}`;
	}
	const baseDir = posix.dirname(repoPath);
	const resolved = posix.normalize(posix.join(baseDir, linkPath));
	return `${REPO_BLOB}/${resolved}${hash}`;
}

function rewriteMarkdownLinks(text, sourcePath) {
	if (!sourcePath) return text;
	return text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, (match, label, link) => {
		const resolved = resolveRepoLink(link, sourcePath);
		if (resolved === link) return match;
		return `[${label}](${resolved})`;
	});
}

function insertSectionAfterDivider(text, sectionLines) {
	const lines = text.split("\n");
	const dividerIndex = lines.findIndex((line) => line.trim() === "---");
	const insertIndex = dividerIndex === -1 ? 1 : dividerIndex + 1;
	lines.splice(insertIndex, 0, "", ...sectionLines, "");
	return lines.join("\n");
}

function ensureParentIssueSection(text, parentIssue) {
	if (!parentIssue || text.includes("## Parent Issue")) {
		return text;
	}
	const parentUrl = buildIssueUrl(parentIssue);
	return insertSectionAfterDivider(text, [
		"## Parent Issue",
		"",
		`- ${parentUrl}`,
	]);
}

function ensureSourceSection(text, sourceUrl) {
	if (!sourceUrl || text.includes("## Source")) {
		return text;
	}
	return insertSectionAfterDivider(text, ["## Source", "", `- ${sourceUrl}`]);
}

function buildChildIssueSearchUrl(phase) {
	const labels = ["v0.14.x"];
	if (phase === "validation") {
		labels.push(getValidationLabelExists() ? "validation" : "testing");
	} else if (PHASE_LABELS[phase]) {
		labels.push(PHASE_LABELS[phase]);
	}
	const query = labels.map((label) => `label:${label}`).join(" ");
	return `${REPO_URL}/issues?q=${encodeURIComponent(query)}`;
}

function uniqueArray(values) {
	return [...new Set(values.filter(Boolean))];
}

async function buildIssues() {
	const validationLabelExists = getValidationLabelExists();
	const taskFiles = await listTaskFiles();
	const issues = [];

	for (const parent of PARENT_ISSUES) {
		const labels = [...parent.labels];
		if (parent.phase === "validation" && getValidationLabelExists()) {
			labels.splice(labels.indexOf("testing"), 1, "validation");
		}
		const parentIssueUrl = buildIssueUrl(parent.parent_issue);
		issues.push({
			title: parent.title,
			body: buildParentIssueBody(parent),
			labels: uniqueArray(labels),
			milestone: parent.milestone,
			parent_issue: parent.parent_issue,
			parent_issue_url: parentIssueUrl,
			phase: parent.phase,
			priority: parent.priority,
			task_id:
				parent.phase === "validation" ? "V-PARENT" : `PARENT-${parent.phase}`,
			dependencies: [],
			estimate_hours: null,
			source_path: "",
			source_url: "",
			child_issue_query: buildChildIssueSearchUrl(parent.phase),
			child_task_ids: [],
			inconsistencies: [],
			mermaid: { ...MERMAID_PLACEHOLDERS },
		});
	}
	const seen = new Set();

	for (const file of taskFiles) {
		const content = await fs.readFile(file, "utf-8");
		const lines = content.split("\n");
		const { title, taskId, phase, priority, estimate, dependencies } =
			parseHeader(lines);

		if (!title || !taskId || !phase || !priority) {
			continue;
		}

		if (seen.has(taskId)) {
			throw new Error(`Duplicate task ID detected: ${taskId}`);
		}
		seen.add(taskId);

		const estimateHours = parseEstimateHours(estimate);
		const deps = extractDependencies(dependencies);

		const repoPath = toRepoPath(file);
		const sourceUrl = buildBlobUrl(repoPath);

		let body = cleanBody(content);
		body = ensureSectionsForCodeBlocks(body);
		body = rewriteMarkdownLinks(body, repoPath);
		body = ensureParentIssueSection(body, PHASE_PARENTS[phase]);
		body = ensureSourceSection(body, sourceUrl);

		const inconsistencies = [];
		const mismatchNote = detectFooterPriorityMismatch(body, priority);
		if (mismatchNote) {
			inconsistencies.push(mismatchNote);
			body = addInconsistencyNote(body, mismatchNote);
		}

		for (const field of [
			"Target File",
			"Target Files",
			"Dependencies",
			"Acceptance Criteria",
		]) {
			const regex = new RegExp(`${field}[^\n]*TBD`, "i");
			if (regex.test(body)) {
				inconsistencies.push(`${field} contains TBD.`);
			}
		}

		const labels = ["v0.14.x"];
		if (phase === "validation") {
			if (validationLabelExists) {
				labels.push("validation");
			} else {
				labels.push("testing");
			}
		} else {
			labels.push(PHASE_LABELS[phase]);
		}
		labels.push(categoryLabel(title, basename(file)));
		labels.push(PRIORITY_LABELS[priority]);

		issues.push({
			title,
			body,
			labels: uniqueArray(labels),
			milestone: PHASE_MILESTONES[phase],
			parent_issue: PHASE_PARENTS[phase],
			parent_issue_url: buildIssueUrl(PHASE_PARENTS[phase]),
			phase,
			priority,
			task_id: taskId,
			dependencies: deps,
			estimate_hours: estimateHours,
			source_path: repoPath,
			source_url: sourceUrl,
			child_issue_query: "",
			child_task_ids: [],
			inconsistencies,
			mermaid: { ...MERMAID_PLACEHOLDERS },
		});
	}

	const parentByPhase = new Map(
		issues
			.filter(
				(issue) =>
					issue.task_id?.startsWith("PARENT") || issue.task_id === "V-PARENT",
			)
			.map((issue) => [issue.phase, issue]),
	);
	for (const issue of issues) {
		if (!issue.source_path) continue;
		const parent = parentByPhase.get(issue.phase);
		if (!parent) continue;
		parent.child_task_ids.push(issue.task_id);
	}

	for (const issue of issues) {
		if (issue.child_task_ids?.length) {
			issue.child_task_ids = uniqueArray(issue.child_task_ids);
		}
	}

	return issues;
}

function createIssue(issue) {
	const bodyFile = `/tmp/gh-issue-${Date.now()}-${Math.random().toString(36).slice(2)}.md`;
	return fs
		.writeFile(bodyFile, issue.body)
		.then(() => {
			const args = [
				"issue",
				"create",
				"--repo",
				REPO,
				"--title",
				issue.title,
				"--body-file",
				bodyFile,
			];
			const existingLabels = getExistingLabels();
			for (const label of issue.labels) {
				if (!existingLabels || existingLabels.has(label)) {
					args.push("--label", label);
				}
			}
			const output = execFileSync("gh", args, { encoding: "utf-8" });
			return output.trim();
		})
		.finally(() => fs.unlink(bodyFile).catch(() => {}));
}

async function main() {
	const issues = await buildIssues();
	const json = JSON.stringify(issues);

	if (options.dryRun && !options.create) {
		const preview = issues.slice(0, dryRunLimit);
		console.log(
			JSON.stringify(
				{
					mode: "dry-run",
					total: issues.length,
					previewCount: preview.length,
					preview,
				},
				null,
				2,
			),
		);
		return;
	}

	await fs.mkdir("artifacts", { recursive: true });
	await fs.writeFile(OUTPUT_FILE, json);

	if (options.output) {
		process.stdout.write(json);
		return;
	}

	if (options.create) {
		if (options.dryRun) {
			for (const issue of issues) {
				console.log(`[DRY RUN] ${issue.title}`);
			}
			return;
		}

		for (const issue of issues) {
			const url = await createIssue(issue);
			console.log(`Created ${issue.title}: ${url}`);
			await new Promise((resolve) => setTimeout(resolve, 1000));
		}
	}
}

process.stdout.on("error", (err) => {
	if (err && err.code === "EPIPE") {
		process.exit(0);
	}
});

main().catch((error) => {
	console.error(error.message || error);
	process.exit(1);
});

#!/usr/bin/env node

/**
 * inject-doc-templates.js
 *
 * Automatically injects category-specific animated header and footer templates
 * into documentation files using the capsule-render API.
 *
 * Usage:
 *   node scripts/inject-doc-templates.js docs/YOUR_DOC.md
 *   node scripts/inject-doc-templates.js --all              # Process all docs
 *   node scripts/inject-doc-templates.js --dry-run          # Preview changes
 *   node scripts/inject-doc-templates.js --category user-guide --dry-run
 *   node scripts/inject-doc-templates.js --file docs/ai-interaction-tips.md
 */

import {
	existsSync,
	readdirSync,
	readFileSync,
	statSync,
	writeFileSync,
} from "node:fs";
import { basename, dirname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);
const rootDir = join(__dirname, "..");
const docsDir = join(rootDir, "docs");
const templatesDir = join(docsDir, ".templates");

// Template markers
const HEADER_MARKER = "<!-- AUTO-GENERATED HEADER - DO NOT EDIT -->";
const FOOTER_MARKER = "<!-- AUTO-GENERATED FOOTER - DO NOT EDIT -->";
const HEADER_END_MARKER = "<!-- END AUTO-GENERATED HEADER -->";
const FOOTER_END_MARKER = "<!-- END AUTO-GENERATED FOOTER -->";

// Category detection patterns
const CATEGORY_PATTERNS = {
	"user-guide": [
		/AI_INTERACTION_TIPS/i,
		/PROMPTING_HIERARCHY/i,
		/AGENT_RELATIVE_CALLS/i,
		/AGENT_COORDINATION/i,
		/BEST_PRACTICES/i,
	],
	developer: [
		/CONTRIBUTING/i,
		/CLEAN_CODE/i,
		/ERROR_HANDLING/i,
		/BRIDGE_CONNECTORS/i,
		/TECHNICAL_IMPROVEMENTS/i,
		/TESTING/i,
	],
	reference: [
		/REFERENCES/i,
		/SERENA_STRATEGIES/i,
		/CONTEXT_AWARE_GUIDANCE/i,
		/DESIGN_MODULE_STATUS/i,
		/design-module-status/i,
		/METHODOLOGY/i,
		/MIGRATION_STRATEGY/i,
	],
	specialized: [
		/visualization/i,
		/export-formats/i,
		/maintaining-models/i,
		/sprint-planning/i,
		/DIAGRAM_GENERATION/i,
		/AGILE_WORKFLOW/i,
		/MERMAID/i,
	],
};

/**
 * Detect category based on filename patterns
 */
function detectCategory(filePath) {
	const filename = basename(filePath);

	// Check specialized patterns first (most specific)
	if (CATEGORY_PATTERNS.specialized.some((p) => p.test(filename))) {
		return "specialized";
	}

	// Then developer patterns
	if (CATEGORY_PATTERNS.developer.some((p) => p.test(filename))) {
		return "developer";
	}

	// Then user guide patterns
	if (CATEGORY_PATTERNS["user-guide"].some((p) => p.test(filename))) {
		return "user-guide";
	}

	// Then reference patterns
	if (CATEGORY_PATTERNS.reference.some((p) => p.test(filename))) {
		return "reference";
	}

	// Default fallback
	return "reference";
}

/**
 * Load template content for specific category
 */
function loadTemplate(category, type, _docPath) {
	const templateName = `${type}-${category}.html`;
	const templatePath = join(templatesDir, templateName);

	if (!existsSync(templatePath)) {
		throw new Error(`Template not found: ${templateName}`);
	}

	const content = readFileSync(templatePath, "utf-8");
	return content;
}

/**
 * Check if file already has templates
 */
function hasTemplate(content, marker) {
	return content.includes(marker);
}

/**
 * Inject header template with category detection
 */
function injectHeader(content, docPath, category = null) {
	const detectedCategory = category || detectCategory(docPath);
	const header = loadTemplate(detectedCategory, "header", docPath);

	// Template already contains markers, no need to wrap
	if (hasTemplate(content, HEADER_MARKER)) {
		// Replace existing header (including markers)
		const regex = new RegExp(
			`${HEADER_MARKER}[\\s\\S]*?${HEADER_END_MARKER}`,
			"g",
		);
		return content.replace(regex, header.trim());
	} else {
		// Add header at the beginning
		return `${header}\n\n${content}`;
	}
}

/**
 * Inject footer template with category detection
 */
function injectFooter(content, docPath, category = null) {
	const detectedCategory = category || detectCategory(docPath);
	const footer = loadTemplate(detectedCategory, "footer", docPath);

	// Template already contains markers, no need to wrap
	if (hasTemplate(content, FOOTER_MARKER)) {
		// Replace existing footer (including markers)
		const regex = new RegExp(
			`${FOOTER_MARKER}[\\s\\S]*?${FOOTER_END_MARKER}`,
			"g",
		);
		return content.replace(regex, footer.trim());
	} else {
		// Add footer at the end
		return `${content}\n\n${footer}`;
	}
}

/**
 * Process a single file
 */
function processFile(
	filePath,
	dryRun = false,
	category = null,
	verbose = false,
) {
	const relPath = relative(rootDir, filePath);
	const detectedCategory = category || detectCategory(filePath);

	console.log(`Processing: ${relPath} [${detectedCategory}]`);

	const content = readFileSync(filePath, "utf-8");
	let updated = content;

	// Inject header and footer with category
	updated = injectHeader(updated, filePath, category);
	updated = injectFooter(updated, filePath, category);

	if (content === updated) {
		console.log("  ✓ No changes needed");
		return false;
	}

	if (verbose) {
		const headerDiff =
			updated.includes(HEADER_MARKER) && !content.includes(HEADER_MARKER)
				? " [+header]"
				: " [~header]";
		const footerDiff =
			updated.includes(FOOTER_MARKER) && !content.includes(FOOTER_MARKER)
				? " [+footer]"
				: " [~footer]";
		console.log(`  ℹ Changes:${headerDiff}${footerDiff}`);
	}

	if (dryRun) {
		console.log("  ℹ Would update (dry-run mode)");
		return false;
	}

	writeFileSync(filePath, updated, "utf-8");
	console.log("  ✓ Updated");
	return true;
}

/**
 * Get all markdown files in docs directory
 */
function getAllDocsFiles(categoryFilter = null) {
	const files = [];

	function walk(dir) {
		const items = readdirSync(dir);

		for (const item of items) {
			const fullPath = join(dir, item);
			const stat = statSync(fullPath);

			if (stat.isDirectory()) {
				// Skip templates directory
				if (item !== ".templates") {
					walk(fullPath);
				}
			} else if (item.endsWith(".md") && item !== "README.md") {
				// Skip README files
				if (categoryFilter) {
					const fileCategory = detectCategory(fullPath);
					if (fileCategory === categoryFilter) {
						files.push(fullPath);
					}
				} else {
					files.push(fullPath);
				}
			}
		}
	}

	walk(docsDir);
	return files;
}

/**
 * Parse command-line arguments
 */
function parseArgs() {
	const args = process.argv.slice(2);
	const options = {
		dryRun: false,
		processAll: false,
		category: null,
		file: null,
		verbose: false,
	};

	for (let i = 0; i < args.length; i++) {
		const arg = args[i];

		if (arg === "--dry-run") {
			options.dryRun = true;
		} else if (arg === "--all") {
			options.processAll = true;
		} else if (arg === "--category") {
			options.category = args[++i];
		} else if (arg === "--file") {
			options.file = args[++i];
		} else if (arg === "--verbose" || arg === "-v") {
			options.verbose = true;
		} else if (!arg.startsWith("--")) {
			// Treat as file path
			options.file = arg;
		}
	}

	return options;
}

/**
 * Display usage information
 */
function showUsage() {
	console.log("Usage: node scripts/inject-doc-templates.js [options]");
	console.log("\nOptions:");
	console.log("  --all                   Process all documentation files");
	console.log("  --file <path>           Process specific markdown file");
	console.log(
		"  --category <name>       Filter by category (user-guide, developer, reference, specialized)",
	);
	console.log("  --dry-run               Preview changes without writing");
	console.log("  --verbose, -v           Show detailed changes");
	console.log("\nExamples:");
	console.log(
		"  node scripts/inject-doc-templates.js docs/ai-interaction-tips.md",
	);
	console.log("  node scripts/inject-doc-templates.js --all");
	console.log("  node scripts/inject-doc-templates.js --all --dry-run");
	console.log(
		"  node scripts/inject-doc-templates.js --category user-guide --dry-run",
	);
	console.log(
		"  node scripts/inject-doc-templates.js --file docs/technical-improvements.md -v",
	);
	console.log("\nCategories:");
	console.log("  user-guide    Purple/Pink - User-facing documentation");
	console.log("  developer     Green/Cyan - Developer and contributor docs");
	console.log("  reference     Orange/Pink - Reference and research docs");
	console.log("  specialized   Cyan/Green - Tool-specific documentation");
}

/**
 * Main execution
 */
function main() {
	const options = parseArgs();

	if (!options.processAll && !options.file) {
		showUsage();
		process.exit(1);
	}

	console.log("🎨 Documentation Template Injector\n");

	if (options.dryRun) {
		console.log("⚠️  DRY RUN MODE - No files will be modified\n");
	}

	if (options.category) {
		console.log(`📁 Filtering by category: ${options.category}\n`);
	}

	let filesProcessed = 0;
	let filesUpdated = 0;
	const categoryCounts = {
		"user-guide": 0,
		developer: 0,
		reference: 0,
		specialized: 0,
	};

	if (options.processAll) {
		const files = getAllDocsFiles(options.category);
		console.log(`Found ${files.length} documentation files\n`);

		for (const file of files) {
			filesProcessed++;
			const category = detectCategory(file);
			categoryCounts[category]++;

			if (
				processFile(file, options.dryRun, options.category, options.verbose)
			) {
				filesUpdated++;
			}
		}
	} else if (options.file) {
		const filePath = options.file.startsWith("/")
			? options.file
			: join(rootDir, options.file);

		if (!existsSync(filePath)) {
			console.error(`❌ File not found: ${filePath}`);
			process.exit(1);
		}

		filesProcessed = 1;
		const category = detectCategory(filePath);
		categoryCounts[category]++;

		if (
			processFile(filePath, options.dryRun, options.category, options.verbose)
		) {
			filesUpdated = 1;
		}
	}

	console.log(
		`\n✨ Done! Processed ${filesProcessed} files, updated ${filesUpdated}`,
	);

	if (options.verbose && options.processAll) {
		console.log("\n📊 Category Distribution:");
		for (const [cat, count] of Object.entries(categoryCounts)) {
			if (count > 0) {
				console.log(`  ${cat}: ${count} files`);
			}
		}
	}

	if (options.dryRun && filesUpdated > 0) {
		console.log("\nRun without --dry-run to apply changes");
	}
}

main();

#!/usr/bin/env node

/**
 * Link Sub-Issues to Parent Epics
 *
 * This script links all sub-issues to their parent epics using GitHub's GraphQL API.
 * Should be run AFTER create-all-issues.js has created all issues.
 *
 * Usage:
 *   node scripts/link-sub-issues.js [--dry-run]
 *
 * Prerequisites:
 *   - All issues must be created on GitHub
 *   - artifacts/issue-number-mapping.json must exist
 *   - GitHub CLI (gh) must be installed and authenticated
 */

import { execSync } from "node:child_process";
import { readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

const dryRun = process.argv.includes("--dry-run");

/**
 * Get the internal GitHub ID for an issue number
 */
function getIssueId(issueNumber) {
	try {
		const result = execSync(
			`gh api graphql -f query='query { repository(owner: "Anselmoo", name: "mcp-ai-agent-guidelines") { issue(number: ${issueNumber}) { id } } }'`,
			{ encoding: "utf-8" },
		);
		const data = JSON.parse(result);
		return data.data?.repository?.issue?.id;
	} catch (error) {
		console.error(
			`Failed to get ID for issue #${issueNumber}: ${error.message}`,
		);
		return null;
	}
}

/**
 * Link a sub-issue to its parent using GraphQL mutation
 */
async function linkSubIssue(parentNumber, subIssueNumber) {
	const parentId = getIssueId(parentNumber);
	if (!parentId) {
		throw new Error(`Could not get ID for parent issue #${parentNumber}`);
	}

	const subIssueId = getIssueId(subIssueNumber);
	if (!subIssueId) {
		throw new Error(`Could not get ID for sub-issue #${subIssueNumber}`);
	}

	const mutation = `mutation {
		addSubIssue(input: {
			issueId: "${parentId}"
			subIssueId: "${subIssueId}"
		}) {
			issue {
				number
			}
		}
	}`;

	if (dryRun) {
		console.log(
			`   [DRY-RUN] Would link #${subIssueNumber} to parent #${parentNumber}`,
		);
		return;
	}

	try {
		execSync(`gh api graphql -f query='${mutation}'`, {
			encoding: "utf-8",
			stdio: "pipe",
		});
		console.log(`   ✅ Linked #${subIssueNumber} to parent #${parentNumber}`);
	} catch (error) {
		console.error(`   ❌ Failed to link #${subIssueNumber}: ${error.message}`);
		throw error;
	}

	// Rate limit - GitHub API rate limit is 5000/hour, so 300ms should be safe
	await new Promise((resolve) => setTimeout(resolve, 300));
}

/**
 * Get parent issue number from a sub-issue file
 */
function getParentNumber(filename, mapping) {
	// Extract parent prefix (e.g., "p1" from "p1-001-sub-...")
	const match = filename.match(/^p(\d+)-/);
	if (!match) {
		throw new Error(`Invalid sub-issue filename: ${filename}`);
	}

	const phaseNum = match[1];

	// Find the matching parent file
	const parentFile = Object.keys(mapping.parents).find((f) =>
		f.startsWith(`00${phaseNum}-parent-`),
	);

	if (!parentFile) {
		throw new Error(`Could not find parent file for phase ${phaseNum}`);
	}

	return mapping.parents[parentFile];
}

/**
 * Main execution
 */
async function main() {
	console.log("🔗 Linking Sub-Issues to Parent Epics\n");

	if (dryRun) {
		console.log(
			"ℹ️  Running in DRY-RUN mode - no actual changes will be made\n",
		);
	}

	// Load the mapping file
	const mappingPath = path.join(
		__dirname,
		"..",
		"artifacts",
		"issue-number-mapping.json",
	);
	const mapping = JSON.parse(readFileSync(mappingPath, "utf-8"));

	console.log(
		`📊 Total sub-issues to link: ${Object.keys(mapping.subIssues).length}\n`,
	);

	// Group sub-issues by parent
	const linksByParent = new Map();

	for (const [filename, subIssueNumber] of Object.entries(mapping.subIssues)) {
		const parentNumber = getParentNumber(filename, mapping);

		if (!linksByParent.has(parentNumber)) {
			linksByParent.set(parentNumber, []);
		}

		linksByParent.get(parentNumber).push({ filename, subIssueNumber });
	}

	// Link each parent's sub-issues
	let totalLinked = 0;
	let totalFailed = 0;

	for (const [parentNumber, subIssues] of linksByParent) {
		console.log(`\n📌 Parent Issue #${parentNumber}:`);
		console.log(`   Linking ${subIssues.length} sub-issues...\n`);

		for (const { filename, subIssueNumber } of subIssues) {
			try {
				await linkSubIssue(parentNumber, subIssueNumber);
				totalLinked++;
			} catch (error) {
				console.error(`   ⚠️  Failed: ${filename} → ${error.message}`);
				totalFailed++;
			}
		}
	}

	// Summary
	console.log("\n" + "=".repeat(60));
	console.log("📊 Linking Summary:");
	console.log("=".repeat(60));
	console.log(`✅ Successfully linked: ${totalLinked}`);
	if (totalFailed > 0) {
		console.log(`❌ Failed to link: ${totalFailed}`);
	}
	console.log("=".repeat(60));

	if (dryRun) {
		console.log(
			"\nℹ️  This was a dry-run. To actually link issues, run without --dry-run",
		);
	} else {
		console.log("\n✨ All sub-issues have been linked to their parent epics!");
	}
}

// Run the script
main().catch((error) => {
	console.error("\n❌ Fatal error:", error.message);
	process.exit(1);
});

#!/usr/bin/env node

/**
 * Documentation Linter
 *
 * Validates documentation files for consistency in:
 * - File naming conventions
 * - Header/Footer structure
 * - Table of Contents format
 * - SVG text visibility in dark mode
 */

import { readdirSync, readFileSync, statSync } from "node:fs";
import { basename, extname, join, relative } from "node:path";
import { fileURLToPath } from "node:url";

const __filename = fileURLToPath(import.meta.url);
const __dirname = fileURLToPath(new URL(".", import.meta.url));

// Configuration
const DOCS_DIR = join(__dirname, "..", "docs");
// Parse command-line arguments
const WARN_ONLY = process.argv.includes("--warn-only");
const NAMING_ONLY = process.argv.includes("--naming-only");
// All documentation files should use kebab-case (lowercase, dash-separated)
// This standardizes naming across all doc directories for consistency
const NAMING_CONVENTION = "kebab-case";

// Issue tracking
const issues = {
	naming: [],
	headers: [],
	footers: [],
	toc: [],
	svg: [],
};

/**
 * Check if a filename matches the kebab-case convention
 */
function checkNamingConvention(filepath) {
	const filename = basename(filepath, extname(filepath));

	// README.md is always valid
	if (filename === "README") return true;

	// kebab-case: lowercase letters, numbers, and dashes
	return /^[a-z][a-z0-9-]*$/.test(filename);
}

/**
 * Get expected convention description for error messages
 */
function getExpectedConvention() {
	return NAMING_CONVENTION;
}

/**
 * Check markdown file for header/footer structure
 */
function checkMarkdownStructure(filepath, content) {
	const lines = content.split("\n");

	// Check for header markers
	const hasHeaderStart = lines.some((line) =>
		line.includes("<!-- HEADER:START -->"),
	);
	const hasHeaderEnd = lines.some((line) =>
		line.includes("<!-- HEADER:END -->"),
	);
	const hasHeaderImage = lines.some((line) =>
		/!\[Header\]\(.+\.svg\)/.test(line),
	);

	// Check for footer markers
	const hasFooterStart = lines.some((line) =>
		line.includes("<!-- FOOTER:START -->"),
	);
	const hasFooterEnd = lines.some((line) =>
		line.includes("<!-- FOOTER:END -->"),
	);
	const hasFooterImage = lines.some((line) =>
		/!\[Footer\]\(.+\.svg\)/.test(line),
	);

	// Report missing headers
	if (!hasHeaderStart || !hasHeaderEnd || !hasHeaderImage) {
		issues.headers.push({
			file: relative(DOCS_DIR, filepath),
			issue: "Missing or incomplete header structure",
			details: {
				hasStart: hasHeaderStart,
				hasEnd: hasHeaderEnd,
				hasImage: hasHeaderImage,
			},
		});
	}

	// Report missing footers (optional but should be consistent if present)
	const hasAnyFooter = hasFooterStart || hasFooterEnd || hasFooterImage;
	if (hasAnyFooter && (!hasFooterStart || !hasFooterEnd || !hasFooterImage)) {
		issues.footers.push({
			file: relative(DOCS_DIR, filepath),
			issue: "Incomplete footer structure",
			details: {
				hasStart: hasFooterStart,
				hasEnd: hasFooterEnd,
				hasImage: hasFooterImage,
			},
		});
	}

	// Check for proper heading hierarchy
	const headings = lines.filter((line) => line.startsWith("#"));
	if (headings.length > 0) {
		const firstHeading = headings[0];
		if (!firstHeading.startsWith("# ")) {
			issues.toc.push({
				file: relative(DOCS_DIR, filepath),
				issue: "First heading should be H1 (#)",
				details: { firstHeading },
			});
		}
	}
}

/**
 * Check SVG file for dark mode text visibility issues
 */
function checkSVGVisibility(filepath, content) {
	const relativePath = relative(DOCS_DIR, filepath);

	// Check for text elements
	const hasTextElements = /<text/.test(content);
	if (!hasTextElements) return; // No text to check

	// Check for dark mode styles
	const hasDarkModeQuery = /@media \(prefers-color-scheme: dark\)/.test(
		content,
	);

	// Extract text fill colors in dark mode
	const darkModeMatch = content.match(
		/@media \(prefers-color-scheme: dark\)\s*\{([^}]+)\}/s,
	);
	if (darkModeMatch) {
		const darkModeStyles = darkModeMatch[1];

		// Check if text has explicit fill colors
		const hasTextFill = /\.text-[a-z]+\s*\{\s*fill:\s*#[a-fA-F0-9]+/.test(
			darkModeStyles,
		);

		// Check for potentially invisible colors (dark colors)
		const hasDarkFill = /#[0-2][0-9a-fA-F]{5}/.test(darkModeStyles);

		if (!hasTextFill) {
			issues.svg.push({
				file: relativePath,
				issue: "No explicit text fill color in dark mode",
				severity: "warning",
			});
		}

		if (hasDarkFill) {
			issues.svg.push({
				file: relativePath,
				issue: "Potentially invisible dark text color in dark mode",
				severity: "error",
			});
		}
	} else if (hasDarkModeQuery) {
		issues.svg.push({
			file: relativePath,
			issue: "Dark mode query exists but styles not properly structured",
			severity: "warning",
		});
	}

	// Check for hardcoded dark fill attributes on text elements
	const textElements = content.match(/<text[^>]*>/g) || [];
	for (const element of textElements) {
		if (/fill=["']#[0-2][0-9a-fA-F]{5}["']/.test(element)) {
			issues.svg.push({
				file: relativePath,
				issue: "Text element has hardcoded dark fill color",
				severity: "error",
				element: element.substring(0, 100),
			});
		}
	}
}

/**
 * Recursively scan directory for files
 */
function scanDirectory(dir, fileHandler) {
	const entries = readdirSync(dir);

	for (const entry of entries) {
		const fullPath = join(dir, entry);
		const stat = statSync(fullPath);

		if (stat.isDirectory()) {
			// Skip node_modules, .git, etc.
			if (!entry.startsWith(".") && entry !== "node_modules") {
				scanDirectory(fullPath, fileHandler);
			}
		} else if (stat.isFile()) {
			fileHandler(fullPath);
		}
	}
}

/**
 * Main linting function
 */
function lintDocumentation() {
	console.log("🔍 Linting documentation files...\n");

	if (NAMING_ONLY) {
		console.log("📝 Running naming convention check only\n");
	}

	scanDirectory(DOCS_DIR, (filepath) => {
		const ext = extname(filepath);

		// Check markdown files
		if (ext === ".md") {
			const isValidNaming = checkNamingConvention(filepath);

			if (!isValidNaming) {
				issues.naming.push({
					file: relative(DOCS_DIR, filepath),
					expected: getExpectedConvention(),
					actual: basename(filepath),
				});
			}

			// Skip structure checks if naming-only mode
			if (!NAMING_ONLY) {
				const content = readFileSync(filepath, "utf-8");
				checkMarkdownStructure(filepath, content);
			}
			return;
		}

		// Check SVG files
		if (ext === ".svg") {
			// Always check naming convention
			const isValidNaming = checkNamingConvention(filepath);
			if (!isValidNaming) {
				issues.naming.push({
					file: relative(DOCS_DIR, filepath),
					expected: getExpectedConvention(),
					actual: basename(filepath),
				});
			}
			// Skip visibility checks if naming-only mode
			if (!NAMING_ONLY) {
				const content = readFileSync(filepath, "utf-8");
				checkSVGVisibility(filepath, content);
			}
			return;
		}
	});

	// Print results
	printResults();
}

/**
 * Print linting results
 */
function printResults() {
	let totalIssues = 0;

	console.log("📊 Linting Results\n");
	console.log("=".repeat(80));
	console.log();

	// Naming convention issues
	if (issues.naming.length > 0) {
		console.log(`❌ Naming Convention Issues (${issues.naming.length})`);
		console.log("-".repeat(80));
		for (const issue of issues.naming) {
			console.log(`  File: ${issue.file}`);
			console.log(`  Expected: ${issue.expected}`);
			console.log(`  Actual: ${issue.actual}`);
			console.log();
		}
		totalIssues += issues.naming.length;
	} else {
