	below90.slice(0, 20).forEach((f, i) => {
		console.log(`${i + 1}. ${f.file} — ${f.pct}% (${f.hit}/${f.total})`);
	});
}

#!/usr/bin/env node
/**
 * Parse Model Documentation - HTML Parsing Utilities
 *
 * Reusable utilities for parsing GitHub Copilot model documentation pages.
 * Used by sync-models.js and can be imported for testing or other scripts.
 *
 * Data Sources:
 * - Model Comparison: https://docs.github.com/en/copilot/reference/ai-models/model-comparison
 * - Supported Models: https://docs.github.com/en/copilot/reference/ai-models/supported-models
 *
 * Usage:
 *   import { parseModelComparison, normalizeTaskArea } from './parse-model-docs.js';
 */

import * as cheerio from "cheerio";

/**
 * Parse the model comparison table from HTML
 *
 * @param {string} html - Raw HTML content from GitHub Copilot docs
 * @returns {Array<Object>} Parsed model data with name, taskArea, excelsAt, etc.
 */
export function parseModelComparison(html) {
	const $ = cheerio.load(html);
	const models = [];

	// Find the main comparison table
	$("table").each((_, table) => {
		const $table = $(table);
		const headers = $table
			.find("th")
			.map((_, th) => $(th).text().trim())
			.get();

		// Look for the model comparison table
		if (headers.includes("Model") && headers.includes("Task area")) {
			$table.find("tbody tr").each((_, row) => {
				const $row = $(row);
				const cells = $row
					.find("td")
					.map((_, td) => $(td).text().trim())
					.get();

				if (cells.length >= 3) {
					const modelName = cells[0];
					const taskArea = cells[1];
					const excelsAt = cells[2];
					const additionalCapabilities = cells[3] || "";

					// Extract documentation URL
					const docLink = $row.find("a").last().attr("href") || "";
					const documentationUrl = docLink.startsWith("http")
						? docLink
						: docLink.startsWith("/")
							? `https://docs.github.com${docLink}`
							: "";

					models.push({
						name: modelName,
						taskArea: normalizeTaskArea(taskArea),
						excelsAt,
						additionalCapabilities,
						documentationUrl,
					});
				}
			});
		}
	});

	return models;
}

/**
 * Normalize task area text to match our schema values
 *
 * @param {string} taskAreaText - Raw task area text from documentation
 * @returns {string} Normalized task area: "general-purpose" | "deep-reasoning" | "fast-simple" | "visual"
 */
export function normalizeTaskArea(taskAreaText) {
	const normalized = taskAreaText.toLowerCase();
	if (
		normalized.includes("general-purpose") ||
		normalized.includes("general purpose")
	) {
		return "general-purpose";
	}
	if (
		normalized.includes("deep reasoning") ||
		normalized.includes("debugging")
	) {
		return "deep-reasoning";
	}
	if (
		normalized.includes("fast") ||
		normalized.includes("simple") ||
		normalized.includes("repetitive")
	) {
		return "fast-simple";
	}
	if (normalized.includes("visual") || normalized.includes("diagram")) {
		return "visual";
	}
	return "general-purpose"; // Default
}

/**
 * Infer provider from model name
 *
 * @param {string} modelName - Model name to analyze
 * @returns {string} Inferred provider name
 */
export function inferProvider(modelName) {
	const name = modelName.toLowerCase();
	// Only match known OpenAI "o-series" prefixes (e.g., o1, o2, o3, o4, o5, oai)
	if (
		name.startsWith("gpt") ||
		name.startsWith("o1") ||
		name.startsWith("o2") ||
		name.startsWith("o3") ||
		name.startsWith("o4") ||
		name.startsWith("o5") ||
		name.startsWith("oai")
	)
		return "OpenAI";
	if (name.startsWith("claude")) return "Anthropic";
	if (name.startsWith("gemini")) return "Google";
	if (name.startsWith("grok")) return "xAI";
	if (name.startsWith("qwen")) return "Alibaba";
	if (name.startsWith("raptor")) return "Meta";
	return "Unknown";
}

/**
 * Infer supported modes from capabilities and model name
 *
 * @param {string} capabilities - Additional capabilities text
 * @param {string} modelName - Model name
 * @returns {Object} Object with boolean flags for each mode
 */
export function inferModes(capabilities, modelName) {
	const capLower = capabilities.toLowerCase();
	const nameLower = modelName.toLowerCase();

	return {
		agent:
			capLower.includes("agent") ||
			nameLower.includes("codex") ||
			nameLower.includes("sonnet"),
		reasoning:
			capLower.includes("reasoning") ||
			nameLower.includes("opus") ||
			nameLower.includes("qwen"),
		vision: capLower.includes("vision") || capLower.includes("multimodal"),
		chat: true, // Most models support chat
		edit: true, // Most models support editing
		completions:
			!nameLower.includes("opus") &&
			!nameLower.includes("gpt-5.1") &&
			!nameLower.includes("gpt-5 "),
	};
}

/**
 * Infer multiplier based on model characteristics
 *
 * @param {string} modelName - Model name
 * @param {string} taskArea - Task area category
 * @returns {number} Premium request multiplier (e.g., 0.5, 1.0, 1.5, 2.0)
 */
export function inferMultiplier(modelName, taskArea) {
	const nameLower = modelName.toLowerCase();

	// Premium models (2.0x)
	if (nameLower.includes("opus") || nameLower.includes("gpt-5.1")) {
		return 2.0;
	}

	// Mid-tier reasoning models (1.5x)
	if (
		nameLower.includes("gpt-5 ") &&
		!nameLower.includes("mini") &&
		!nameLower.includes("codex")
	) {
		return 1.5;
	}

	// Budget models (0.5x)
	if (
		nameLower.includes("haiku") ||
		nameLower.includes("mini") ||
		nameLower.includes("flash") ||
		taskArea === "fast-simple"
	) {
		return 0.5;
	}

	// Complimentary models (0.0x)
	if (nameLower.includes("grok")) {
		return 0.0;
	}

	// Default (1.0x)
	return 1.0;
}

/**
 * Infer status from model name and characteristics
 *
 * @param {string} modelName - Model name
 * @param {string} _capabilities - Additional capabilities (unused but kept for API consistency)
 * @returns {string} Status: "ga" | "preview" | "beta" | "retired"
 */
export function inferStatus(modelName, _capabilities) {
	const nameLower = modelName.toLowerCase();

	if (nameLower.includes("raptor") || nameLower.includes("grok")) {
		return "preview";
	}

	return "ga"; // Generally available by default
}

/**
 * Infer pricing tier from task area and multiplier
 *
 * @param {string} _taskArea - Task area (unused but kept for API consistency)
 * @param {number} multiplier - Premium request multiplier
 * @returns {string} Pricing tier: "premium" | "mid-tier" | "budget"
 */
export function inferPricingTier(_taskArea, multiplier) {
	if (multiplier >= 1.5) return "premium";
	if (multiplier <= 0.5) return "budget";
	return "mid-tier";
}

/**
 * Fetch a page with retry logic
 *
 * @param {string} url - URL to fetch
 * @param {number} maxRetries - Maximum number of retry attempts (default: 3)
 * @returns {Promise<string>} HTML content of the page
 * @throws {Error} If all retries fail
 */
export async function fetchWithRetry(url, maxRetries = 3) {
	for (let i = 0; i < maxRetries; i++) {
		try {
			console.log(`📥 Fetching: ${url} (attempt ${i + 1}/${maxRetries})`);
			const response = await fetch(url);

			if (!response.ok) {
				throw new Error(`HTTP ${response.status}: ${response.statusText}`);
			}

			return await response.text();
		} catch (error) {
			if (i === maxRetries - 1) {
				throw error;
			}

			const delay = 2 ** i * 1000; // 1s, 2s, 4s
			console.log(`⚠️  Retry in ${delay}ms...`);
			await new Promise((resolve) => setTimeout(resolve, delay));
		}
	}
}

/**
 * Documentation URLs for GitHub Copilot models
 */
export const DOCS_URLS = {
	comparison:
		"https://docs.github.com/en/copilot/reference/ai-models/model-comparison",
	supported:
		"https://docs.github.com/en/copilot/reference/ai-models/supported-models",
};

#!/usr/bin/env node

/**
 * Pre-Calculate GitHub Issue Numbers
 *
 * Queries GitHub for the latest issue number, then pre-calculates
 * all issue numbers for parent and sub-issues before creation.
 *
 * This enables updating all markdown files with correct issue numbers
 * before creating the issues, so all links work immediately.
 *
 * Usage:
 *   node scripts/pre-calculate-issue-numbers.js
 */

import { execSync } from "node:child_process";
import { promises as fs } from "node:fs";

const REPO = "Anselmoo/mcp-ai-agent-guidelines";
const ISSUES_DRAFT_DIR = "plan-v0.13.x/issues-draft";

// Parent issue files in creation order
const PARENT_FILES = [
	"001-parent-phase1-discoverability.md",
	"002-parent-phase2-domain-extraction.md",
	"003-parent-phase3-broken-tools.md",
	"004-parent-phase4-speckit-integration.md",
];

/**
 * Get latest issue number from GitHub
 */
function getLatestIssueNumber() {
	try {
		const output = execSync(
			`gh api 'repos/${REPO}/issues?state=all&per_page=1' | jq '.[0].number'`,
			{ encoding: "utf-8", shell: "/bin/bash" },
		);
		const latestNumber = Number.parseInt(output.trim(), 10);
		console.log(`📊 Latest issue number in repo: #${latestNumber}`);
		return latestNumber;
	} catch (error) {
		console.error("❌ Failed to query GitHub API:", error.message);
		process.exit(1);
	}
}

/**
 * Get all sub-issue files in order
 */
async function getSubIssueFiles() {
	const files = await fs.readdir(ISSUES_DRAFT_DIR);
	return files.filter((f) => f.match(/^p\d+-\d+-sub-.+\.md$/)).sort();
}

/**
 * Extract task ID from filename or content
 */
function extractTaskId(filename) {
	const match = filename.match(/^(p\d+-\d+)-sub-/);
	return match ? match[1].toUpperCase() : null;
}

/**
 * Pre-calculate all issue numbers
 */
async function preCalculateNumbers() {
	console.log("🔢 Pre-Calculating Issue Numbers\n");

	// Get latest issue number
	const latestNumber = getLatestIssueNumber();
	let nextNumber = latestNumber + 1;

	// Calculate parent issue numbers
	const parentMapping = {};
	console.log("\n📋 Parent Issues:");
	for (const filename of PARENT_FILES) {
		parentMapping[filename] = nextNumber;
		console.log(`   ${filename} → #${nextNumber}`);
		nextNumber++;
	}

	// Calculate sub-issue numbers
	const subIssueFiles = await getSubIssueFiles();
	const subIssueMapping = {};
	const taskIdMapping = {};

	console.log(`\n📋 Sub-Issues (${subIssueFiles.length} total):`);
	for (const filename of subIssueFiles) {
		subIssueMapping[filename] = nextNumber;

		// Also map by task ID (e.g., P1-001 → issue number)
		const taskId = extractTaskId(filename);
		if (taskId) {
			taskIdMapping[taskId] = nextNumber;
		}

		console.log(`   ${filename} → #${nextNumber}`);
		nextNumber++;
	}

	// Create comprehensive mapping
	const mapping = {
		calculatedAt: new Date().toISOString(),
		latestIssueNumber: latestNumber,
		nextIssueNumber: nextNumber,
		totalIssues: PARENT_FILES.length + subIssueFiles.length,
		parents: parentMapping,
		subIssues: subIssueMapping,
		taskIds: taskIdMapping,
	};

	// Save mapping
	await fs.mkdir("artifacts", { recursive: true });
	const mappingFile = "artifacts/issue-number-mapping.json";
	await fs.writeFile(mappingFile, JSON.stringify(mapping, null, 2));

	console.log(`\n✅ Saved mapping to ${mappingFile}`);
	console.log(`\n📊 Summary:`);
	console.log(`   Latest issue: #${latestNumber}`);
	console.log(`   First parent: #${latestNumber + 1}`);
	console.log(`   Last parent: #${latestNumber + 4}`);
	console.log(`   First sub-issue: #${latestNumber + 5}`);
	console.log(`   Last sub-issue: #${nextNumber - 1}`);
	console.log(`   Total to create: ${mapping.totalIssues}`);

	console.log("\n🎯 Parent Epic Issues (will be created):");
	for (const [filename, issueNum] of Object.entries(parentMapping)) {
		console.log(`   #${issueNum} - ${filename}`);
	}

	console.log("\n📝 Next steps:");
	console.log("   1. Review mapping: cat artifacts/issue-number-mapping.json");
	console.log("   2. Update files: node scripts/update-issue-numbers.js");
	console.log("   3. Review changes: git diff plan-v0.13.x/issues-draft/");
	console.log("   4. Create issues: node scripts/create-all-issues.js");

	return mapping;
}

preCalculateNumbers().catch(console.error);

#!/usr/bin/env node
// Simple utility: parse coverage/lcov.info and print a table of file coverage for files under src/
const fs = require("node:fs");
const path = require("node:path");

const lcovPath = path.resolve(process.cwd(), "coverage", "lcov.info");
if (!fs.existsSync(lcovPath)) {
	console.error(
		"coverage/lcov.info not found. Run the coverage command first (npm run test:coverage:vitest)",
	);
	process.exit(1);
}

const lcov = fs.readFileSync(lcovPath, "utf8");
const blocks = lcov.split("\n\n");

const entries = [];
for (const block of blocks) {
	const lines = block.split("\n");
	const fileLine = lines.find((l) => l.startsWith("SF:"));
	if (!fileLine) continue;
	const file = fileLine.slice(3);
	// Only include src/ files (handle absolute, relative and windows paths)
	if (!/(^|[\\/])src([\\/]|$)/.test(file)) continue;

	const lhLine = lines.find((l) => l.startsWith("LH:"));
	const lfLine = lines.find((l) => l.startsWith("LF:"));
	let percent = 0;
	let executed = 0;
	let total = 0;
	if (lhLine && lfLine) {
		executed = parseInt(lhLine.slice(3), 10);
		total = parseInt(lfLine.slice(3), 10);
		percent = total === 0 ? 100 : Math.round((executed / total) * 10000) / 100;
	} else {
		// fallback: count DA entries
		const da = lines.filter((l) => l.startsWith("DA:"));
		for (const d of da) {
			const parts = d.slice(3).split(",");
			const hits = parseInt(parts[1] || "0", 10);
			total++;
			if (hits > 0) executed++;
		}
		percent = total === 0 ? 100 : Math.round((executed / total) * 10000) / 100;
	}

	entries.push({
		file: path.relative(process.cwd(), file),
		percent,
		executed,
		total,
	});
}

entries.sort((a, b) => a.percent - b.percent || a.file.localeCompare(b.file));

const outLines = [];
outLines.push("Coverage by file (src/ only)");
outLines.push("=".repeat(80));
const header = ["%".padEnd(6), "Executed/Total".padEnd(16), "File"];
outLines.push(header.join(" | "));
outLines.push("-".repeat(80));
for (const e of entries) {
	const pct = String(e.percent).padEnd(6);
	const ratio = `${e.executed}/${e.total}`.padEnd(16);
	outLines.push(`${pct} | ${ratio} | ${e.file}`);
}

const out = outLines.join("\n");
console.log(out);

// write to coverage/file-coverage.log
const outPath = path.resolve(process.cwd(), "coverage", "file-coverage.log");
fs.writeFileSync(outPath, out, "utf8");
console.log(`\nWrote ${outPath}`);

#!/usr/bin/env node
/**
 * Sync AI Models from GitHub Copilot Documentation
 *
 * Fetches the latest model information from GitHub Copilot documentation
 * and updates models.yaml with any changes.
 *
 * Data Sources:
 * - Model Comparison: https://docs.github.com/en/copilot/reference/ai-models/model-comparison
 * - Supported Models: https://docs.github.com/en/copilot/reference/ai-models/supported-models
 *
 * Usage: node scripts/sync-models.js
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dump, load } from "js-yaml";

// Import parsing utilities from the separate module
import {
	DOCS_URLS,
	fetchWithRetry,
	inferModes,
	inferMultiplier,
	inferPricingTier,
	inferProvider,
	inferStatus,
	parseModelComparison,
} from "./parse-model-docs.js";

const MODELS_YAML_PATH = "src/tools/config/models.yaml";

/**
 * Update or add a model in the models array
 */
function updateModel(existingModels, newModelData) {
	const existingIndex = existingModels.findIndex(
		(m) => m.name === newModelData.name,
	);

	if (existingIndex >= 0) {
		// Merge with existing model, preserving manually curated fields
		const existing = existingModels[existingIndex];
		existingModels[existingIndex] = {
			...existing,
			...newModelData,
			// Preserve manually curated fields
			contextTokens: existing.contextTokens,
			baseScore: existing.baseScore,
			capabilities: existing.capabilities,
			strengths: existing.strengths,
			limitations: existing.limitations,
			specialFeatures: existing.specialFeatures,
			pricing: existing.pricing,
			pricingTier: existing.pricingTier,
		};
		return "updated";
	} else {
		// New model - add with default values
		existingModels.push({
			name: newModelData.name,
			provider: newModelData.provider,
			pricingTier: inferPricingTier(
				newModelData.taskArea,
				newModelData.multiplier,
			),
			contextTokens: 128000, // Default
			baseScore: 50, // Default
			capabilities: ["code"],
			strengths: [newModelData.excelsAt],
			limitations: ["Requires validation"],
			specialFeatures: newModelData.additionalCapabilities
				.split(",")
				.map((s) => s.trim())
				.filter(Boolean),
			pricing: "To be determined",
			modes: newModelData.modes,
			taskArea: newModelData.taskArea,
			multiplier: newModelData.multiplier,
			status: newModelData.status,
			documentationUrl: newModelData.documentationUrl,
		});
		return "added";
	}
}

/**
 * Main sync function
 */
async function main() {
	console.log(
		"🔄 Starting AI model sync from GitHub Copilot documentation...\n",
	);

	try {
		// Fetch documentation pages
		const comparisonHtml = await fetchWithRetry(DOCS_URLS.comparison);
		console.log("✅ Fetched model comparison page\n");

		// Parse model data
		const parsedModels = parseModelComparison(comparisonHtml);
		console.log(`📊 Found ${parsedModels.length} models in documentation\n`);

		if (parsedModels.length === 0) {
			console.log(
				"⚠️  No models found in documentation. Exiting without changes.",
			);
			process.exit(0);
		}

		// Load current models.yaml
		console.log("📖 Loading current models.yaml...");
		const yamlContent = readFileSync(MODELS_YAML_PATH, "utf8");
		const currentYaml = load(yamlContent);

		if (!currentYaml.models || !Array.isArray(currentYaml.models)) {
			throw new Error("Invalid models.yaml structure");
		}

		// Process each parsed model
		const changes = { added: [], updated: [], unchanged: [] };

		for (const parsedModel of parsedModels) {
			const provider = inferProvider(parsedModel.name);
			const modes = inferModes(
				parsedModel.additionalCapabilities,
				parsedModel.name,
			);
			const multiplier = inferMultiplier(
				parsedModel.name,
				parsedModel.taskArea,
			);
			const status = inferStatus(
				parsedModel.name,
				parsedModel.additionalCapabilities,
			);

			const modelData = {
				name: parsedModel.name,
				provider,
				modes,
				taskArea: parsedModel.taskArea,
				multiplier,
				status,
				documentationUrl: parsedModel.documentationUrl,
				excelsAt: parsedModel.excelsAt,
				additionalCapabilities: parsedModel.additionalCapabilities,
			};

			const result = updateModel(currentYaml.models, modelData);

			if (result === "added") {
				changes.added.push(parsedModel.name);
			} else if (result === "updated") {
				changes.updated.push(parsedModel.name);
			} else {
				changes.unchanged.push(parsedModel.name);
			}
		}

		// Update last updated timestamp
		currentYaml.lastUpdated = new Date().toISOString().split("T")[0];

		// Write updated YAML
		console.log("\n💾 Writing updated models.yaml...");
		const yamlOutput = dump(currentYaml, {
			lineWidth: -1, // Don't wrap lines
			noRefs: true,
			sortKeys: false,
		});

		writeFileSync(MODELS_YAML_PATH, yamlOutput, "utf8");

		// Report changes
		console.log("\n✅ Sync complete!\n");
		console.log("📈 Summary:");
		console.log(`   - Added: ${changes.added.length} models`);
		console.log(`   - Updated: ${changes.updated.length} models`);
		console.log(`   - Unchanged: ${changes.unchanged.length} models`);

		if (changes.added.length > 0) {
			console.log("\n➕ Added models:");
			for (const name of changes.added) {
				console.log(`   - ${name}`);
			}
		}

		if (changes.updated.length > 0) {
			console.log("\n📝 Updated models:");
			for (const name of changes.updated) {
				console.log(`   - ${name}`);
			}
		}

		// Exit code indicates if changes were made
		const hasChanges = changes.added.length > 0 || changes.updated.length > 0;
		process.exit(hasChanges ? 0 : 0); // Always exit 0 - changes detected via git diff
	} catch (error) {
		console.error("\n❌ Error syncing models:", error.message);
		console.error(error.stack);
		process.exit(1);
	}
}

// Run if called directly
if (import.meta.url === `file://${process.argv[1]}`) {
	main();
}

#!/usr/bin/env node

/**
 * Update Issue Numbers in Markdown Files
 *
 * Updates all #TBD placeholders with pre-calculated issue numbers:
 * - Parent headers in sub-issues
 * - Table entries in parent issues
 *
 * Usage:
 *   node scripts/update-issue-numbers.js [--dry-run]
 */

import { promises as fs } from "node:fs";
import { join } from "node:path";

const ISSUES_DRAFT_DIR = "plan-v0.13.x/issues-draft";
const MAPPING_FILE = "artifacts/issue-number-mapping.json";

// Parse command line arguments
const args = process.argv.slice(2);
const dryRun = args.includes("--dry-run");

/**
 * Load pre-calculated mapping
 */
async function loadMapping() {
	try {
		const content = await fs.readFile(MAPPING_FILE, "utf-8");
		return JSON.parse(content);
	} catch {
		console.error(`❌ Failed to load mapping file: ${MAPPING_FILE}`);
		console.error("   Run: node scripts/pre-calculate-issue-numbers.js first");
		process.exit(1);
	}
}

/**
 * Update Parent header in sub-issue file
 */
async function updateSubIssueParent(filename, mapping) {
	const filePath = join(ISSUES_DRAFT_DIR, filename);
	const content = await fs.readFile(filePath, "utf-8");

	// Determine parent file based on phase
	const phase = filename.match(/^p(\d+)-/)?.[1];
	if (!phase) {
		console.warn(`⚠️  Skipping ${filename}: Cannot determine phase`);
		return false;
	}

	const parentFilename = Object.keys(mapping.parents).find((f) =>
		f.startsWith(`00${phase}-parent-`),
	);

	if (!parentFilename) {
		console.warn(`⚠️  Skipping ${filename}: No parent found for phase ${phase}`);
		return false;
	}

	const parentIssueNumber = mapping.parents[parentFilename];

	// Check if file has Parent header
	if (content.includes("> **Parent**:")) {
		// Update existing Parent header
		const updated = content.replace(
			/> \*\*Parent\*\*:.*/,
			`> **Parent**: #${parentIssueNumber}`,
		);

		if (!dryRun) {
			await fs.writeFile(filePath, updated);
		}
		console.log(`  ✅ ${filename} → Parent: #${parentIssueNumber}`);
		return true;
	}

	// Add Parent header after title (line 3)
	const lines = content.split("\n");
	lines.splice(2, 0, `> **Parent**: #${parentIssueNumber}`);
	const updated = lines.join("\n");

	if (!dryRun) {
		await fs.writeFile(filePath, updated);
	}
	console.log(`  ➕ ${filename} → Added Parent: #${parentIssueNumber}`);
	return true;
}

/**
 * Update table in parent issue file
 */
async function updateParentTable(filename, mapping) {
	const filePath = join(ISSUES_DRAFT_DIR, filename);
	let content = await fs.readFile(filePath, "utf-8");

	// Extract phase number
	const phase = filename.match(/^00(\d)-parent-/)?.[1];
	if (!phase) {
		console.warn(`⚠️  Skipping ${filename}: Cannot determine phase`);
		return false;
	}

	let updated = false;

	// Find all table rows with #TBD and task IDs
	const tableRowRegex = /\|\s*(\d+)\s*\|\s*#TBD\s*\|\s*(P\d+-\d+)\s*\|/g;

	content = content.replace(tableRowRegex, (match, _rowNum, taskId) => {
		const issueNumber = mapping.taskIds[taskId];
		if (issueNumber) {
			updated = true;
			return match.replace("#TBD", `#${issueNumber}`);
		}
		console.warn(`⚠️  No mapping found for ${taskId} in ${filename}`);
		return match;
	});

	if (updated && !dryRun) {
		await fs.writeFile(filePath, content);
	}

	if (updated) {
		console.log(`  ✅ ${filename} → Updated table with issue numbers`);
	}

	return updated;
}

async function main() {
	console.log("📝 Updating Issue Numbers in Files\n");

	if (dryRun) {
		console.log("🔍 DRY RUN MODE - No files will be modified\n");
	}

	// Load mapping
	const mapping = await loadMapping();
	console.log(
		`📋 Loaded mapping (calculated ${new Date(mapping.calculatedAt).toLocaleString()})\n`,
	);

	// Update sub-issue Parent headers
	console.log("📋 Updating Sub-Issue Parent Headers:");
	const subIssueFiles = Object.keys(mapping.subIssues);
	let subIssuesUpdated = 0;

	for (const filename of subIssueFiles) {
		const success = await updateSubIssueParent(filename, mapping);
		if (success) subIssuesUpdated++;
	}

	// Update parent issue tables
	console.log("\n📋 Updating Parent Issue Tables:");
	const parentFiles = Object.keys(mapping.parents);
	let parentsUpdated = 0;

	for (const filename of parentFiles) {
		const success = await updateParentTable(filename, mapping);
		if (success) parentsUpdated++;
	}

	console.log(`\n✨ ${dryRun ? "Would update" : "Updated"}:`);
	console.log(`   Sub-issues: ${subIssuesUpdated}/${subIssueFiles.length}`);
	console.log(`   Parents: ${parentsUpdated}/${parentFiles.length}`);

	if (dryRun) {
		console.log("\n📝 Run without --dry-run to apply changes");
	} else {
		console.log("\n📝 Next steps:");
		console.log("   1. Review changes: git diff plan-v0.13.x/issues-draft/");
		console.log(
			'   2. Commit changes: git add . && git commit -m "Pre-populate issue numbers"',
		);
		console.log("   3. Create issues: node scripts/create-all-issues.js");
	}
}

main().catch(console.error);

#!/usr/bin/env node

/**
 * Update Parent References in Sub-Issue Files
 *
 * After parent issues are created, replace #TBD with actual parent issue numbers.
 *
 * Usage:
 *   node scripts/update-parent-refs.js --mapping artifacts/parent-mapping.json
 */

import { promises as fs } from "node:fs";
import { join } from "node:path";

const ISSUES_DRAFT_DIR = "plan-v0.13.x/issues-draft";

// Parse command line arguments
const args = process.argv.slice(2);
const mappingFile =
	args.find((a) => a.startsWith("--mapping="))?.split("=")[1] ||
	"artifacts/parent-mapping.json";

/**
 * Load parent issue mapping
 * Format: { "001-parent-phase1-discoverability.md": 617, ... }
 */
async function loadParentMapping() {
	try {
		const content = await fs.readFile(mappingFile, "utf-8");
		return JSON.parse(content);
	} catch (error) {
		console.error(`❌ Failed to load mapping file: ${mappingFile}`);
		console.error(error.message);
		process.exit(1);
	}
}

/**
 * Update Parent header in a file
 */
async function updateParentHeader(filePath, parentIssueNumber) {
	const content = await fs.readFile(filePath, "utf-8");
	const lines = content.split("\n");

	// Find Parent header line
	const parentLineIndex = lines.findIndex((line) =>
		line.match(/^> \*\*Parent\*\*:/),
	);

	if (parentLineIndex === -1) {
		console.warn(`⚠️  No Parent header found in ${filePath}`);
		return false;
	}

	// Extract parent filename from comment
	const commentMatch = lines[parentLineIndex].match(/<!-- (.+?) -->/);
	if (!commentMatch) {
		console.warn(`⚠️  No parent filename comment in ${filePath}`);
		return false;
	}

	// Replace #TBD with actual issue number
	lines[parentLineIndex] =
		`> **Parent**: #${parentIssueNumber} <!-- ${commentMatch[1]} -->`;

	await fs.writeFile(filePath, lines.join("\n"));
	return true;
}

async function main() {
	console.log("📝 Updating Parent References in Sub-Issue Files\n");

	// Load parent mapping
	const parentMapping = await loadParentMapping();
	console.log(
		`📋 Loaded ${Object.keys(parentMapping).length} parent issue mappings\n`,
	);

	// Get all sub-issue files
	const files = await fs.readdir(ISSUES_DRAFT_DIR);
	const subIssueFiles = files
		.filter((f) => f.match(/^p\d+-\d+-sub-.+\.md$/))
		.sort();

	console.log(`Found ${subIssueFiles.length} sub-issue files\n`);

	let updated = 0;
	let skipped = 0;

	for (const file of subIssueFiles) {
		const filePath = join(ISSUES_DRAFT_DIR, file);
		const content = await fs.readFile(filePath, "utf-8");

		// Extract parent filename from comment
		const parentMatch = content.match(/> \*\*Parent\*\*:.*<!-- (.+?) -->/);
		if (!parentMatch) {
			console.warn(`⚠️  Skipping ${file}: No parent comment found`);
			skipped++;
			continue;
		}

		const parentFilename = parentMatch[1];
		const parentIssueNumber = parentMapping[parentFilename];

		if (!parentIssueNumber) {
			console.warn(
				`⚠️  Skipping ${file}: Parent ${parentFilename} not in mapping`,
			);
			skipped++;
			continue;
		}

		const success = await updateParentHeader(filePath, parentIssueNumber);
		if (success) {
			console.log(`✅ Updated ${file} → Parent: #${parentIssueNumber}`);
			updated++;
		} else {
			skipped++;
		}
	}

	console.log(`\n✨ Done!`);
	console.log(`   Updated: ${updated} files`);
	console.log(`   Skipped: ${skipped} files`);
}

main().catch(console.error);

