	if (yValues.length > 0) {
		const min = Math.min(...yValues);
		const max = Math.max(...yValues);
		const avg = yValues.reduce((a, b) => a + b, 0) / yValues.length;
		const sorted = [...yValues].sort((a, b) => a - b);
