#!/usr/bin/env node

import fs from "node:fs";
import path from "node:path";

const thresholds = {
	lines: 87,
	functions: 80, // Lower due to untestable inline arrow functions and resolveWebviewView
	branches: 87,
	statements: 87,
};

// Note: codecov.yml targets 90% but ~2-3% is effectively untestable:
// - resolveWebviewView methods in src/providers/DataPreviewProvider.ts and
//   src/providers/ChartViewProvider.ts require a live VS Code webview context
// - Inline arrow functions used as dependency factories in src/extension.ts and
//   src/commands/dataCommands.ts are only invoked by VS Code at runtime
// - Some panel creation "else" branches in src/providers/DataPreviewProvider.ts and
//   src/providers/ChartViewProvider.ts are not hit by vscode-test due to coverage
//   instrumentation quirks
// For a detailed breakdown of these exclusions, see docs/TESTING_COVERAGE.md.

const summaryPath = path.resolve(process.cwd(), "coverage", "coverage-summary.json");

if (!fs.existsSync(summaryPath)) {
	console.error(
		`Coverage summary not found at ${summaryPath}. Did the coverage run complete successfully?`,
	);
	process.exit(1);
}

let summary;
try {
	summary = JSON.parse(fs.readFileSync(summaryPath, "utf8"));
} catch (_error) {
	console.error(
		`Unable to read coverage summary: ${error instanceof Error ? _error.message : error}`,
	);
	process.exit(1);
}

const totals = summary.total;
if (!totals) {
	console.error("Coverage summary is missing total metrics.");
	process.exit(1);
}

let hasFailure = false;

for (const [metric, min] of Object.entries(thresholds)) {
	const stats = totals[metric];
	if (!stats) {
		console.error(`Coverage summary does not contain '${metric}' metrics.`);
		hasFailure = true;
		continue;
	}

	const pct = typeof stats.pct === "number" ? stats.pct : Number.NaN;
	if (!Number.isFinite(pct)) {
		console.error(`Coverage percentage for '${metric}' is not a number.`);
		hasFailure = true;
		continue;
	}

	if (pct + 1e-9 < min) {
		console.error(`Coverage for ${metric} (${pct.toFixed(2)}%) is below the required ${min}%.`);
		hasFailure = true;
	}
}

if (hasFailure) {
	process.exit(1);
}

console.log(
	"Coverage thresholds met:",
